def _fused_moe_projection_n(shape, variant):
    widths = {
        "w1": 2 * shape["intermediate"],
        "w2": shape["hidden"],
    }
    if variant not in widths:
        raise ValueError(f"unsupported grouped-MoE role: {variant!r}")
    return widths[variant]


class _TypedServiceResource:
    def __init__(self, services):
        self.services = frozenset(services)

    def has_typed_service(self, service):
        return service in self.services


class _TypedServiceHardware:
    def __init__(self, base, services):
        self._base = base
        self._resource = _TypedServiceResource(services)
        self._role_map = {"compute_vector": self._resource}
        self.add_rmsnorm_source_round_pipeline = None

    def resource_by_role(self, role):
        assert role == "compute_vector"
        return self._resource

    def __getattr__(self, name):
        return getattr(self._base, name)


def _a800_block256_add_rms_services():
    return {
        f"bf16_{function}_{regime}_256_block256"
        for function in ("add_square", "scale_multiply")
        for regime in ("first", "resident")
    }


def test_a800_add_rms_typed_round_gate_uses_exact_launch_subset():
    hardware = _TypedServiceHardware(
        HARDWARE, _a800_block256_add_rms_services())
    launch = _select_launch_config(
        "nvidia_a800", KernelKind.VECTOR,
        {"rows": 256, "hidden": 4096}, "bf16", "add_rmsnorm", {},
        hardware=HARDWARE)
    kernel = KernelSpec(
        KernelKind.VECTOR, "nvidia_a800", {"rows": 256, "hidden": 4096},
        dtype="bf16", variant="add_rmsnorm", launch=launch)

    assert _has_typed_add_rms_round_services(kernel, hardware)


