def test_a800_block256_add_rms_pipeline_composes_resident_ctas():
    shape = {"rows": 256, "hidden": 4096}
    launch = _select_launch_config(
        "nvidia_a800", KernelKind.VECTOR, shape, "bf16", "add_rmsnorm", {},
        hardware=HARDWARE)
    kernel = KernelSpec(
        KernelKind.VECTOR, "nvidia_a800", shape, dtype="bf16",
        variant="add_rmsnorm", launch=launch)

    resource_input, _ = create_predictor(
        kernel.kind).resource_input(kernel, HARDWARE)
    vector_demand = next(
        demand for demand in resource_input.compute_demands
        if demand.resource_role == "compute_vector")
    service_names = {
        demand.service for demand in vector_demand.service_demands}

    assert resource_input.pipeline_plan is not None
    assert resource_input.demand_per_resource["compute_fma"] == 0.0
    assert resource_input.demand_per_resource["compute_alu"] == 0.0
    assert service_names == _a800_block256_add_rms_services()
    programs = resource_input.pipeline_plan.tasks
    assert len(programs) == 2
    assert all(isinstance(program, PipelineTaskProgramDemand)
               for program in programs)
    assert sorted(program.worker_multiplicity for program in programs) == [
        40, 68]
    assert tuple(sorted(
        worker
        for program in programs
        for worker in program.physical_workers)) == tuple(range(108))
    assert resource_input.resident_cta_cohort_refills is None


