def test_a800_h4096_add_rms_pipeline_reuses_cta_local_source_service():
    shape = {"rows": 64, "hidden": 4096}
    launch = _select_launch_config(
        "nvidia_a800", KernelKind.VECTOR, shape, "bf16", "add_rmsnorm", {},
        hardware=HARDWARE)
    kernel = KernelSpec(
        KernelKind.VECTOR, "nvidia_a800", shape, dtype="bf16",
        variant="add_rmsnorm", launch=launch)

    resource_input, _ = create_predictor(
        kernel.kind).resource_input(kernel, HARDWARE)
    vector_demand = next(
        demand for demand in resource_input.compute_demands
        if demand.resource_role == "compute_vector")
    services = {
        demand.service: demand.operations
        for demand in vector_demand.service_demands}
    issue_demand, = (
        demand for demand in resource_input.compute_demands
        if demand.resource_role == "warp_issue")
    worker_class, = resource_input.pipeline_plan.tasks
    task, = worker_class.patterns[0].tasks
    stages = {stage.name: stage for stage in task.stages}
    assert services == {
        "bf16_add_square_first_512_block1024": 64.0,
        "bf16_scale_multiply_first_512_block1024": 64.0,
    }
    assert issue_demand.operations == 64 * 16 * 22
    assert resource_input.demand_per_resource["warp_issue"] == (
        issue_demand.operations)
    assert worker_class.worker_multiplicity == 64
    assert stages["cta0_source_prologue"].work_fraction == pytest.approx(
        1 / 64)
    assert stages["cta0_add_square_0"].predecessors == (
        "cta0_source_prologue",)
    input_phase = next(
        phase for phase in resource_input.phase_ledger.phases
        if phase.name == "input_compute")
    assert (
        PhaseComputeDemand(
            "warp_issue", "add_rmsnorm_non_loop_prologue", 64 * 16 * 22)
        in input_phase.compute_demands)
    assert not any(
        demand.operation == "add_rmsnorm_cold_source_chain_entry"
        for demand in input_phase.compute_demands)


