def _kernel(kind, shape, *, variant=None, attributes=None):
    attributes = {} if attributes is None else dict(attributes)
    if kind is KernelKind.GEMM:
        attributes["launch_policy"] = "analytical_launch"
    elif kind is KernelKind.FLASH_ATTN:
        attributes["split_policy"] = "serving"
    launch = select_launch_config(
        HARDWARE.hardware_id,
        kind,
        shape,
        "bf16",
        variant,
        attributes,
        hardware=HARDWARE,
    )
    if kind is KernelKind.FLASH_ATTN:
        prediction_attributes = {
            "causal": False,
            "kv_layout": attributes["kv_layout"],
            "kv_dist": "uniform",
            "q_lens": (shape["q_len"],) * shape["batch"],
            "kv_lens": (shape["kv_len"],) * shape["batch"],
            "fa_ksteps": None,
            "fa_eff_mfrac": 1.0,
        }
    elif kind is KernelKind.GEMM:
        prediction_attributes = {}
    else:
        raise AssertionError(f"unsupported traffic-test kernel kind: {kind!r}")
    return KernelSpec(
        kind,
        HARDWARE.hardware_id,
        shape,
        dtype="bf16",
        variant=variant,
        launch=launch,
        attributes=prediction_attributes,
    )


def _demand(kernel):
    resource_input, _ = create_predictor(kernel.kind).resource_input(
        kernel, HARDWARE)
    return resource_input.demand_per_resource


def _resource_input(kernel):
    resource_input, _ = create_predictor(kernel.kind).resource_input(
        kernel, HARDWARE)
    return resource_input


def _resource_input_for(kernel, hardware):
    resource_input, _ = create_predictor(kernel.kind).resource_input(
        kernel, hardware)
    return resource_input


def test_vector_roofline_uses_compact_forward_representation(monkeypatch):
    kernel = object()
    hardware = object()
    calls = []
    resource_input = SimpleNamespace(demand_per_resource={"dram": 3.0})

    monkeypatch.setattr(
        vector_predictor, "forward_analytical_resource_input",
        lambda received_kernel, received_hardware: (
            calls.append((received_kernel, received_hardware))
            or (resource_input, 7.0)))
    monkeypatch.setattr(
        vector_predictor, "roofline_ns",
        lambda demand, received_hardware, compulsory: (
            11.0 if (demand == resource_input.demand_per_resource
                     and received_hardware is hardware and compulsory == 7.0)
            else (_ for _ in ()).throw(AssertionError("unexpected roofline input"))))

    prediction = vector_predictor.VectorPredictor().roofline(kernel, hardware)

    assert calls == [(kernel, hardware)]
    assert prediction.t_total_ns == 11.0


def _expand_pipeline_work_plan(plan):
    """Expand a compact demand plan for schedule-equivalence tests only."""

    explicit_tasks = []

    def append_task(task, worker):
        for _ in range(task.repeat_count):
            explicit_tasks.append(dataclasses.replace(
                task,
                name=f"explicit_task{len(explicit_tasks)}",
                worker=worker,
                repeat_count=1,
            ))

    def append_sequence(sequence, worker):
        for _ in range(sequence.repeat_count):
            explicit_tasks.append(PipelineTaskSequenceDemand(
                name=f"explicit_sequence{len(explicit_tasks)}",
                worker=worker,
                tasks=tuple(dataclasses.replace(task, worker=worker)
                            for task in sequence.tasks),
            ))

    has_worker_classes = any(
        isinstance(entry, PipelineTaskProgramDemand)
        and entry.worker_multiplicity > 1
        for entry in plan.tasks)
    if has_worker_classes:
        assert all(
            isinstance(entry, PipelineTaskProgramDemand)
            for entry in plan.tasks)
        assert sum(
            entry.worker_multiplicity for entry in plan.tasks
        ) == plan.worker_count
    expanded_worker = 0
    for entry in plan.tasks:
        if isinstance(entry, PipelineTaskDemand):
            append_task(entry, entry.worker)
        elif isinstance(entry, PipelineTaskSequenceDemand):
            append_sequence(entry, entry.worker)
        elif isinstance(entry, PipelineTaskProgramDemand):
            workers = (
                (entry.physical_workers or range(
                    expanded_worker,
                    expanded_worker + entry.worker_multiplicity))
                if has_worker_classes else (entry.worker,))
            for worker in workers:
                for _ in range(entry.repeat_count):
                    for pattern_index in entry.order:
                        append_sequence(entry.patterns[pattern_index], worker)
                for pattern_index in entry.tail_order:
                    append_sequence(entry.patterns[pattern_index], worker)
            if has_worker_classes:
                expanded_worker += entry.worker_multiplicity
        else:
            raise AssertionError(
                f"unexpected pipeline task type: {type(entry).__name__}")
    return PipelineWorkPlan(
        worker_count=plan.worker_count,
        tasks=tuple(explicit_tasks),
        buffers=plan.buffers,
    )


def _assert_compact_formula_matches_explicit(resource_input, hardware):
    compact_plan = resource_input.pipeline_plan
    assert compact_plan is not None
    explicit_input = dataclasses.replace(
        resource_input,
        pipeline_plan=_expand_pipeline_work_plan(compact_plan),
    )
    formula = PerformanceFormula(hardware)
    compact = formula.predict_kernel(resource_input)
    explicit = formula.predict_kernel(explicit_input)
    assert compact.t_total_s == pytest.approx(explicit.t_total_s, rel=1e-12)
    compact_pipeline = compact.diagnostics.pipeline
    explicit_pipeline = explicit.diagnostics.pipeline
    assert compact_pipeline is not None
    assert explicit_pipeline is not None
    assert compact_pipeline.execution_time_s == pytest.approx(
        explicit_pipeline.execution_time_s, rel=1e-12)
    assert compact_pipeline.initiation_interval_s == pytest.approx(
        explicit_pipeline.initiation_interval_s, rel=1e-12)
    if any(
            isinstance(entry, PipelineTaskProgramDemand)
            and entry.physical_workers
            for entry in compact_plan.tasks):
        assert compact_pipeline.worker_makespan_s == pytest.approx(
            explicit_pipeline.worker_makespan_s, rel=1e-12)
    elif any(
            isinstance(entry, PipelineTaskProgramDemand)
            and entry.worker_multiplicity > 1
            for entry in compact_plan.tasks):
        compact_makespans = sorted(
            compact_pipeline.worker_makespan_s[str(entry.worker)]
            for entry in compact_plan.tasks
            for _ in range(entry.worker_multiplicity)
        )
        assert compact_makespans == pytest.approx(
            sorted(explicit_pipeline.worker_makespan_s.values()), rel=1e-12)
    else:
        assert compact_pipeline.worker_makespan_s == pytest.approx(
            explicit_pipeline.worker_makespan_s, rel=1e-12)
    assert compact_pipeline.stage_service_s == pytest.approx(
        explicit_pipeline.stage_service_s, rel=1e-12)


def _tiled_flash_attention_kernel(
        *, batch, q_len, kv_len, query_heads, kv_heads,
        q_lens, kv_lens, causal):
    tile_q = 64
    tile_kv = 128
    head_dim = 128
    launch = LaunchConfig(
        algorithm="vllm_flash_attn_splitkv",
        grid=(math.ceil(q_len / tile_q), batch, query_heads),
        block=(128, 1, 1),
        tiling=TilingSpec(
            tile_shape={"q": tile_q, "kv": tile_kv, "head": head_dim},
            num_kv_splits=1,
        ),
        parameters={
            "unpadded_flops": 0.0,
            "mma_smem_bytes_per_flop": 0.125,
            "split_scratch_dram_bytes_per_element": 0.0,
            "page_table_bytes_per_kv_panel": 0.0,
        },
        execution_variant="prefill",
    )
    return KernelSpec(
        KernelKind.FLASH_ATTN,
        HARDWARE.hardware_id,
        {
            "batch": batch,
            "q_len": q_len,
            "kv_len": kv_len,
            "head_dim": head_dim,
            "num_query_heads": query_heads,
            "num_kv_heads": kv_heads,
        },
        dtype="bf16",
        variant="prefill",
        launch=launch,
        attributes={
            "causal": causal,
            "kv_layout": "paged",
            "kv_dist": "uniform",
            "q_lens": q_lens,
            "kv_lens": kv_lens,
            "fa_ksteps": None,
            "fa_eff_mfrac": 1.0,
        },
    )


def _observed_flash_attention_kernel(
        hardware, *, algorithm, grid, block, tile_shape, splits, batch, q_len, kv_len,
        head_dim, query_heads, kv_heads, q_lens, kv_lens, causal, kv_layout,
        variant, shared_memory_bytes=None, registers_per_thread=None):
    del shared_memory_bytes, registers_per_thread
    launch = LaunchConfig(
        algorithm=algorithm,
        grid=grid,
        block=block,
        tiling=TilingSpec(
            tile_shape=tile_shape,
            num_kv_splits=splits,
        ),
        parameters={
            "unpadded_flops": 0.0,
            "mma_smem_bytes_per_flop": 0.0,
            "split_scratch_dram_bytes_per_element": 0.0,
            "page_table_bytes_per_kv_panel": 0.0,
        },
        execution_variant=variant,
    )
    return KernelSpec(
        KernelKind.FLASH_ATTN,
        hardware.hardware_id,
        {
            "batch": batch,
            "q_len": q_len,
            "kv_len": kv_len,
            "head_dim": head_dim,
            "num_query_heads": query_heads,
            "num_kv_heads": kv_heads,
        },
        dtype="bf16",
        variant=variant,
        launch=launch,
        attributes={
            "causal": causal,
            "kv_layout": kv_layout,
            "kv_dist": "skew",
            "q_lens": q_lens,
            "kv_lens": kv_lens,
            "fa_ksteps": None,
            "fa_eff_mfrac": 1.0,
        },
    )


def _metax_tile16_flash_attention_kernel(
        *, kv_lens=(128, 512), kv_layout="paged_varlen",
        tile_q=16, tile_kv=16, block_size=64, splits=1, q_len=1,
        algorithm="observed_flash_attention:decode"):
    batch = len(kv_lens)
    q_lens = (q_len,) * batch
    query_heads = 64
    kv_heads = 8
    head_groups = kv_heads if q_len == 1 else query_heads
    query_tiles = sum(math.ceil(length / tile_q) for length in q_lens)
    grid_size = query_tiles * head_groups * splits
    variant = "decode" if q_len == 1 else "prefill"
    if variant == "decode" and tile_q == 16 and tile_kv == 16:
        if splits == 1 and kv_layout in ("paged", "paged_varlen"):
            grid = (kv_heads, batch, 1)
        elif splits > 1 and kv_layout == "contiguous":
            grid = (1, batch * kv_heads, splits)
        else:
            grid = (grid_size, 1, 1)
    else:
        grid = (grid_size, 1, 1)
    return _observed_flash_attention_kernel(
        METAX_HARDWARE,
        algorithm=algorithm,
        grid=grid,
        block=(block_size, 1, 1),
        tile_shape={"q": tile_q, "kv": tile_kv, "head": 128},
        splits=splits,
        batch=batch,
        q_len=q_len,
        kv_len=max(kv_lens),
        head_dim=128,
        query_heads=query_heads,
        kv_heads=kv_heads,
        q_lens=q_lens,
        kv_lens=kv_lens,
        causal=False,
        kv_layout=kv_layout,
        variant=variant,
    )


