    def test_ascend_warm_operand_context_replays_shared_lru_without_shape_key(
            self, monkeypatch):
        program = CannGemmLaunchProgram(
            program_kind="cann_gemm_launch_v1",
            aic_workers=1,
            worker_grid_m=1,
            worker_grid_n=1,
            worker_grid_k=1,
            single_core_m=16,
            single_core_n=64,
            single_core_k=64,
            base_m=16,
            base_n=64,
            base_k=64,
            depth_a1=1,
            depth_b1=1,
            a_l1_k_tiles=1,
            b_l1_k_tiles=1,
            step_m=1,
            step_n=1,
            m_l2_regions=1,
            n_l2_regions=1,
            m_l2_block=1,
            n_l2_block=1,
            traversal_order="persistent_n_then_m",
            a_uses_l2=True,
            b_uses_l2=True,
            split_k=1,
        )
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            {"b": 1, "m": 1, "n": 64, "k": 64, "dtype_bytes": 2},
            dtype="bf16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="ascend_cann_matmul",
                grid=(1, 1, 1),
                block=(1, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 16, "n": 64, "k": 64},
                    pipeline_depth=1,
                    split_k=1,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
                source_program=program,
            ),
        )
        cold = gemm_predictor._cann_gemm_persistent_operand_traffic(
            kernel, ASCEND_HARDWARE)
        warm = gemm_predictor._cann_gemm_persistent_operand_traffic(
            dataclasses.replace(
                kernel,
                l2_execution_context=L2ExecutionContext(
                    same_program_operand_replays=5),
            ),
            ASCEND_HARDWARE,
        )

        assert cold is not None
        assert warm is not None
        assert cold.a_dram_bytes + cold.b_dram_bytes > 0
        assert warm.a_dram_bytes == 0
        assert warm.b_dram_bytes == 0
        assert warm.a_l2_bytes == cold.a_l2_bytes
        assert warm.b_l2_bytes == cold.b_l2_bytes
        assert warm.dirty_writeback_bytes == cold.dirty_writeback_bytes

        cold_kernel = kernel
        warm_kernel = dataclasses.replace(
            kernel,
            l2_execution_context=L2ExecutionContext(
                same_program_operand_replays=5),
        )
        predictor = create_predictor(KernelKind.GEMM)
        model_calls = []
        original_model = gemm_predictor._model

        def record_model_call(kernel_arg, hardware_arg, **kwargs):
            model_calls.append(kwargs["cold_traffic"])
            return original_model(kernel_arg, hardware_arg, **kwargs)

        monkeypatch.setattr(gemm_predictor, "_model", record_model_call)
        predictor.midlayer(warm_kernel, ASCEND_HARDWARE)
        assert model_calls[-1] is False
        cold_input, _ = predictor.resource_input(
            cold_kernel, ASCEND_HARDWARE)
        warm_input, _ = predictor.resource_input(
            warm_kernel, ASCEND_HARDWARE)
        assert model_calls[-2:] == [False, False]
        assert warm_input.demand_per_resource != (
            cold_input.demand_per_resource)
        cold_forward, _ = predictor.forward_resource_input(
            cold_kernel, ASCEND_HARDWARE)
        warm_forward, _ = predictor.forward_resource_input(
            warm_kernel, ASCEND_HARDWARE)
        assert model_calls[-2:] == [True, True]
        assert warm_forward.demand_per_resource == (
            cold_forward.demand_per_resource)

    @pytest.mark.parametrize(
        ("shape", "expected_traffic"),
        (
            (
                {"b": 1, "m": 512, "n": 5120, "k": 5120},
                gemm_predictor.GemmSourceOrderTraffic(
                    l2_bytes=367_001_600,
                    dram_bytes=125_829_120,
                    a_l2_bytes=251_658_240,
                    a_dram_bytes=5_242_880,
                    b_l2_bytes=110_100_480,
                    b_dram_bytes=52_428_800,
                    output_l2_bytes=5_242_880,
                    dirty_writeback_bytes=68_157_440,
                    predecessor_dirty_writeback_bytes=62_914_560,
                ),
            ),
        ),
    )
    def test_ascend_persistent_program_replays_shared_lru_once(
            self, shape, expected_traffic):
        attributes = {
            "a_layout": "row_major",
            "b_layout": "row_major",
            "c_layout": "row_major",
            "trans_a": False,
            "trans_b": True,
            "epilogue": "none",
            "has_bias": False,
            "position": "qkv_proj",
            "tensor_parallel_size": 1,
            "expert_parallel_size": 1,
            "launch_policy": "injected_launch",
        }
        launch = _select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.GEMM,
            shape, "bf16", "gemm", attributes, ASCEND_HARDWARE)
        kernel = KernelSpec(
            kind=KernelKind.GEMM,
            hardware_id=ASCEND_HARDWARE.hardware_id,
            shape={**shape, "dtype_bytes": 2},
            dtype="bf16",
            variant="gemm",
            launch=launch,
        )

        traffic = gemm_predictor._cann_gemm_persistent_operand_traffic(
            kernel, ASCEND_HARDWARE,
            predecessor_dirty_bytes=int(
                ASCEND_HARDWARE.l2_replacement_capacity_bytes))
        assert traffic == expected_traffic
        assert traffic.l2_bytes == (
            traffic.a_l2_bytes + traffic.b_l2_bytes
            + traffic.output_l2_bytes)
        assert traffic.dram_bytes == (
            traffic.a_dram_bytes + traffic.b_dram_bytes
            + traffic.dirty_writeback_bytes)
        program = launch.source_program
        geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            kernel, ASCEND_HARDWARE)
        assert geometry is not None
        assert geometry.worker_count == program.aic_workers
        assert geometry.worker_m_tiles == (
            program.single_core_m // program.base_m)
        assert geometry.worker_n_tiles == (
            program.single_core_n // program.base_n)
        assert geometry.a_l1_k_tiles == program.a_l1_k_tiles
        assert geometry.b_l1_k_tiles == program.b_l1_k_tiles
        assert geometry.a_descriptor_bytes == (
            program.base_m * program.step_m * program.a_l1_k_tiles
            * program.base_k * kernel.shape["dtype_bytes"])
        assert geometry.b_descriptor_bytes == (
            program.base_n * program.step_n * program.b_l1_k_tiles
            * program.base_k * kernel.shape["dtype_bytes"])

