        assignments = cann_gemm_source_tile_assignments(
            256, 112,
            program.m_l2_regions, program.n_l2_regions,
            program.m_l2_block, program.n_l2_block,
            program.traversal_order, program.aic_workers)
        expected_counts = tuple(
            (sum(worker == expected_worker
                 for worker, _, _ in assignments),)
            for expected_worker in range(program.aic_workers))
        assert sum(count[0] for count in expected_counts) == len(assignments)

        def reject_assignment_expansion(*_args, **_kwargs):
            raise AssertionError("full-region envelope expanded tile assignments")

        monkeypatch.setattr(
            gemm_predictor,
            "cann_gemm_source_tile_assignments",
            reject_assignment_expansion,
        )
        envelope = gemm_predictor._cann_npu_gemm_analytical_envelope(
            kernel, ASCEND_HARDWARE, geometry, traffic)

        assert envelope is not None
        assert envelope.class_shapes == ((128, 256),)
        assert envelope.counts_by_worker == expected_counts
        assert envelope.source_class_runs_by_worker == tuple(
            ((0, count[0]),) for count in expected_counts)
        assert envelope.tensor_operations == pytest.approx(
            2 * 256 * 112 * 128 * 256 * 8192)

