    def test_mcblas_non_split_uses_logical_l2_and_compulsory_dram(
            self, monkeypatch):
        kernel = self._mcblas_kernel()

        def _unexpected_lru(*args, **kwargs):
            pytest.fail("opaque mcBLAS launch must not enter an LRU model")

        monkeypatch.setattr(
            gemm_predictor, "simulate_gemm_n_major", _unexpected_lru)
        l2_bytes, dram_bytes = gemm_predictor._tensor_traffic(
            kernel, METAX_HARDWARE)

        expected_l2 = float(2 * 2 * (
            2 * (16 * 32 * 2 + 32 * 32 * 2) + 16 * 32 * 2))
        expected_dram = float((17 * 64 + 64 * 34 + 17 * 34) * 2)
        assert l2_bytes == expected_l2
        assert dram_bytes == expected_dram

