    def test_a800_analytical_gemv_keeps_fill_fixed_as_k_grows(self):
        def predict_at_k(k):
            shape = {"b": 1, "m": 1, "n": 4096, "k": k}
            launch = _select_launch_config(
                HARDWARE.hardware_id,
                KernelKind.GEMM,
                shape,
                "bf16",
                "gemv",
                {
                    "has_bias": False,
                    "position": "generic",
                    "launch_policy": "analytical_launch",
                },
                hardware=HARDWARE,
            )
            kernel = KernelSpec(
                KernelKind.GEMM,
                HARDWARE.hardware_id,
                shape,
                dtype="bf16",
                variant="gemv",
                launch=launch,
            )
            resource_input, _ = create_predictor(
                kernel.kind).resource_input(kernel, HARDWARE)
            prediction = create_predictor(
                kernel.kind).midlayer(kernel, HARDWARE)
            read_diagnostic = next(
                path for path in prediction.diagnostics.memory
                if path.path_name == "global_read")
            return resource_input, prediction, read_diagnostic.steady_time_s

        small_input, small_prediction, small_read_s = predict_at_k(4096)
        large_input, large_prediction, large_read_s = predict_at_k(4096 * 64)

        assert small_input.pipeline_plan is None
        assert large_input.pipeline_plan is None
        path, = small_input.dependency_paths
        assert path.name == "gpu_gemv_load_reduce_store"
        assert path.concurrent_service_groups == ((
            "memory:global_read", "compute:compute_fma"),)
        small_fixed_s = small_prediction.t_total_s - small_read_s
        large_fixed_s = large_prediction.t_total_s - large_read_s
        assert small_fixed_s > 0.0
        assert large_fixed_s == pytest.approx(small_fixed_s, abs=1e-15)
        assert (
            large_prediction.t_total_s - small_prediction.t_total_s
        ) == pytest.approx(large_read_s - small_read_s, rel=1e-12)

