    def test_mcblas_split_retains_fp32_partial_materialization(self):
        kernel = self._mcblas_kernel(grid_z=2, partial_bytes=4.0)

        l2_bytes, dram_bytes = gemm_predictor._tensor_traffic(
            kernel, METAX_HARDWARE)

        # L2 counts every logical (M tile, N tile) pair's full K-step operand
        # reads, independently of split_k: m_tiles=ceil(17/16)=2,
        # n_tiles=ceil(34/32)=2, k_steps=64/32=2, a_tile=min(16,17)*32*2=1024,
        # b_tile=32*32*2=2048.  A retained mcBLAS split-K launch shares this
        # accounting with every other grid-z split (see _tensor_traffic):
        # its CTA raster still executes one full a_tile/b_tile pair per
        # (M tile, N tile, K step) regardless of the opaque mainloop.  DRAM
        # stays the compulsory unique-byte count plus the external reducer's
        # FP32 partial buffer, unaffected by that per-tile L2 multiplicity.
        operand_l2_bytes = 2 * 2 * 2 * (1024 + 2048)
        input_bytes = (17 * 64 + 64 * 34) * 2
        partial_bytes = 2 * 17 * 34 * 4
        assert l2_bytes == operand_l2_bytes + partial_bytes
        assert dram_bytes == input_bytes + partial_bytes

    def test_c500_gemm_b512_k5120_n1536_l2_matches_canonical_launch(self):
        """GEMM_B512_M1_K5120_N1536: canonical launch facts (grid (12,4,2),
        block (256,1,1), tile 128x128x128, split_k=2, FP32 external partial)
        reproduced verbatim from kernel_dataset/metax_c500/gemm.json.zst.
        The mcBLAS split-K compulsory shortcut this fixes under-counted L2 by
        skipping the m_tiles x n_tiles operand re-read across M-tile groups
        the raw grid states (12 CTAs on the wide axis, 4 on the narrow one,
        2 K slices): predicted 26.00 MiB against a measured 126.05 MiB
        (0.206x) before this fix.
        """
        kernel = KernelSpec(
            KernelKind.GEMM,
            METAX_HARDWARE.hardware_id,
            {"b": 512, "m": 1, "n": 1536, "k": 5120, "dtype_bytes": 2},
            dtype="bf16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="observed_mcblas_gemm:gemm",
                grid=(12, 4, 2),
                block=(256, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 128, "n": 128, "k": 128},
                    split_k=2,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 4.0,
                    "split_k_partial_dram_bytes_per_element": 4.0,
                },
                execution_variant="gemm",
            ),
        )

        l2_bytes, dram_bytes = gemm_predictor._tensor_traffic(
            kernel, METAX_HARDWARE)

        # m_tiles=ceil(512/128)=4, n_tiles=ceil(1536/128)=12, k_steps=40,
        # a_tile=b_tile=128*128*2=32768; matches the measured main-kernel L2
        # read (125,878,272 bytes) to 99.96%.
        operand_l2_bytes = 4 * 12 * 40 * (32768 + 32768)
        partial_bytes = 2 * 512 * 1536 * 4
        input_bytes = 512 * 5120 * 2 + 5120 * 1536 * 2
        assert l2_bytes == operand_l2_bytes + partial_bytes
        assert dram_bytes == input_bytes + partial_bytes
        assert l2_bytes == pytest.approx(125_829_120.0 + 6_291_456.0)

    def test_c500_gemm_family_l2_is_monotonic_in_batch_across_split_k(self):
        """The predicted-value non-monotonicity (B256 -> B512 dropping from
        66.00 to 26.00 MiB) was the launch-selection defect's own diagnostic
        signal, independent of the measured side: this reproduces the whole
        GEMM_B*_M1_K5120_N1536 family's real captured launch facts and checks
        the predicted main-kernel L2 is monotonic non-decreasing in B, as the
        measured side always is -- with one documented exception.  B32 -> B48
        (both go through this same corrected formula) still dips by 1.6%: an
        underfull M tile (effective_m = min(tile_m, per_batch_m) below the
        retained tile_m) reads less than the real launch's boundary-CTA
        traffic, a pre-existing effective_m imprecision shared by the
        split_k<=1 sibling formula this one now matches, not something this
        fix introduces or is scoped to correct (it requires an independent
        read-quantization microbench, not a fit to this family's measured
        ratios).  Before this fix the same boundary dropped by 60.6%
        (B256->B512) and 2.8% (B8->B16); both are fully resolved here.
        """
        # (b, grid, tile_m, tile_n, tile_k) captured verbatim from
        # kernel_dataset/metax_c500/gemm.json.zst for GEMM_B*_M1_K5120_N1536;
        # split_k is each row's captured grid[2].
        family = (
            (2, (1, 12, 7), 64, 128, 256),
            (4, (1, 12, 7), 64, 128, 256),
            (8, (1, 12, 7), 64, 128, 256),
            (16, (12, 1, 7), 64, 128, 256),
            (32, (24, 1, 4), 32, 64, 256),
            (48, (12, 1, 8), 128, 128, 128),
            (64, (12, 1, 8), 128, 128, 128),
            (128, (1, 12, 8), 128, 128, 128),
            (256, (2, 12, 4), 128, 128, 128),
            (512, (12, 4, 2), 128, 128, 128),
        )
        known_residual_dip_indices = {5}  # B32 (index 4) -> B48 (index 5)

        def main_l2(b, tile_m, tile_n, tile_k, split_k):
            kernel = KernelSpec(
                KernelKind.GEMM,
                METAX_HARDWARE.hardware_id,
                {"b": b, "m": 1, "n": 1536, "k": 5120, "dtype_bytes": 2},
                dtype="bf16",
                variant="gemm",
                launch=LaunchConfig(
                    algorithm="observed_mcblas_gemm:gemm",
                    grid=(1, 1, split_k),
                    block=(256, 1, 1),
                    tiling=TilingSpec(
                        tile_shape={
                            "m": tile_m, "n": tile_n, "k": tile_k},
                        split_k=split_k,
                    ),
                    parameters={
                        "compulsory_traffic": 0.0,
                        "weight_tile_rows": 0.0,
                        "mte2_tile_bytes": 0.0,
                        "aiv_mixed": 0.0,
                        "n_major_traffic": 0.0,
                        "split_k_partial_bytes_per_element": 4.0,
                        "split_k_partial_dram_bytes_per_element": 4.0,
                    },
                    execution_variant="gemm",
                ),
            )
            l2_bytes, _ = gemm_predictor._tensor_traffic(
                kernel, METAX_HARDWARE)
            return l2_bytes

        predicted = [
            main_l2(b, tile_m, tile_n, tile_k, grid[2])
            for b, grid, tile_m, tile_n, tile_k in family
        ]
        for index in range(1, len(predicted)):
            if index in known_residual_dip_indices:
                assert predicted[index] < predicted[index - 1]
                assert predicted[index] > 0.97 * predicted[index - 1]
                continue
            assert predicted[index] >= predicted[index - 1]

