    def test_a800_six_stage_gemm_uses_source_complete_operand_pair_buffer(self):
        kernel = KernelSpec(
            KernelKind.GEMM,
            HARDWARE.hardware_id,
            {"b": 1, "m": 1, "n": 4096, "k": 4096,
             "dtype_bytes": 2},
            dtype="fp16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="observed_gemm:gemm",
                grid=(64, 1, 1),
                block=(128, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 64, "n": 64, "k": 64},
                    pipeline_depth=6,
                    split_k=1,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
            ),
        )

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, HARDWARE)

        plan = resource_input.pipeline_plan
        assert isinstance(plan, PipelineWorkPlan)
        assert plan.worker_count == 64
        program, = plan.tasks
        assert isinstance(program, PipelineTaskProgramDemand)
        assert program.worker == 0
        assert program.worker_multiplicity == 64
        assert program.physical_workers == tuple(range(64))
        assert program.order == (0,)
        sequence, = program.patterns
        assert len(sequence.tasks) == 3
        first, middle, final = sequence.tasks
        assert first.stages[0].name == "load"
        assert first.stages[0].work_fraction == pytest.approx(1.0 / (64 * 64))
        assert first.stages[0].include_first_request_latency
        assert middle.repeat_count == 62
        assert not middle.stages[0].include_first_request_latency
        assert tuple(stage.name for stage in final.stages) == (
            "load", "operand_smem", "compute", "store")
        # The CUDA 12.2 64x64x64 stages_64x6 source program retains three
        # complete 16-KiB A/B panel pairs, not six independently consumable
        # producer/consumer slots.
        assert plan.buffers == (PipelineBuffer(
            "load_compute_buffer", "load", "compute", 3, "worker"),)

