        assert plan.worker_count == 64
        assert plan.buffers == (PipelineBuffer(
            "load_compute_buffer", "load", "compute", 4, "worker"),)
        program, = plan.tasks
        assert isinstance(program, PipelineTaskProgramDemand)
        assert program.worker == 0
        assert program.worker_multiplicity == 64
        assert program.physical_workers == tuple(range(64))
        assert program.order == (0,)
        sequence, = program.patterns
        assert sequence.repeat_count == 1
        first, middle, final = sequence.tasks
        assert tuple(stage.name for stage in first.stages) == (
            "load", "operand_smem", "compute")
        assert first.stages[0].include_first_request_latency
        assert middle.repeat_count == 170
        assert not middle.stages[0].include_first_request_latency
        assert tuple(stage.name for stage in final.stages) == (
            "load", "operand_smem", "compute", "store")
        assert first.stages[0].work_fraction == pytest.approx(
            1.0 / (64 * 172))
        assert final.stages[-1].work_fraction == pytest.approx(1.0 / 64)
        _assert_compact_formula_matches_explicit(resource_input, HARDWARE)

