    def test_a800_depth5_split2_counts_non_hmma_sass_issue(self):
        kernel = KernelSpec(
            KernelKind.GEMM,
            HARDWARE.hardware_id,
            {"b": 1, "m": 8192, "n": 5120, "k": 1536,
             "dtype_bytes": 2},
            dtype="fp16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="observed_gemm:gemm",
                grid=(40, 64, 2),
                block=(128, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 128, "n": 128, "k": 32},
                    pipeline_depth=5,
                    split_k=2,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
            ),
        )

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, HARDWARE)

        # 5,120 CTAs execute 5,446 fixed non-HMMA warp instructions, while
        # all 2,560 output tiles cover 48 K32 tiles at 228 instructions each.
        assert resource_input.demand_per_resource["warp_issue"] == 55900160.0
        issue_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "warp_issue")
        assert issue_demand.operations == 55900160.0
        sass_path, = resource_input.dependency_paths
        assert sass_path.name == "sm80_depth5_split2_sass_issue_tensor"
        assert sass_path.services == (
            "compute:warp_issue", "compute:compute_tensor")

        prediction = PerformanceFormula(HARDWARE).predict_kernel(
            resource_input)
        assert prediction.bottleneck_group == (
            "dependency:sm80_depth5_split2_sass_issue_tensor")
        # The launch also pays its measured CTA dispatch cost, which is
        # geometry-independent and ordered before the program.
        assert prediction.t_total_ns == pytest.approx(
            632315.7894736843
            + HARDWARE.cta_dispatch_cost_ns(
                resource_input.grid_size))

