    def test_a800_depth3_split5_orders_epilogue_issue_by_output(self):
        kernel = KernelSpec(
            KernelKind.GEMM,
            HARDWARE.hardware_id,
            {"b": 128, "m": 1, "n": 5120, "k": 13824,
             "dtype_bytes": 2},
            dtype="fp16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="observed_gemm:gemm",
                grid=(20, 1, 5),
                block=(256, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 128, "n": 256, "k": 64},
                    pipeline_depth=3,
                    split_k=5,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
            ),
        )

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, HARDWARE)

        # Twenty output tiles each serialize five epilogues; the first skips
        # fourteen instructions in each of its eight warps.
        assert resource_input.demand_per_resource["warp_issue"] == 823360.0
        barrier_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_reduction")
        assert barrier_demand.operations == pytest.approx(
            20 * (13824 // 64)
            * HARDWARE.sm80_depth3_cta_barrier_service_cycles[
                "barrier_cycles"])
        issue_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "warp_issue")
        assert issue_demand.operations == 823360.0
        assert issue_demand.schedule_efficiency == pytest.approx(0.2)
        read_path = next(
            candidate for candidate in resource_input.memory_paths
            if candidate.name == "global_read")
        assert tuple(
            demand.service for demand in read_path.access_class_demands
        ) == (
            "sm80_depth3_operand_l2_hit",
            "sm80_depth3_operand_dram_miss",
        )
        assert all(
            demand.replaces_ingress_path_service
            for demand in read_path.access_class_demands)
        assert sum(
            demand.logical_bytes
            for demand in read_path.access_class_demands
        ) == pytest.approx(read_path.nodes[0].bytes)
        assert resource_input.pipeline_plan is None
        path, = resource_input.dependency_paths
        assert path.name == "sm80_depth3_split_load_mma_epilogue_store"
        assert path.services == (
            "launch:submit",
            "memory:global_read",
            "memory_latency:global_read",
            "compute:compute_tensor",
            "compute:compute_reduction",
            "compute:warp_issue",
            "memory:global_write",
            "memory_latency:global_write",
        )
        assert path.concurrent_service_groups == ((
            "memory:global_read", "compute:compute_tensor"),)
        warp_issue = HARDWARE.resource_by_role("warp_issue")
        warp_issue_capacity = warp_issue.effective_capacity(
            resource_input.active_units,
            sm_freq_hz=resource_input.sm_freq_hz,
            dram_freq_hz=resource_input.dram_freq_hz,
        )
        warp_issue_capacity *= (
            resource_input.active_units / HARDWARE.num_compute_units)
        analytical_issue_ns = (
            issue_demand.operations
            / (warp_issue_capacity * issue_demand.schedule_efficiency)
            * 1e9)
        assert resource_input.resource_time_overrides_ns["warp_issue"] == (
            pytest.approx(
                analytical_issue_ns + 35 * HARDWARE.l2_latency_ns))

        prediction = PerformanceFormula(HARDWARE).predict_kernel(
            resource_input)
        assert prediction.bottleneck_group == (
            "dependency:sm80_depth3_split_load_mma_epilogue_store")

