    def test_a800_finite_async_operand_stream_floor_prices_mixed_tiers(self):
        kernel = KernelSpec(
            KernelKind.GEMM,
            HARDWARE.hardware_id,
            {"b": 64, "m": 1, "n": 4096, "k": 11008,
             "dtype_bytes": 2},
            dtype="fp16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="observed_gemm:gemm",
                grid=(64, 1, 1),
                block=(128, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 64, "n": 64, "k": 64},
                    pipeline_depth=6,
                    split_k=1,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
            ),
        )

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, HARDWARE)

        profile = HARDWARE.finite_async_operand_stream_completion
        read_path, = (
            path for path in resource_input.memory_paths
            if path.name == "global_read")
        nodes = {node.resource_role: node for node in read_path.nodes}
        # A mixed stream keeps the tier-independent intercept and takes its
        # steady time from the binding independently measured tier service.
        assert 0.0 < nodes["dram"].bytes < nodes["l2_cache"].bytes
        capacity_by_service = {
            service: HARDWARE.memory_access_class_service(
                service, "read", "l2_cache",
                gemm_predictor._finite_async_operand_stream_signature(
                    kernel, service)).logical_byte_capacity_per_s
            for service in (
                "sm80_64x64_depth6_operand_l2_hit",
                "sm80_64x64_depth6_operand_dram_miss")
        }
        assert resource_input.execution_time_floor_ns == pytest.approx(
            profile["fixed_completion_ns"]
            + 1e9 * max(
                (nodes["l2_cache"].bytes - nodes["dram"].bytes)
                / capacity_by_service["sm80_64x64_depth6_operand_l2_hit"],
                nodes["dram"].bytes
                / capacity_by_service["sm80_64x64_depth6_operand_dram_miss"]))
        full_dram_read_path = dataclasses.replace(
            read_path,
            nodes=tuple(
                dataclasses.replace(
                    node,
                    bytes=nodes["l2_cache"].bytes,
                    transactions=(
                        nodes["l2_cache"].bytes / node.transaction_bytes),
                )
                if node.resource_role == "dram" else node
                for node in read_path.nodes),
        )
        full_dram_input = dataclasses.replace(
            resource_input,
            memory_paths=tuple(
                full_dram_read_path if path is read_path else path
                for path in resource_input.memory_paths),
        )
        completed = gemm_predictor._attach_finite_async_operand_stream_completion_floor(
            dataclasses.replace(full_dram_input, execution_time_floor_ns=None),
            kernel, HARDWARE)
        assert completed.execution_time_floor_ns == pytest.approx(
            profile["fixed_completion_ns"]
            + (11008 // 64) * profile["dram_unique_ns_per_round"])

    def test_a800_mixed_tier_finite_stream_floor_stays_under_measurement(self):
        """Bind the finite-stream tier composition to independent measurement.

        The preserved mixed-tier reference measures the same grid-64 / 16-KiB
        operand-pair / three-slot stream at five L2 operand-byte fractions and
        four round counts.  Every completion the predictor can produce inside
        that topology must stay a conservative envelope under those
        observations: the pure tiers through the published endpoint per-round
        rates, and a mixed stream through the binding per-tier byte service.
        The additive alternative is retained as a falsified candidate: it
        exceeds at least one measured observation, so the binding-tier
        composition is evidence-bound rather than a preference.
        """

        reference_path = Path(
            "microbench/nvidia_a800/references/"
            "finite_async_operand_stream_completion_mixed_tiers_sm80.json")
        endpoint_path = Path(
            "microbench/nvidia_a800/references/"
            "finite_async_operand_stream_completion_sm80.json")
        reference = json.loads(reference_path.read_text(encoding="utf-8"))
        assert reference["hardware_id"] == HARDWARE.hardware_id
        assert reference["production_or_evaluation_duration_consumed"] is False
        # Fail closed if the preserved verification stops describing the
        # endpoint profile the production floor consumes.
        assert reference["provenance"]["endpoint_reference_sha256"] == (
            hashlib.sha256(endpoint_path.read_bytes()).hexdigest())
        profile = HARDWARE.finite_async_operand_stream_completion
        derived = reference["derived_model"]
        scope = reference["scope"]
        assert scope["grid_ctas"] == profile["grid_ctas"]
        assert scope["operand_pair_bytes"] == profile["operand_pair_bytes"]
        assert scope["complete_operand_pair_slots"] == (
            profile["complete_operand_pair_slots"])
        assert derived["fixed_completion_ns"] == (
            profile["fixed_completion_ns"])
        tiers = derived["cache_tiers"]
        assert tiers["l2_resident"]["conservative_ns_per_round"] == (
            profile["l2_resident_ns_per_round"])
        assert tiers["dram_unique"]["conservative_ns_per_round"] == (
            profile["dram_unique_ns_per_round"])

        signature_for = lambda service: MemoryAccessClassSignature(
            access_class=service, dtype=scope["dtype"], tile_m=64, tile_k=64,
            logical_row_bytes=scope["operand_pair_bytes"])
        capacity = {
            service: HARDWARE.memory_access_class_service(
                service, "read", "l2_cache", signature_for(service)
            ).logical_byte_capacity_per_s
            for service in (
                "sm80_64x64_depth6_operand_l2_hit",
                "sm80_64x64_depth6_operand_dram_miss")
        }
        additive_violations = 0
        checked = 0
        for percent, samples in derived[
                "mixed_tier_verification"]["samples"].items():
            l2_fraction = int(percent) / 100.0
            for rounds, sample in samples.items():
                round_count = int(rounds)
                assert (profile["minimum_rounds"] <= round_count
                        <= profile["maximum_rounds"])
                observed_ns = sample["observed_ns"]
                total_bytes = float(
                    round_count * scope["operand_pair_bytes"]
                    * scope["grid_ctas"])
                l2_hit_bytes = l2_fraction * total_bytes
                dram_bytes = total_bytes - l2_hit_bytes
                l2_ns = 1e9 * l2_hit_bytes / capacity[
                    "sm80_64x64_depth6_operand_l2_hit"]
                dram_ns = 1e9 * dram_bytes / capacity[
                    "sm80_64x64_depth6_operand_dram_miss"]
                if l2_hit_bytes == 0.0:
                    floor_ns = (
                        profile["fixed_completion_ns"]
                        + round_count * profile["dram_unique_ns_per_round"])
                elif dram_bytes == 0.0:
                    floor_ns = (
                        profile["fixed_completion_ns"]
                        + round_count * profile["l2_resident_ns_per_round"])
                else:
                    floor_ns = (
                        profile["fixed_completion_ns"]
                        + max(l2_ns, dram_ns))
                    if (profile["fixed_completion_ns"] + l2_ns + dram_ns
                            > observed_ns):
                        additive_violations += 1
                assert floor_ns <= observed_ns, (percent, rounds, floor_ns)
                checked += 1
        assert checked == 20
        assert additive_violations > 0

