    def test_ascend_deterministic_split_k_derives_aiv_admission_from_tail(
            self):
        # CANN's L2-split AIV body recomputes coreSize from the current M
        # slab before evaluating ``vIndex * coreSize < coreOutSize``.  This
        # is deliberately a source-program contract rather than an
        # observation of any kernel duration.
        for batch, expected_workers in ((8, 8), (16, 16), (128, 43)):
            shape = {
                "b": batch,
                "m": 1,
                "n": 8192,
                "k": 28672,
                "dtype_bytes": 2,
            }
            launch = select_launch_config(
                ASCEND_HARDWARE.hardware_id,
                KernelKind.GEMM,
                shape,
                "bf16",
                "gemm",
                {"launch_policy": "analytical_launch"},
                hardware=ASCEND_HARDWARE,
            )
            kernel = KernelSpec(
                KernelKind.GEMM,
                ASCEND_HARDWARE.hardware_id,
                shape,
                dtype="bf16",
                variant=launch.execution_variant,
                launch=launch,
            )

            assert launch.source_program.aiv_workers == 48
            assert (
                gemm_predictor._cann_deterministic_split_k_aiv_data_workers(
                    kernel)
                == expected_workers)

    def test_ascend_deterministic_split_k_qualifies_nbuffer33_by_l2_path(self):
        # CANN 8.5.1 uses NBuffer33 only for the non-L2-split MK body.  Its
        # bounded-M policy, cache-slab topology and A1/B1/L0 ownership belong
        # in the launch contract, not in a Dataset/Serving predictor branch.
        nbuffer_shape = {
            "b": 128,
            "m": 1,
            "n": 4096,
            "k": 28672,
            "dtype_bytes": 2,
        }
        nbuffer_launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id,
            KernelKind.GEMM,
            nbuffer_shape,
            "bf16",
            "gemm",
            {"launch_policy": "analytical_launch"},
            hardware=ASCEND_HARDWARE,
        )
        nbuffer_program = nbuffer_launch.source_program
        assert nbuffer_program.program_kind == (
            "cann_gemm_deterministic_split_k_v1")
        assert nbuffer_program.scheduler_policy == "n_buffer_33"
        assert nbuffer_program.traversal_order == "n_then_m"
        assert (
            nbuffer_program.a1_buffer_slots,
            nbuffer_program.b1_buffer_slots,
            nbuffer_program.l0a_buffer_slots,
            nbuffer_program.l0b_buffer_slots,
        ) == (3, 2, 2, 2)

        # The identical small-M source geometry with two N L2 slabs enters
        # ``Mc2MatMulMultiCoreSplitKDivideL2cache``.  That function uses an
        # ordinary MatmulImpl and must expose that source's own queue credits
        # rather than inheriting NBuffer33.
        l2_split_shape = {**nbuffer_shape, "n": 8192}
        l2_split_launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id,
            KernelKind.GEMM,
            l2_split_shape,
            "bf16",
            "gemm",
            {"launch_policy": "analytical_launch"},
            hardware=ASCEND_HARDWARE,
        )
        l2_split_program = l2_split_launch.source_program
        assert l2_split_program.program_kind == (
            "cann_gemm_deterministic_split_k_v1")
        assert l2_split_program.scheduler_policy == "l2_split_matmul"
        assert l2_split_program.traversal_order == "n_then_m"
        assert (
            l2_split_program.a1_buffer_slots,
            l2_split_program.b1_buffer_slots,
            l2_split_program.l0a_buffer_slots,
            l2_split_program.l0b_buffer_slots,
        ) == (1, 2, 2, 2)

        # The retained legacy single-core program exposes its own fixed CANN
        # source scheduler rather than inheriting NBuffer33 slots merely
        # because it uses the same 128-cube base geometry.
        other_shape = {**nbuffer_shape, "b": 256, "n": 8192}
        other_launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id,
            KernelKind.GEMM,
            other_shape,
            "bf16",
            "gemm",
            {"launch_policy": "analytical_launch"},
            hardware=ASCEND_HARDWARE,
        )
        other_program = other_launch.source_program
        assert other_program.program_kind == (
            "cann_gemm_single_core_split_k_v1")
        assert other_program.scheduler_policy == "single_core_split_k"
        assert other_program.traversal_order == "n_then_m"
        assert (
            other_program.a1_buffer_slots,
            other_program.b1_buffer_slots,
            other_program.l0a_buffer_slots,
            other_program.l0b_buffer_slots,
        ) == (2, 2, 2, 2)

    def test_ascend_deterministic_split_k_uses_only_admitted_aiv_data_workers(
            self):
        shape = {
            "b": 128,
            "m": 1,
            "n": 8192,
            "k": 28672,
            "dtype_bytes": 2,
        }
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id,
            KernelKind.GEMM,
            shape,
            "bf16",
            "gemm",
            {"launch_policy": "analytical_launch"},
            hardware=ASCEND_HARDWARE,
        )
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            shape,
            dtype="bf16",
            variant=launch.execution_variant,
            launch=launch,
        )

        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        paths = {path.name: path for path in resource_input.memory_paths}
        vector, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")

        assert launch.source_program.aiv_workers == 48
        assert (
            gemm_predictor._cann_deterministic_split_k_aiv_data_workers(
                kernel)
            == 43)
        assert paths["aiv_workspace_mte2_read"].source.active_units == 43
        # CANN invokes IterateAll for all 75 K chunks.  The first call
        # initializes each output slab and the remaining calls atomically
        # accumulate complete FP32 partials into the same workspace.
        assert paths["fixpipe_l2_write"].nodes[0].bytes == pytest.approx(
            314_572_800)
        assert paths["mte3_write"].source.active_units == 43
        assert "nbuffer33_mte1_pair" not in paths
        split_k_mte1 = paths["split_k_mte1_pair"]
        assert tuple(
            (node.resource_role, node.bytes)
            for node in split_k_mte1.nodes
        ) == (
            ("l0a_buffer", pytest.approx(14_680_064)),
            ("l0b_buffer", pytest.approx(469_762_048)),
        )
        assert vector.schedule_efficiency == pytest.approx(43 / 48)
        prediction = PerformanceFormula(
            ASCEND_HARDWARE).predict_kernel(resource_input)
        workspace = next(
            path for path in prediction.diagnostics.memory
            if path.path_name == "aiv_workspace_mte2_read")
        mte2 = next(
            node for node in workspace.nodes
            if node.resource_role == "mte2")
        assert mte2.capacity_time_s * 1e9 == pytest.approx(
            81_284.96124031008)

        plan = resource_input.pipeline_plan
        assert isinstance(plan, PipelineWorkPlan)
        assert plan.worker_count == 24
        assert tuple(
            task.worker_multiplicity for task in plan.tasks) == (2, 1, 21)
        full_extra, tail_extra, regular = (
            task.patterns[0] for task in plan.tasks)
        assert tuple(task.repeat_count for task in full_extra.tasks) == (
            1, 2, 1, 1)
        assert tuple(task.repeat_count for task in tail_extra.tasks) == (
            1, 2, 1, 1)
        assert tuple(task.repeat_count for task in regular.tasks) == (
            1, 1, 1, 1)
        # CANN waits for the paired AIV flags, executes SyncAll and drains
        # PIPE_ALL before entering every output slab after the first.  The
        # repeated first K task therefore carries the prior slab's complete
        # AIC/AIV resource state; on slab zero those resources start ready.
        first_operand = full_extra.tasks[0].stages[0]
        assert first_operand.name == "operand_read"
        assert first_operand.prior_resources == (
            "memory:mte2_read",
            "memory:split_k_mte1_pair",
            "compute:compute_tensor",
            "memory:fixpipe_l2_write",
            "memory:aiv_workspace_mte2_read",
            "compute:compute_vector",
            "memory:mte3_write",
        )
        assert plan.buffers == (
            PipelineBuffer(
                "split_k_a1_credit", "operand_read", "mte1_pair",
                1, "worker"),
            PipelineBuffer(
                "split_k_b1_credit", "operand_read", "mte1_pair",
                2, "worker"),
            PipelineBuffer(
                "split_k_l0a_ping_pong", "mte1_pair", "cube",
                2, "worker"),
            PipelineBuffer(
                "split_k_l0b_ping_pong", "mte1_pair", "cube",
                2, "worker"),
            PipelineBuffer(
                "split_k_workspace_ping_pong", "workspace_first_write",
                "output_write", 2, "worker"),
        )

        def exact_group_columns(sequence):
            return tuple(
                exact.request_sizes_by_worker[0][0]
                for task in sequence.tasks
                for stage in task.stages
                for exact in stage.memory_exact_request_demands
                if exact.service == gemm_predictor._CANN_SPLIT_K_MTE2_GROUP_SERVICE
            )

        def nbuffer33_pair_counts(sequence):
            return tuple(
                len(exact.request_sizes_by_worker[0])
                for task in sequence.tasks
                for stage in task.stages
                for exact in stage.memory_exact_request_demands
                if exact.service == gemm_predictor._CANN_NBUFFER33_MTE1_PAIR_SERVICE
            )

        assert exact_group_columns(full_extra) == ()
        assert exact_group_columns(tail_extra) == ()
        assert exact_group_columns(regular) == ()
        assert nbuffer33_pair_counts(full_extra) == ()
        assert nbuffer33_pair_counts(tail_extra) == ()
        assert nbuffer33_pair_counts(regular) == ()
        assert plan.initial_resource_availability_s == ((
            gemm_predictor._CANN_SPLIT_K_SOURCE_QUEUE_FLOOR,
            pytest.approx(493_040.0e-9),
        ),)
        terminal = plan.tasks[0].patterns[1]
        final_cube, = tuple(
            stage
            for task in terminal.tasks
            for stage in task.stages
            if stage.name == "cube"
            and gemm_predictor._CANN_SPLIT_K_SOURCE_QUEUE_FLOOR
            in stage.prior_resources)
        assert final_cube.prior_resources == (
            gemm_predictor._CANN_SPLIT_K_SOURCE_QUEUE_FLOOR,)
        assert "mte2_descriptor_and_credit_evidence_unavailable" not in (
            resource_input.limitations)
        assert "aic_aiv_collective_barrier_lifecycle_unavailable" not in (
            resource_input.limitations)
        assert "mte_transaction_geometry_unavailable" in (
            resource_input.limitations)

    def test_ascend_nbuffer33_retains_generic_tail_mte1_path(self):
        # The full 128-row pair probe is deliberately not reused for an M
        # tail.  The normalized NBuffer33 program still carries its source
        # credit graph and conserved L0 traffic, while the tail receives only
        # the independent byte-capacity service.
        shape = {
            "b": 16,
            "m": 1,
            "n": 4096,
            "k": 28672,
            "dtype_bytes": 2,
        }
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id,
            KernelKind.GEMM,
            shape,
            "bf16",
            "gemm",
            {"launch_policy": "analytical_launch"},
            hardware=ASCEND_HARDWARE,
        )
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            shape,
            dtype="bf16",
            variant=launch.execution_variant,
            launch=launch,
        )
        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        plan = resource_input.pipeline_plan
        assert isinstance(plan, PipelineWorkPlan)
        assert {buffer.name for buffer in plan.buffers} >= {
            "split_k_a1_credit", "split_k_b1_credit",
            "split_k_l0a_ping_pong", "split_k_l0b_ping_pong",
        }
        mte1_exact = tuple(
            exact
            for task_program in plan.tasks
            for sequence in task_program.patterns
            for task in sequence.tasks
            for stage in task.stages
            for exact in stage.memory_exact_request_demands
            if exact.service == gemm_predictor._CANN_NBUFFER33_MTE1_PAIR_SERVICE
        )
        assert mte1_exact == ()
        prediction = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            resource_input)
        assert prediction.bottleneck_group == "pipeline"

    def test_ascend_single_core_split_k_replays_b_per_inner_m_stripe(self):
        shape = {
            "b": 8,
            "m": 4096,
            "n": 8192,
            "k": 28672,
            "dtype_bytes": 2,
        }
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id,
            KernelKind.GEMM,
            shape,
            "bf16",
            "gemm",
            {"launch_policy": "analytical_launch"},
            hardware=ASCEND_HARDWARE,
        )
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            shape,
            dtype="bf16",
            variant=launch.execution_variant,
            launch=launch,
        )

        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        traffic = gemm_predictor._cann_single_core_split_k_traffic(
            kernel,
            l2_replacement_capacity_bytes=(
                ASCEND_HARDWARE.l2_replacement_capacity_bytes),
        )
        assert traffic is not None
        rows = shape["b"] * shape["m"]
        n_groups = math.ceil(shape["n"] / launch.source_program.single_core_n)
        m_groups = math.ceil(rows / launch.source_program.single_core_m)
        stripes_per_m_group = math.ceil(
            launch.source_program.single_core_m
            / (launch.source_program.step_m
               * launch.source_program.base_m))
        m_stripes = m_groups * stripes_per_m_group
        assert traffic.operand_l2_read_bytes == (
            n_groups * rows * shape["k"] * shape["dtype_bytes"]
            + m_stripes * shape["k"] * shape["n"]
            * shape["dtype_bytes"])

        output_elements = rows * shape["n"]
        k_groups = math.ceil(
            shape["k"] / launch.source_program.single_core_k)
        assert traffic.workspace_l2_write_bytes == (
            k_groups * output_elements * 4)
        assert traffic.workspace_l2_read_bytes == output_elements * 4
        assert traffic.workspace_dram_write_bytes == (
            traffic.workspace_l2_write_bytes)
        paths = {path.name: path for path in resource_input.memory_paths}
        assert tuple(
            node.resource_role for node in paths["fixpipe_l2_write"].nodes
        ) == ("l2_cache",)
        operand_mte2 = paths["mte2_read"].nodes[0]
        assert operand_mte2.bytes == traffic.operand_l2_read_bytes
        assert operand_mte2.independent_service_streams == 2
        assert operand_mte2.capacity_ceiling_resource_role == "l2_cache"

        plan = resource_input.pipeline_plan
        assert isinstance(plan, CannSingleCoreSplitKEnvelopeDemand)
        assert plan.worker_count == 24
        assert plan.class_shapes == ((4096, 2816), (4096, 2560))
        assert plan.class_multiplicities == (16, 8)
        assert plan.single_core_k == 384
        assert plan.a1_buffer_slots == 3
        assert plan.b1_buffer_slots == 2
        replaced = replace_structured_demands(
            resource_input,
            {
                "compute_tensor": (
                    resource_input.demand_per_resource["compute_tensor"]
                    / 2.0),
            },
        )
        assert replaced.pipeline_plan == plan
        prediction = PerformanceFormula(
            ASCEND_HARDWARE).predict_kernel(resource_input)
        assert prediction.diagnostics.pipeline is not None
        assert prediction.diagnostics.pipeline.execution_time_s * 1e3 == (
            pytest.approx(47.75535234374986))
        assert prediction.t_total_s == pytest.approx(
            0.04775535234374986)
        assert prediction.t_total_s == pytest.approx(
            prediction.diagnostics.pipeline.execution_time_s)

