        assert pair_count == 2432
        assert geometry.worker_n_tiles > geometry.worker_m_tiles
        assert gemm_predictor._cann_npu_gemm_mte2_duration_ns(
            kernel, ASCEND_HARDWARE) == pytest.approx(
                ASCEND_HARDWARE.aic_mte2_operand_pair_stream_time_ns(
                    128, 64, 64, 256, 24, pair_count))

        m_major = dataclasses.replace(
            kernel,
            shape={"b": 1, "m": 2048, "n": 4096, "k": 11008,
                   "dtype_bytes": 2},
        )
        m_major_geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            m_major, ASCEND_HARDWARE)
        assert m_major_geometry.worker_m_tiles > (
            m_major_geometry.worker_n_tiles)
        m_major_duration_ns = gemm_predictor._cann_npu_gemm_mte2_duration_ns(
            m_major, ASCEND_HARDWARE)
        resident_pair_duration_ns = (
            ASCEND_HARDWARE.aic_mte2_operand_pair_stream_time_ns(
                128, 64, 64, 256, 24,
                (m_major_geometry.output_tiles_per_worker
                 * m_major_geometry.k_tiles)))
        assert not math.isclose(
            m_major_duration_ns, resident_pair_duration_ns,
            rel_tol=1e-12, abs_tol=1e-9)

