    def test_ascend_gemm_derives_l1_descriptor_pipeline(self):
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            {
                "b": 1,
                "m": 2048,
                "n": 4096,
                "k": 14336,
                "dtype_bytes": 2,
            },
            dtype="bf16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="cann_matmul_v3",
                grid=(24, 1, 1),
                block=(1, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 128, "n": 240, "k": 64},
                    pipeline_depth=2,
                    split_k=1,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
            ),
        )

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)

        geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            kernel, ASCEND_HARDWARE)
        assert geometry == gemm_predictor._CannNpuGemmPipelineGeometry(
            worker_count=24,
            worker_m_tiles=4,
            worker_n_tiles=3,
            output_tiles_per_worker=12,
            k_tiles=224,
            a_l1_k_tiles=8,
            b_l1_k_tiles=4,
            k_slabs=28,
            a_descriptors_per_worker=336,
            b_descriptors_per_worker=672,
            a_descriptor_bytes=131_072,
            b_descriptor_bytes=122_880,
        )
        assert resource_input.demand_per_resource["l2_cache"] == (
            24 * (336 * 131_072 + 672 * 122_880))
        assert resource_input.demand_per_resource["dram"] == 192_937_984.0
        assert compulsory == 192_937_984.0
        assert resource_input.support_level == "partial"
        assert "aic_operand_replay_evidence_unavailable" not in (
            resource_input.limitations)
        assert "mte2_descriptor_and_credit_evidence_unavailable" not in (
            resource_input.limitations)

        plan = resource_input.pipeline_plan
        assert isinstance(plan, PipelineWorkPlan)
        assert plan.worker_count == 24
        program, = plan.tasks
        assert isinstance(program, PipelineTaskProgramDemand)
        assert program.worker_multiplicity == 24
        sequence, = program.patterns
        assert sequence.repeat_count == 1
        first, middle, final = sequence.tasks
        assert (first.repeat_count, middle.repeat_count, final.repeat_count) == (
            1, 26, 1)
        assert all(
            tuple(stage.name for stage in task.stages) == (
                "load_l1_group", "load_l0a_group", "load_l0b_group",
                "cube_group")
            for task in (first, middle, final))
        assert first.stages[0].work_fraction == pytest.approx(1.0 / 672)
        assert plan.buffers == (
            PipelineBuffer(
                "l1_a_worker_group_lifetime", "load_l1_group",
                "load_l0a_group", 2, "worker"),
            PipelineBuffer(
                "l1_b_worker_group_lifetime", "load_l1_group",
                "load_l0b_group", 2, "worker"),
            PipelineBuffer(
                "l0a_worker_group_lifetime", "load_l0a_group",
                "cube_group", 2, "worker"),
            PipelineBuffer(
                "l0b_worker_group_lifetime", "load_l0b_group",
                "cube_group", 2, "worker"),
        )
        paths = {path.name: path for path in resource_input.memory_paths}
        assert paths["mte1_a_l1_to_l0"].nodes[0].bytes == (
            24 * 12 * 224 * 128 * 64 * 2)
        assert paths["mte1_b_l1_to_l0"].nodes[0].bytes == (
            24 * 12 * 224 * 64 * 240 * 2)

        a_channel_ns = gemm_predictor._cann_npu_mte2_descriptor_channel_time_ns(
            ASCEND_HARDWARE, 128, 512, 24, 336,
            delayed_by_one_issue=False)
        b_channel_ns = gemm_predictor._cann_npu_mte2_descriptor_channel_time_ns(
            ASCEND_HARDWARE, 240, 256, 24, 672,
            delayed_by_one_issue=True)
        assert a_channel_ns is not None
        assert b_channel_ns is not None
        expected_mte2_ns = max(a_channel_ns, b_channel_ns)
        assert resource_input.resource_time_overrides_ns["l2_cache"] == (
            pytest.approx(expected_mte2_ns))

