    def test_ascend_v2_drained_ingress_does_not_override_pipeline(self):
        program = CannGemmLaunchProgram(
            program_kind="cann_gemm_launch_v1",
            aic_workers=23,
            worker_grid_m=1,
            worker_grid_n=23,
            worker_grid_k=1,
            single_core_m=128,
            single_core_n=224,
            single_core_k=1536,
            base_m=128,
            base_n=112,
            base_k=128,
            depth_a1=2,
            depth_b1=2,
            a_l1_k_tiles=2,
            b_l1_k_tiles=2,
            step_m=1,
            step_n=1,
            m_l2_regions=1,
            n_l2_regions=1,
            m_l2_block=1,
            n_l2_block=23,
            traversal_order="persistent_n_then_m",
            a_uses_l2=True,
            b_uses_l2=True,
            split_k=1,
        )
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            {"b": 128, "m": 1, "n": 5120, "k": 1536,
             "dtype_bytes": 2},
            dtype="bf16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="ascend_cann_matmul",
                grid=(23, 1, 1),
                block=(1, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 128, "n": 112, "k": 128},
                    pipeline_depth=2,
                    split_k=1,
                ),
                parameters={
                    "compulsory_traffic": 0.0,
                    "weight_tile_rows": 0.0,
                    "mte2_tile_bytes": 0.0,
                    "aiv_mixed": 0.0,
                    "n_major_traffic": 0.0,
                    "split_k_partial_bytes_per_element": 0.0,
                    "split_k_partial_dram_bytes_per_element": 0.0,
                },
                execution_variant="gemm",
                source_program=program,
            ),
        )

        geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            kernel, ASCEND_HARDWARE)
        assert geometry is not None
        completion_ns = (
            gemm_predictor._cann_npu_gemm_finite_ingress_completion_ns(
                kernel, ASCEND_HARDWARE, geometry))
        stride_penalty_ns = (
            gemm_predictor._cann_npu_gemm_cold_v3_stride_penalty_ns(
                kernel, ASCEND_HARDWARE, geometry))
        assert stride_penalty_ns == pytest.approx(2850.932835169124)
        assert completion_ns == pytest.approx(22840.0 + stride_penalty_ns)
        traffic = gemm_predictor._cann_gemm_persistent_operand_traffic(
            kernel, ASCEND_HARDWARE,
            predecessor_dirty_bytes=int(
                ASCEND_HARDWARE.l2_replacement_capacity_bytes))
        assert traffic is not None
        cold_source_ns = (
            ASCEND_HARDWARE.aic_mte2_nd2nz_cold_stream_time_ns(
                traffic.a_dram_bytes + traffic.b_dram_bytes,
                geometry.worker_count)
            + stride_penalty_ns
            + gemm_predictor._cann_npu_gemm_cold_small_m_stride_penalty_ns(
                kernel, ASCEND_HARDWARE, geometry))
        assert cold_source_ns > completion_ns
        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)
        assert resource_input.pipeline_plan is not None
        assert resource_input.pipeline_plan.source_kind == "matmul_v2"
        assert resource_input.execution_time_floor_ns is None
        assert "l2_cache" not in resource_input.resource_time_overrides_ns
        prediction = create_predictor(kernel.kind).midlayer(
            kernel, ASCEND_HARDWARE)
        assert prediction.bottleneck_group != "analytical_execution_floor"

        # A finite ingress probe is source-program evidence, not a generic
        # per-pair latency.  The same completion-pair count on a 16x64x128
        # descriptor program must retain the analytical pipeline instead of
        # inheriting the 128x112x128 probe's serial drain.
        narrow_program = dataclasses.replace(
            program,
            aic_workers=24,
            worker_grid_n=24,
            single_core_m=16,
            single_core_n=64,
            single_core_k=5120,
            base_m=16,
            base_n=64,
            base_k=128,
            a_l1_k_tiles=4,
            b_l1_k_tiles=4,
            n_l2_block=24,
        )
        narrow_kernel = dataclasses.replace(
            kernel,
            shape={"b": 16, "m": 1, "n": 1536, "k": 5120,
                   "dtype_bytes": 2},
            launch=dataclasses.replace(
                kernel.launch,
                grid=(24, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 16, "n": 64, "k": 128},
                    pipeline_depth=2,
                    split_k=1,
                ),
                source_program=narrow_program,
            ),
        )
        narrow_geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            narrow_kernel, ASCEND_HARDWARE)
        assert narrow_geometry is not None
        assert gemm_predictor._cann_npu_gemm_finite_ingress_completion_ns(
            narrow_kernel, ASCEND_HARDWARE, narrow_geometry) is None

        b64_program = dataclasses.replace(
            program,
            aic_workers=20,
            worker_grid_n=20,
            single_core_m=64,
            single_core_n=256,
            base_m=64,
            base_n=256,
            base_k=64,
            a_l1_k_tiles=8,
            b_l1_k_tiles=4,
            n_l2_block=20,
        )
        b64_kernel = dataclasses.replace(
            kernel,
            shape={"b": 64, "m": 1, "n": 5120, "k": 1536,
                   "dtype_bytes": 2},
            launch=dataclasses.replace(
                kernel.launch,
                grid=(20, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 64, "n": 256, "k": 64},
                    pipeline_depth=2,
                    split_k=1,
                ),
                source_program=b64_program,
            ),
        )
        b64_geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            b64_kernel, ASCEND_HARDWARE)
        assert b64_geometry is not None
        assert gemm_predictor._cann_npu_gemm_measured_mte1_pair_completion_ns(
            b64_kernel, ASCEND_HARDWARE, b64_geometry) == pytest.approx(
                24 * 164.420572917)

