    def test_ascend_legacy_k14336_adds_only_exact_descriptor_stride_penalty(
            self):
        parameters = {
            "compulsory_traffic": 0.0,
            "weight_tile_rows": 0.0,
            "mte2_tile_bytes": 0.0,
            "aiv_mixed": 0.0,
            "n_major_traffic": 0.0,
            "split_k_partial_bytes_per_element": 0.0,
            "split_k_partial_dram_bytes_per_element": 0.0,
        }
        kernel = KernelSpec(
            KernelKind.GEMM,
            ASCEND_HARDWARE.hardware_id,
            {"b": 16, "m": 1, "n": 4096, "k": 14336,
             "dtype_bytes": 2},
            dtype="bf16",
            variant="gemm",
            launch=LaunchConfig(
                algorithm="cann_injected_matmul",
                grid=(22, 1, 1),
                block=(1, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 16, "n": 96, "k": 64},
                    pipeline_depth=2,
                    split_k=1),
                parameters=parameters,
                execution_variant="gemm",
            ),
        )
        geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            kernel, ASCEND_HARDWARE)
        serial_startup_ns, serial_capacity_per_s = (
            gemm_predictor._cann_npu_mte2_affine_service(
                ASCEND_HARDWARE, 22, stream=False))
        service = (
            ASCEND_HARDWARE.aic_mte2_cold_legacy_k14336_stride_service)
        a_contiguous_ns = (
            serial_startup_ns
            + geometry.a_descriptor_bytes / serial_capacity_per_s * 1e9)
        b_contiguous_ns = (
            serial_startup_ns
            + geometry.b_descriptor_bytes / serial_capacity_per_s * 1e9)
        expected_penalty_ns = (
            geometry.a_descriptors_per_worker
            * (service["descriptors"]["a"]["serial_completion_ns"]
               - a_contiguous_ns)
            + geometry.b_descriptors_per_worker
            * (service["descriptors"]["b"]["serial_completion_ns"]
               - b_contiguous_ns))

        assert (geometry.a_descriptor_bytes,
                geometry.a_descriptors_per_worker) == (131072, 8)
        assert (geometry.b_descriptor_bytes,
                geometry.b_descriptors_per_worker) == (122880, 46)
        assert gemm_predictor._cann_npu_gemm_cold_legacy_stride_penalty_ns(
            kernel, ASCEND_HARDWARE, geometry) == pytest.approx(
                expected_penalty_ns)

        unmatched = dataclasses.replace(
            kernel,
            launch=dataclasses.replace(
                kernel.launch,
                grid=(21, 1, 1),
            ),
        )
        unmatched_geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            unmatched, ASCEND_HARDWARE)
        assert gemm_predictor._cann_npu_gemm_cold_legacy_stride_penalty_ns(
            unmatched, ASCEND_HARDWARE, unmatched_geometry) == 0.0

