        resident_ns = (
            ASCEND_HARDWARE.aic_mte2_nd2nz_serial_time_ns(
                a_descriptor_bytes, 23)
            + (pair_count - 1)
            * ASCEND_HARDWARE.aic_mte2_nd2nz_stream_time_ns(
                a_descriptor_bytes, 23)
            + pair_count
            * ASCEND_HARDWARE.aic_mte2_nd2nz_stream_time_ns(
                b_descriptor_bytes, 23))
        cold_stream_ns = (
            ASCEND_HARDWARE.aic_mte2_nd2nz_cold_stream_time_ns(
                (8 * 1536 + 1536 * 5120) * 2, 23))
        geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            kernel, ASCEND_HARDWARE)
        stride_penalty_ns = (
            gemm_predictor._cann_npu_gemm_cold_v3_stride_penalty_ns(
                kernel, ASCEND_HARDWARE, geometry))
        source_descriptor_penalty_ns = (
            gemm_predictor._cann_npu_gemm_cold_small_m_stride_penalty_ns(
                kernel, ASCEND_HARDWARE, geometry))

        assert resource_input.resource_time_overrides_ns["l2_cache"] == (
            pytest.approx(max(resident_ns, cold_stream_ns)
                          + stride_penalty_ns
                          + source_descriptor_penalty_ns))
        assert cold_stream_ns > resident_ns
        assert stride_penalty_ns > 0
        # The source program is not present in canonical launch data. Its
        # private dry-launch L1 layout therefore cannot add a Forward term.
        assert source_descriptor_penalty_ns == 0.0

        remaining = dataclasses.replace(
            kernel,
            shape={"b": 4, "m": 1, "n": 1536, "k": 5120,
                   "dtype_bytes": 2},
            launch=dataclasses.replace(
                kernel.launch,
                grid=(24, 1, 1),
                tiling=TilingSpec(
                    tile_shape={"m": 16, "n": 64, "k": 128},
                    pipeline_depth=2,
                    split_k=1),
            ),
        )
        remaining_geometry = gemm_predictor._cann_npu_gemm_pipeline_geometry(
            remaining, ASCEND_HARDWARE)
        assert gemm_predictor._cann_npu_gemm_cold_small_m_stride_penalty_ns(
            remaining, ASCEND_HARDWARE, remaining_geometry) > 0

