    def test_a800_typed_pytorch_vec4_streams_static_warp_issue(
            self):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        shape = {"element_count": 2560}
        attributes = {"reads": 2, "writes": 1, "operation": "add"}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise_pytorch_vec4", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)
        ledger = resource_input.phase_ledger

        assert resource_input.demand_per_resource["warp_issue"] == 1100.0
        assert launch.parameters["warp_instructions"] == 1100.0
        assert "warp_instructions_lower_bound" not in launch.parameters
        assert launch.parameters[
            "source_bound_memory_dependency_task"] == 1.0
        assert ledger is not None
        issue, = ledger.unassigned_compute_demands
        assert issue.resource_role == "warp_issue"
        assert issue.operation == "whole_kernel_warp_instruction"
        assert issue.operations == 1100.0
        assert ledger.limitations == (
            "whole_kernel_warp_issue_phase_assignment_unavailable",)
        ledger.validate_conservation(
            resource_input.compute_demands, resource_input.memory_paths)

    def test_a800_elementwise_complete_task_floor_overlaps_source_body(self):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        elements = 4096
        shape = {"element_count": elements}
        attributes = {"reads": 2, "writes": 1, "operation": "add"}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise_pytorch_vec4", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)
        dependency_path, = resource_input.dependency_paths
        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)

        assert resource_input.task_duration_floor_contract == (
            WARM_DEFAULT_CACHE_MEMORY_DEPENDENCY_TASK_FLOOR)
        assert "task:memory_dependency_increment" not in (
            dependency_path.services)
        # The task floor still overlaps the source body rather than adding to
        # it; the prediction is the largest of the floors that apply.  A800
        # publishes a measured warm floor for this task class at this launch
        # geometry, and at this shape it is the binding one.
        assert prediction.t_total_ns == pytest.approx(
            max(
                hardware.memory_dependency_task_duration_ns(
                    WARM_DEFAULT_CACHE_MEMORY_DEPENDENCY_TASK_FLOOR,
                    launch.grid_size, launch.block_size,
                    launch.grid, launch.block, hardware.nominal_sm_freq_hz),
                _memory_touching_span_floor_ns(hardware, launch.grid_size),
                hardware.runtime_task_class_duration_ns(
                    PYTORCH_BF16_BINARY_TENSOR_ITERATOR_TASK_CLASS, elements,
                    launch.grid_size, launch.block_size))
            + hardware.cta_dispatch_cost_ns(launch.grid_size))

