    def test_c500_silu_builds_packed_cta_dependency_pipeline(self):
        hardware = HWSpec("configs/hardware/metax_c500.yaml")
        elements = 2 * 6144
        shape = {
            "tok": 2,
            "intermediate": 6144,
            "element_count": elements,
        }
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16", "silu",
            {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert launch.grid == (2, 2, 1)
        assert launch.parameters[
            SOURCE_VECTOR_ELEMENTS_PER_THREAD_PARAMETER] == 8.0
        assert launch.parameters[
            SOURCE_BF16_CONVERSION_OPERATIONS_PARAMETER] == 3.0 * elements
        sfu_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_sfu")
        assert sfu_demand.service_demands == (
            ComputeServiceDemand(
                "exp_dependency", 24.0, serial_invocations=1),
            ComputeServiceDemand(
                "reciprocal_one_plus_dependency", 24.0,
                serial_invocations=1),
        )
        assert resource_input.demand_per_resource["compute_fma"] == (
            2.0 * elements)
        assert resource_input.demand_per_resource["compute_alu"] == (
            3.0 * elements)
        plan = resource_input.pipeline_plan
        assert plan is not None
        assert resource_input.resident_cta_cohort_refills is None
        assert plan.worker_count == launch.grid_size == 4
        assert len(plan.tasks) == 4
        math_operations = []
        for program in plan.tasks:
            task, = program.patterns[0].tasks
            assert tuple(stage.name for stage in task.stages) == (
                "load", "conversion_0", "source_sfu_math_0",
                "arithmetic_0", "store")
            math_stage = task.stages[2]
            math_operations.append(
                math_stage.compute_service_demands[0].operations)
            assert tuple(
                demand.service
                for demand in math_stage.compute_service_demands
            ) == (
                "exp_dependency", "reciprocal_one_plus_dependency")
        assert math_operations == [8.0, 4.0, 8.0, 4.0]
        first_worker_task, = plan.tasks[0].patterns[0].tasks
        matching_worker_task, = plan.tasks[2].patterns[0].tasks
        assert all(
            first_stage is matching_stage
            for first_stage, matching_stage in zip(
                first_worker_task.stages, matching_worker_task.stages))

