    @pytest.mark.parametrize(
        (
            "variant", "l2_read_copies", "dram_read_copies",
            "write_copies", "lowered_passes", "semantic_passes",
        ),
        (("rmsnorm", 3, 1, 1, 4, 4),
         ("add_rmsnorm", 4, 4, 2, 9, 5)),
    )
    def test_ascend_split_d_preserves_source_read_path(
            self, variant, l2_read_copies, dram_read_copies, write_copies,
            lowered_passes, semantic_passes):
        shape = {"rows": 2, "hidden": 12289}
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, shape, "bf16",
            variant, {}, hardware=ASCEND_HARDWARE)
        kernel = KernelSpec(
            KernelKind.VECTOR,
            ASCEND_HARDWARE.hardware_id,
            shape,
            dtype="bf16",
            variant=launch.execution_variant,
            launch=launch,
        )

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)
        elements = shape["rows"] * shape["hidden"]
        weight_elements = shape["hidden"]
        expected_l2_read = l2_read_copies * elements * 2
        expected_dram_read = (
            (dram_read_copies * elements + weight_elements) * 2
            if variant == "rmsnorm"
            else dram_read_copies * elements * 2)
        expected_write = write_copies * elements * 2
        expected_rstd_write = shape["rows"] * 4
        expected_rstd_transfer = (
            32 * shape["rows"] if variant == "rmsnorm"
            else expected_rstd_write)

        if variant == "rmsnorm":
            expected_lowered_parameters = {
                "lowered_vector_input_operations": float(elements),
                "lowered_vector_output_operations": float(3 * elements),
            }
        elif variant == "add_rmsnorm":
            expected_lowered_parameters = {
                "lowered_vector_input_operations": float(3 * elements),
                "lowered_vector_reduce_operations": float(
                    elements + shape["rows"]),
                "lowered_vector_output_operations": float(5 * elements),
            }
        else:
            raise AssertionError(variant)
        if variant == "rmsnorm":
            expected_tiling_key = 1.0
            expected_source_parameters = {
                "source_bound_rmsnorm_split_d_dag": 1.0,
            }
        elif variant == "add_rmsnorm":
            expected_tiling_key = 31.0
            expected_source_parameters = {
                "source_bound_add_rmsnorm_split_d_dag": 1.0,
            }
        else:
            raise AssertionError(variant)
        assert launch.parameters == {
            **expected_source_parameters,
            "input_reread_count": 1.0,
            **expected_lowered_parameters,
            "norm_weight_l2_copies": float(shape["rows"]),
            "rstd_output_bytes": float(expected_rstd_write),
            **({"cann_rmsnorm_rstd_transfer_bytes": float(
                expected_rstd_transfer)} if variant == "rmsnorm" else {}),
            "norm_epsilon_add_flops": float(shape["rows"]),
            "norm_block_factor": 1.0,
            "cann_tiling_payload_bytes": (
                28.0 if variant == "rmsnorm" else 80.0),
            "cann_tiling_key": expected_tiling_key,
        }
        semantic_vector_operations = (
            semantic_passes * elements
            + 2 * shape["rows"])
        lowered_operations = sum(
            launch.parameters[name]
            for name in (
                "lowered_vector_input_operations",
                "lowered_vector_reduce_operations",
                "lowered_vector_output_operations",
            )
            if name in launch.parameters)
        expected_lowered_operations = float(lowered_passes * elements)
        if variant == "add_rmsnorm":
            expected_lowered_operations += float(shape["rows"])
        assert lowered_operations == expected_lowered_operations
        assert resource_input.demand_per_resource["compute_vector"] == (
            semantic_vector_operations + lowered_operations)
        assert resource_input.demand_per_resource["l2_cache"] == (
            expected_l2_read + expected_write + expected_rstd_transfer)
        assert resource_input.demand_per_resource["dram"] == (
            expected_dram_read + expected_write + expected_rstd_transfer)
        assert resource_input.demand_per_resource["mte3"] == (
            expected_write + expected_rstd_transfer)
        assert compulsory == (
            expected_dram_read + expected_write + expected_rstd_transfer)
        if variant == "rmsnorm":
            assert resource_input.support_level == "partial"
            assert resource_input.pipeline_plan is not None
            assert resource_input.dependency_paths == ()
        elif variant == "add_rmsnorm":
            assert resource_input.support_level == "partial"
            assert resource_input.pipeline_plan is not None
            assert resource_input.dependency_paths == ()
        else:
            raise AssertionError(variant)
        vector_demand, = tuple(
            item for item in resource_input.compute_demands
            if item.resource_role == "compute_vector")
        if variant == "rmsnorm":
            assert vector_demand.service_demands[0].service == "generic"
            assert vector_demand.service_demands[0].operations == (
                resource_input.demand_per_resource["compute_vector"]
                - shape["rows"])
            assert vector_demand.service_demands[0].operations_by_worker == (
                vector_demand.service_demands[0].operations / 2,
                vector_demand.service_demands[0].operations / 2,
            )
        elif variant == "add_rmsnorm":
            assert vector_demand.service_demands
            assert math.fsum(
                demand.operations
                for demand in vector_demand.service_demands
            ) == (
                resource_input.demand_per_resource["compute_vector"]
                - shape["rows"])
        else:
            raise AssertionError(variant)
        exact_demand, = vector_demand.exact_request_demands
        assert exact_demand.service == (
            "norm_sqrt_duplicate_div_serialized")
        assert exact_demand.request_sizes_by_worker == ((1,), (1,))
        ledger = resource_input.phase_ledger
        assert ledger is not None
        assert ledger.limitations == ()
        assert ledger.unassigned_compute_demands == ()
        phases = {phase.name: phase for phase in ledger.phases}
        load_reduce_memory = {
            (demand.path_name, demand.resource_role): demand.bytes
            for demand in phases["load_reduce"].memory_demands
        }
        load_output_memory = {
            (demand.path_name, demand.resource_role): demand.bytes
            for demand in phases["load_output"].memory_demands
        }
        residual_store_memory = {
            (demand.path_name, demand.resource_role): demand.bytes
            for demand in phases["residual_store"].memory_demands
        } if "residual_store" in phases else {
        }
        store_memory = {
            (demand.path_name, demand.resource_role): demand.bytes
            for demand in phases["store"].memory_demands
        }

        reduction_input_bytes = (
            dram_read_copies * elements * 2
            if variant == "rmsnorm" else 2 * elements * 2)
        assert load_reduce_memory == {
            ("mte2_read", "mte2"): reduction_input_bytes,
            ("mte2_read", "l2_cache"): reduction_input_bytes,
            ("mte2_read", "dram"): reduction_input_bytes,
        }
        assert load_output_memory == {
            ("mte2_read", "mte2"):
                expected_l2_read - reduction_input_bytes,
            ("mte2_read", "l2_cache"):
                expected_l2_read - reduction_input_bytes,
            ("mte2_read", "dram"): (
                weight_elements * 2
                if variant == "rmsnorm"
                else expected_l2_read - reduction_input_bytes),
        }
        if variant == "rmsnorm":
            expected_reduce_memory = {}
            expected_final_write = expected_write + expected_rstd_transfer
        elif variant == "add_rmsnorm":
            updated_residual_write = elements * 2
            expected_reduce_memory = {
                ("mte3_write", "mte3"): updated_residual_write,
                ("mte3_write", "l2_cache"): updated_residual_write,
                ("mte3_write", "dram"): updated_residual_write,
            }
            expected_final_write = (
                expected_write - updated_residual_write
                + expected_rstd_write)
        else:
            raise AssertionError(variant)
        assert residual_store_memory == expected_reduce_memory
        assert store_memory == {
            ("mte3_write", "mte3"): expected_final_write,
            ("mte3_write", "l2_cache"): expected_final_write,
            ("mte3_write", "dram"): expected_final_write,
        }

    @pytest.mark.parametrize(
        ("variant", "shape", "payload_bytes", "prologue_contract"),
        (
            ("rmsnorm", {"rows": 4, "hidden": 2048}, 28.0,
             CANN_AIV_TILING_MATERIALIZATION_PROLOGUE),
            ("rmsnorm", {"rows": 4, "hidden": 16384}, 28.0,
             CANN_AIV_TILING_MATERIALIZATION_PROLOGUE),
            ("add_rmsnorm", {"rows": 4, "hidden": 2048}, 80.0,
             CANN_AIV_TILING_MATERIALIZATION_80B_PROLOGUE),
            ("add_rmsnorm", {"rows": 49, "hidden": 2048}, 80.0,
             CANN_AIV_TILING_MATERIALIZATION_80B_PROLOGUE),
            ("add_rmsnorm", {"rows": 4, "hidden": 16384}, 80.0,
             CANN_AIV_TILING_MATERIALIZATION_80B_PROLOGUE),
        ),
    )
    def test_ascend_norm_prices_source_tiling_payload_contract(
            self, variant, shape, payload_bytes, prologue_contract):
        """Typed CANN entries select their materialization mechanism.

        The payload comes from the fixed CANN 8.5.1 entry type, so all
        AddRMSNorm implementation keys use 80 B and both RMSNorm keys use
        28 B.  Rows and hidden merely exercise the source key dispatch.
        """
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, shape, "bf16",
            variant, {}, hardware=ASCEND_HARDWARE)
        kernel = KernelSpec(
            KernelKind.VECTOR, ASCEND_HARDWARE.hardware_id, shape,
            dtype="bf16", variant=launch.execution_variant, launch=launch)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)

        assert launch.parameters["cann_tiling_payload_bytes"] == payload_bytes
        assert resource_input.task_prologue_contract == prologue_contract
        assert resource_input.task_prologue_repetitions == 1

    def test_ascend_norm_tail_serializes_generic_and_exact_per_aiv(self):
        shape = {"rows": 49, "hidden": 8192}
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "add_rmsnorm", {}, hardware=ASCEND_HARDWARE)
        kernel = KernelSpec(
            KernelKind.VECTOR, ASCEND_HARDWARE.hardware_id, shape,
            dtype="bf16", variant=launch.execution_variant, launch=launch)
        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        exact, = vector_demand.exact_request_demands

        assert launch.grid_size == 25
        assert launch.parameters["cann_tiling_key"] == 30.0
        assert launch.parameters["norm_block_factor"] == 2.0
        assert all(
            len(service.operations_by_worker) == 25
            and len(service.serial_invocations_by_worker) == 25
            for service in vector_demand.service_demands)
        assert exact.request_sizes_by_worker[:-1] == ((1, 1),) * 24
        assert exact.request_sizes_by_worker[-1] == (1,)

        prediction = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            resource_input)
        vector = ASCEND_HARDWARE.resource_by_role("compute_vector")
        expected_worker_durations = tuple(
            math.fsum(
                service.operations_by_worker[worker]
                / vector.service_rate_for_one_unit(service.service)
                + (
                    service.serial_invocations_by_worker[worker]
                    * vector.setup_time_for_service(service.service)
                    if service.serial_invocations_by_worker[worker] else 0.0)
                for service in vector_demand.service_demands)
            + math.fsum(
                vector.exact_request_service_time_s(
                    exact.service, request_size)
                for request_size in exact.request_sizes_by_worker[worker])
            for worker in range(25))
        assert expected_worker_durations[:-1] == pytest.approx(
            (expected_worker_durations[0],) * 24)
        assert expected_worker_durations[-1] < expected_worker_durations[0]
        assert prediction.t_per_resource[vector.name] == pytest.approx(
            max(expected_worker_durations))

