    def test_ascend_rms_single_row_pipeline_conserves_source_work(self):
        rows = 4
        hidden = 2048
        _, resource_input = self._ascend_rms_single_row_input(rows, hidden)
        plan = resource_input.pipeline_plan

        assert resource_input.support_level == "partial"
        assert (
            "rmsnorm_scalar_reciprocal_sqrt_service_unavailable"
            not in resource_input.limitations)
        assert plan is not None
        assert plan.worker_count == rows
        assert len(plan.tasks) == rows
        assert resource_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_PLUS_SOURCE_PROGRAM)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert plan.buffers == (
            PipelineBuffer(
                "rms_gamma_ub", "gamma_load", "gamma_apply", 1,
                "worker"),
            PipelineBuffer(
                "rms_x_fp32_ub", "input_load", "output_scale", 1,
                "worker"),
            PipelineBuffer(
                "rms_y_queue", "final_cast", "output_store", 1,
                "worker"),
            PipelineBuffer(
                "rms_rstd_queue", "local_scalar_dependency", "rstd_store",
                1, "worker"),
        )
        expected_stages = (
            "source_control", "gamma_load", "input_load",
            "input_square_reduce", "local_scalar_dependency",
            "output_scale", "gamma_apply", "final_cast", "output_store",
            "rstd_store",
        )
        assert all(
            tuple(stage.name for stage in task.stages) == expected_stages
            for task in plan.tasks)

        memory_bytes = {}
        generic_operations = 0.0
        generic_operations_by_stage = {}
        for task in plan.tasks:
            for stage in task.stages:
                stage_operations = math.fsum(
                    demand.operations
                    for demand in stage.compute_service_demands)
                generic_operations += stage_operations
                if stage_operations > 0:
                    if stage.name in generic_operations_by_stage:
                        generic_operations_by_stage[stage.name] += (
                            stage_operations)
                    else:
                        generic_operations_by_stage[stage.name] = (
                            stage_operations)
                for demand in stage.memory_node_demands:
                    key = (demand.path_name, demand.resource_role)
                    memory_bytes[key] = (
                        memory_bytes[key] + demand.bytes
                        if key in memory_bytes else demand.bytes)
                if task.worker == 0:
                    for demand in stage.launch_shared_memory_node_demands:
                        key = (demand.path_name, demand.resource_role)
                        memory_bytes[key] = (
                            memory_bytes[key] + demand.bytes
                            if key in memory_bytes else demand.bytes)
        aggregate_memory_bytes = {
            (path.name, node.resource_role): node.bytes
            for path in resource_input.memory_paths
            for node in path.nodes
        }
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        services = {
            demand.service: demand
            for demand in vector_demand.service_demands}

        assert memory_bytes == aggregate_memory_bytes
        exact, = vector_demand.exact_request_demands
        assert exact.service == "rmsnorm_local_scalar_dependency"
        assert exact.request_sizes_by_worker == ((2,),) * rows
        scalar_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "scalar_aiv")
        assert scalar_demand.exact_request_demands == (
            ComputeExactRequestDemand(
                "aiv_four_queue_three_tbuf_lifecycle", ((1,),) * rows),
            ComputeExactRequestDemand(
                "aiv_queue_control_cycle", ((1,),) * rows),
        )
        assert generic_operations + exact.operations == (
            vector_demand.operations) == float(rows * (7 * hidden + 2))
        assert tuple(services) == (
            "cast_bf16_to_fp32_serialized", "mul_serialized",
            "rmsnorm_half_interval_reduce", "muls_serialized",
            "cast_fp32_to_bf16_serialized")
        assert services["cast_bf16_to_fp32_serialized"].operations == (
            float(2 * rows * hidden))
        assert services["mul_serialized"].operations == float(
            2 * rows * hidden)
        assert services[
            "rmsnorm_half_interval_reduce"].operations_by_worker == (
            float(hidden),) * rows
        assert services["muls_serialized"].serial_invocations == 1
        assert services[
            "cast_fp32_to_bf16_serialized"].serial_invocations == 1
        assert generic_operations_by_stage == {
            "input_square_reduce": float(3 * rows * hidden),
            "output_scale": float(rows * hidden),
            "gamma_apply": float(2 * rows * hidden),
            "final_cast": float(rows * hidden),
        }

    def test_ascend_rms_single_row_pipeline_preserves_source_order(self):
        _, resource_input = self._ascend_rms_single_row_input(rows=1)
        task = resource_input.pipeline_plan.tasks[0]
        stages = {stage.name: stage for stage in task.stages}

        control_exact = stages[
            "source_control"].compute_exact_request_demands
        assert control_exact == (
            ComputeExactRequestDemand(
                "aiv_four_queue_three_tbuf_lifecycle", ((1,),)),
            ComputeExactRequestDemand(
                "aiv_queue_control_cycle", ((1,),)),
        )
        assert stages["source_control"].predecessors == ()
        assert stages["gamma_input_load"].predecessors == (
            "source_control",)
        assert stages["input_square_reduce"].predecessors == (
            "gamma_input_load",)
        assert stages["local_scalar_dependency"].predecessors == (
            "input_square_reduce",)
        assert stages["output_scale"].predecessors == (
            "local_scalar_dependency",)
        assert stages["gamma_apply"].predecessors == (
            "gamma_input_load", "output_scale")
        assert stages["final_cast"].predecessors == ("gamma_apply",)
        assert stages["output_store"].predecessors == ("final_cast",)
        assert stages["rstd_store"].predecessors == (
            "local_scalar_dependency",)
        assert stages["rstd_store"].start_predecessors == (
            "output_store",)
        combined = stages["gamma_input_load"]
        exact, = combined.memory_exact_request_demands
        assert exact.resource_role == "mte2"
        assert exact.service == (
            "aiv_rmsnorm_key0_gamma_input_sequence_completion")
        assert exact.request_sizes_by_worker == ((4096,),)
        assert combined.memory_exact_request_replaces_resource_capacity
        assert {
            demand.resource_role: demand.bytes
            for demand in combined.memory_node_demands
        } == {"mte2": 8192.0, "l2_cache": 8192.0}
        assert combined.launch_shared_memory_node_demands == (
            PhaseMemoryDemand("mte2_read", "dram", 8192.0),)
        exact, = stages["output_store"].memory_exact_request_demands
        assert exact.resource_role == "mte3"
