        rstd_exact, = stages["rstd_store"].memory_exact_request_demands
        assert rstd_exact.resource_role == "mte3"
        assert rstd_exact.service == "aiv_mte3_request_completion"
        assert rstd_exact.request_sizes_by_worker == ((32,),)
        assert (
            "cann_rmsnorm_vector_edge_completion_evidence_pending"
            not in resource_input.limitations)
        assert (
            "cann_rmsnorm_fourth_queue_third_tbuf_control_evidence_pending"
            not in resource_input.limitations)

        prediction = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            resource_input)
        pipeline = prediction.diagnostics.pipeline
        first = pipeline.tasks[0]
        assert first.stage_end_s["rstd_store"] == pytest.approx(
            pipeline.worker_makespan_s["0"])
        assert first.stage_start_s["rstd_store"] >= (
            first.stage_end_s["output_store"])

