    def test_ascend_rms_single_row_pipeline_requires_exact_source_facts(
            self):
        kernel, _ = self._ascend_rms_single_row_input()
        parameters = dict(kernel.launch.parameters)
        parameters["source_bound_rmsnorm_single_row_dag"] = 2.0
        with pytest.raises(ValueError, match="must equal one"):
            dataclasses.replace(
                kernel,
                launch=dataclasses.replace(
                    kernel.launch, parameters=parameters))

        parameters = dict(kernel.launch.parameters)
        parameters["lowered_vector_output_operations"] += 1.0
        malformed_work = dataclasses.replace(
            kernel,
            launch=dataclasses.replace(kernel.launch, parameters=parameters))
        with pytest.raises(ValueError, match="lowered work disagrees"):
            create_predictor(malformed_work.kind).resource_input(
                malformed_work, ASCEND_HARDWARE)

        split_shape = {"rows": 4, "hidden": 12289}
        split_launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, split_shape,
            "bf16", "rmsnorm", {}, hardware=ASCEND_HARDWARE)
        split_parameters = dict(split_launch.parameters)
        split_parameters["source_bound_rmsnorm_single_row_dag"] = 1.0
        with pytest.raises(ValueError, match="requires RmsNorm CANN key 0"):
            KernelSpec(
                KernelKind.VECTOR, ASCEND_HARDWARE.hardware_id, split_shape,
                dtype="bf16", variant=split_launch.execution_variant,
                launch=dataclasses.replace(
                    split_launch, parameters=split_parameters))

