    @pytest.mark.parametrize(
        ("rows", "worker", "group_rows"),
        (
            # The source can leave a one-row worker tail, assign two rows,
            # or assign one full 64-row rstd group to an AIV.  These are
            # source-program extents, rather than predictor shape regimes.
            (139, 46, 1),
            (64, 0, 2),
            (3072, 0, 64),
        ),
    )
    def test_ascend_rms_row_group_preserves_subprocess_row_order(
            self, rows, worker, group_rows):
        _, resource_input = self._ascend_rms_row_group_input(
            rows=rows, hidden=2048)
        group = next(
            task for task in resource_input.pipeline_plan.tasks
            if task.name == f"worker{worker}_first_group")
        stages = {stage.name: stage for stage in group.stages}
        positions = {
            stage.name: index for index, stage in enumerate(group.stages)}

        def row_name(base, row_index):
            if base in ("input_queue_control", "input_load") and row_index == 0:
                return base
            if base == "output_store" and row_index == group_rows - 1:
                return "output_store"
            return f"row{row_index}_{base}"

        previous_output = None
        last_scalar = None
        for row_index in range(group_rows):
            input_queue = row_name("input_queue_control", row_index)
            input_load = row_name("input_load", row_index)
            reduce = f"row{row_index}_input_square_reduce"
            scalar = f"row{row_index}_local_scalar_dependency"
            output_scale = f"row{row_index}_output_scale"
            gamma_apply = f"row{row_index}_gamma_apply"
            final_cast = f"row{row_index}_final_cast"
            output_queue = f"row{row_index}_output_queue_control"
            output_store = row_name("output_store", row_index)

            expected_start = (() if previous_output is None
                              else (previous_output,))
            assert stages[input_queue].start_predecessors == expected_start
            assert positions[input_queue] < positions[input_load]
            assert positions[input_load] < positions[reduce]
            assert positions[reduce] < positions[scalar]
            assert positions[scalar] < positions[output_scale]
            assert positions[output_scale] < positions[gamma_apply]
            assert positions[gamma_apply] < positions[final_cast]
            assert positions[final_cast] < positions[output_queue]
            assert positions[output_queue] < positions[output_store]
            if previous_output is not None:
                # The source loop may issue the next CopyIn after CopyOutY,
                # but the depth-one Y queue cannot be reused before the
                # preceding MTE3 transfer completes.
                assert stages[gamma_apply].predecessors == (
                    output_scale, previous_output)
            previous_output = output_store
            last_scalar = scalar

        assert stages["rstd_queue_control"].start_predecessors == (
            last_scalar, previous_output)
        assert stages["rstd_store"].predecessors == (
            last_scalar, "rstd_queue_control")

