    def test_ascend_rms_split_d_pipeline_conserves_source_program(self):
        rows = 6145
        hidden = 16384
        kernel, resource_input = self._ascend_rms_split_d_input(
            rows, hidden)
        plan = resource_input.pipeline_plan

        assert resource_input.support_level == "partial"
        assert resource_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_PLUS_SOURCE_PROGRAM)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert plan is not None
        assert plan.worker_count == kernel.launch.grid_size == 48
        assert plan.buffers == ()
        explicit = _expand_pipeline_work_plan(plan)
        memory_bytes = {}
        generic_operations = 0.0
        exact_operations = 0.0
        generic_by_stage = {
            "reduce_compute": 0.0,
            "normalize_input": 0.0,
            "output_compute": 0.0,
        }
        shared_seen = set()
        for entry in explicit.tasks:
            tasks = (
                entry.tasks
                if isinstance(entry, PipelineTaskSequenceDemand)
                else (entry,))
            for task in tasks:
                for stage in task.stages:
                    stage_generic = math.fsum(
                        demand.operations
                        for demand in stage.compute_service_demands)
                    generic_operations += stage_generic
                    if stage.name in generic_by_stage:
                        generic_by_stage[stage.name] += stage_generic
                    exact_operations += math.fsum(
                        demand.operations
                        for demand in stage.compute_exact_request_demands)
                    for demand in stage.memory_node_demands:
                        key = (demand.path_name, demand.resource_role)
                        memory_bytes[key] = (
                            memory_bytes[key] + demand.bytes
                            if key in memory_bytes else demand.bytes)
                    for demand in stage.launch_shared_memory_node_demands:
                        key = (
                            stage.name, demand.path_name,
                            demand.resource_role)
                        if key in shared_seen:
                            continue
                        shared_seen.add(key)
                        memory_key = (
                            demand.path_name, demand.resource_role)
                        memory_bytes[memory_key] = (
                            memory_bytes[memory_key] + demand.bytes
                            if memory_key in memory_bytes else demand.bytes)
        aggregate_memory_bytes = {
            (path.name, node.resource_role): node.bytes
            for path in resource_input.memory_paths
            for node in path.nodes
        }
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        generic, = vector_demand.service_demands
        exact, = vector_demand.exact_request_demands

        assert memory_bytes == aggregate_memory_bytes
        assert generic.service == "generic"
        assert exact.service == "norm_sqrt_duplicate_div_serialized"
        assert generic_operations == generic.operations
        assert exact_operations == exact.operations == float(rows)
        assert generic_operations + exact_operations == (
            vector_demand.operations) == float(rows * (8 * hidden + 2))
        assert generic_by_stage == {
            "reduce_compute": float(3 * rows * hidden),
            "normalize_input": float(rows),
            "output_compute": float(5 * rows * hidden),
        }

