    @pytest.mark.parametrize(
        ("rows", "worker_count", "block_factor", "group_count"),
        (
            (1, 1, 1, 1),
            (2, 2, 1, 2),
            (64, 32, 2, 32),
            (256, 43, 6, 43),
            (1024, 47, 22, 47),
            (4096, 48, 86, 95),
        ),
    )
    def test_ascend_add_rms_key31_binds_split_d_source_program(
            self, rows, worker_count, block_factor, group_count):
        kernel, resource_input = self._ascend_add_rms_key31_input(rows)
        plan = resource_input.pipeline_plan

        def _stage_occurrences():
            """Flatten source programs while retaining physical multiplicity."""

            for entry in plan.tasks:
                if isinstance(entry, PipelineTaskDemand):
                    task_occurrences = ((entry, entry.repeat_count),)
                elif isinstance(entry, PipelineTaskSequenceDemand):
                    task_occurrences = tuple(
                        (task, task.repeat_count * entry.repeat_count)
                        for task in entry.tasks)
                elif isinstance(entry, PipelineTaskProgramDemand):
                    pattern_counts = [0] * len(entry.patterns)
                    for pattern_index in entry.order:
                        pattern_counts[pattern_index] += entry.repeat_count
                    for pattern_index in entry.tail_order:
                        pattern_counts[pattern_index] += 1
                    population = len(entry.physical_workers)
                    task_occurrences = tuple(
                        (
                            task,
                            task.repeat_count * sequence.repeat_count
                            * count * population,
                        )
                        for sequence, count in zip(
                            entry.patterns, pattern_counts)
                        if count
                        for task in sequence.tasks)
                else:
                    raise AssertionError(
                        f"unexpected key-31 pipeline entry: {entry!r}")
                for task, multiplicity in task_occurrences:
                    for stage in task.stages:
                        yield stage, multiplicity

        assert plan is not None
        assert plan.worker_count == worker_count
        # Every physical worker owns its launch-shared first group.  Only the
        # source-identical remaining row groups are compressed, so the plan
        # stays fixed-size for large Split-D launches.
        assert len(plan.tasks) >= worker_count
        assert sum(
            entry.worker_multiplicity
            for entry in plan.tasks
            if isinstance(entry, PipelineTaskProgramDemand)) <= worker_count
        assert int(kernel.launch.parameters["norm_block_factor"]) == (
            block_factor)
        assert kernel.launch.parameters[
            "source_bound_add_rmsnorm_split_d_dag"] == 1.0
        assert resource_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_COMPETING_SOURCE_FLOOR)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert plan.buffers == (
            PipelineBuffer(
                "key31_former_loop_issue", "former_input_queue_control",
                "former_reduce", 1, "worker", "start"),
            PipelineBuffer(
                "key31_former_output_queue",
                "former_output_queue_control",
                "residual_store", 1, "worker"),
            PipelineBuffer(
                "key31_latter_input_issue_queue",
                "latter_input_queue_control",
                "latter_store", 1, "worker", "start"),
            PipelineBuffer(
                "key31_latter_output_queue",
                "latter_output_queue_control",
                "latter_store", 1, "worker"),
            PipelineBuffer(
                "key31_rstd_output_queue", "rstd_queue_control",
                "rstd_store",
                1, "worker"),
        )
        exact_demands = tuple(
            demand
            for stage, _ in _stage_occurrences()
            if stage.name.endswith("scalar_normalization")
            for demand in stage.memory_exact_request_demands)
        assert not exact_demands
        rstd_requests = tuple(
            demand.request_sizes_by_worker
            for stage, multiplicity in _stage_occurrences()
            if stage.name.endswith("scalar_normalization")
            for demand in stage.compute_exact_request_demands
            for _ in range(multiplicity))
        assert len(rstd_requests) == group_count
        assert all(len(request) == 1 for request in rstd_requests)
        rstd_initialization_stages = tuple(
            (demand.operations, multiplicity)
            for stage, multiplicity in _stage_occurrences()
            if stage.name == "rstd_init"
            for demand in stage.compute_service_demands
            if demand.service == "generic")
        assert rstd_initialization_stages
        assert all(0.0 < operations <= 64.0
                   for operations, _ in rstd_initialization_stages)
        assert math.fsum(
            operations * multiplicity
            for operations, multiplicity in rstd_initialization_stages
        ) == float(rows)
        scalar_handoff_requests = tuple(
            demand.request_sizes_by_worker
            for stage, multiplicity in _stage_occurrences()
            if stage.name == "latter_scalar_handoff"
            for demand in stage.compute_exact_request_demands
            for _ in range(multiplicity))
        assert len(scalar_handoff_requests) == rows * 2
        assert all(request == ((1,),) for request in scalar_handoff_requests)
        scalar_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "scalar_aiv")
        scalar_handoff_demand, = tuple(
            demand for demand in scalar_demand.exact_request_demands
            if demand.service == (
                "add_rmsnorm_split_d_local_scalar_handoff"))
        queue_control_demand, = tuple(
            demand for demand in scalar_demand.exact_request_demands
            if demand.service == "aiv_queue_control_cycle")
        rows_by_worker = (
            (block_factor,) * (worker_count - 1)
            + (rows - (worker_count - 1) * block_factor,))
        assert scalar_handoff_demand.request_sizes_by_worker == tuple(
            (1,) * (worker_rows * 2)
            for worker_rows in rows_by_worker)
        groups_by_worker = tuple(
            math.ceil(worker_rows / 64)
            for worker_rows in rows_by_worker)
        source_groups_by_worker = tuple(
            tuple(
                min(64, worker_rows - offset)
                for offset in range(0, worker_rows, 64))
            for worker_rows in rows_by_worker)
        tile_count = math.ceil(kernel.shape["hidden"] / 8192)
        full_repeats_by_worker = tuple(
            tile_count * sum(group_rows // 8 for group_rows in groups)
            for groups in source_groups_by_worker)
        full_invocations_by_worker = tuple(
            tile_count * sum(group_rows >= 8 for group_rows in groups)
            for groups in source_groups_by_worker)
        tail_invocations_by_worker = tuple(
            tile_count * sum(group_rows % 8 != 0 for group_rows in groups)
            for groups in source_groups_by_worker)
        reduction_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_reduction")
        reduction_services = {
            demand.service: demand for demand in reduction_demand.service_demands}
        if sum(full_repeats_by_worker):
            full_service = reduction_services[
                "cann_add_rmsnorm_split_d_block_reduce_full64"]
            assert full_service.operations == float(sum(full_repeats_by_worker))
            assert full_service.operations_by_worker == tuple(
                float(value) for value in full_repeats_by_worker)
            assert full_service.serial_invocations == max(
                full_invocations_by_worker)
            assert full_service.serial_invocations_by_worker == (
                full_invocations_by_worker)
        else:
            assert "cann_add_rmsnorm_split_d_block_reduce_full64" not in (
                reduction_services)
        if sum(tail_invocations_by_worker):
            tail_service = reduction_services[
                "cann_add_rmsnorm_split_d_block_reduce_tail8"]
            assert tail_service.operations == float(sum(tail_invocations_by_worker))
            assert tail_service.operations_by_worker == tuple(
                float(value) for value in tail_invocations_by_worker)
            assert tail_service.serial_invocations == 0
            assert tail_service.serial_invocations_by_worker == (
                (0,) * worker_count)
        else:
            assert "cann_add_rmsnorm_split_d_block_reduce_tail8" not in (
                reduction_services)
        # CANN Split-D owns two Former queues, one gamma queue, two Latter
        # queues and one rstd queue.  At H=16,384, its static source loop
        # has two 8,192-column tiles: 8R + 3G lifetimes per worker.
        assert queue_control_demand.request_sizes_by_worker == tuple(
            (1,) * (8 * worker_rows + 3 * groups)
            for worker_rows, groups in zip(
                rows_by_worker, groups_by_worker))
        queue_stage_counts = {}
        for stage, multiplicity in _stage_occurrences():
            if stage.name not in {
                    "former_input_queue_control",
                    "former_output_queue_control",
                    "gamma_queue_control",
                    "latter_input_queue_control",
                    "latter_output_queue_control",
                    "rstd_queue_control"}:
                continue
            exact, = stage.compute_exact_request_demands
            assert exact.service == "aiv_queue_control_cycle"
            assert exact.request_sizes_by_worker == ((1,),)
            queue_stage_counts[stage.name] = (
                queue_stage_counts[stage.name] + multiplicity
                if stage.name in queue_stage_counts else multiplicity)
        assert queue_stage_counts == {
            "former_input_queue_control": 2 * rows,
            "former_output_queue_control": 2 * rows,
            "gamma_queue_control": 2 * group_count,
            "latter_input_queue_control": 2 * rows,
            "latter_output_queue_control": 2 * rows,
            "rstd_queue_control": group_count,
        }
        representative, = tuple(
            entry for entry in plan.tasks
            if (isinstance(entry, PipelineTaskSequenceDemand)
                and entry.worker == 0))
        stage_by_name = {
            stage.name: stage
            for task in representative.tasks
            for stage in task.stages}
        assert "key31_gamma_seed" in stage_by_name
        assert "rstd_init" in stage_by_name
        first_former, = tuple(
            task for task in representative.tasks
            if task.name == "key31_former_t0_first")
        first_former_stage_by_name = {
            stage.name: stage for stage in first_former.stages}
        assert first_former_stage_by_name[
            "former_input_queue_control"].predecessors == (
            "rstd_init",)
        assert first_former_stage_by_name["former_input"].predecessors == (
            "former_input_queue_control",)
        assert stage_by_name[
            "former_reduce"].start_predecessors == ("residual_store",)
        if block_factor > 1:
            former_steady = next(
                task for task in representative.tasks
                if task.name == "key31_former_t0_steady")
            latter_steady = next(
                task for task in representative.tasks
                if task.name == "key31_latter_t0_steady")
            assert former_steady.stages[0].predecessors == ()
            assert latter_steady.stages[0].predecessors == ()
            assert latter_steady.stages[1].predecessors == (
                "latter_input_queue_control",)
        aggregate_memory_bytes = {
            (path.name, node.resource_role): node.bytes
            for path in resource_input.memory_paths
            for node in path.nodes}
        row_bytes = 2 * kernel.shape["hidden"]
        assert aggregate_memory_bytes[("mte2_read", "dram")] == float(
            (3 * rows + group_count) * row_bytes)
        staged_memory_bytes = {}
        shared_memory_bytes = {}
        gamma_stages = []
        latter_input_stages = []
        for stage, multiplicity in _stage_occurrences():
            if stage.name in ("key31_gamma_seed", "gamma_load"):
                gamma_stages.append(stage)
            elif stage.name == "latter_input":
                latter_input_stages.append(stage)
            for demand in stage.memory_node_demands:
                key = (demand.path_name, demand.resource_role)
                staged_memory_bytes[key] = (
                    staged_memory_bytes[key]
                    + demand.bytes * multiplicity
                    if key in staged_memory_bytes
                    else demand.bytes * multiplicity)
            for demand in stage.launch_shared_memory_node_demands:
                key = (stage.name, demand.path_name, demand.resource_role)
                if key in shared_memory_bytes:
                    assert shared_memory_bytes[key] == demand.bytes
                else:
                    shared_memory_bytes[key] = demand.bytes
        for (_, path_name, role), byte_count in shared_memory_bytes.items():
            key = (path_name, role)
            staged_memory_bytes[key] = (
                staged_memory_bytes[key] + byte_count
                if key in staged_memory_bytes else byte_count)
        assert gamma_stages
        assert latter_input_stages
        assert all(
            {demand.resource_role for demand in stage.memory_node_demands}
            == {"mte2", "l2_cache", "dram"}
            and not stage.launch_shared_memory_node_demands
            for stage in gamma_stages + latter_input_stages)
        assert staged_memory_bytes == aggregate_memory_bytes
        PerformanceFormula(ASCEND_HARDWARE).predict_kernel(resource_input)

    @pytest.mark.parametrize(
        ("hidden", "expected_tile_widths"),
        (
            (12289, (8192, 4097)),
            (16384, (8192, 8192)),
        ),
    )
    def test_ascend_add_rms_key31_queue_lifetimes_cover_split_d_tail(
            self, hidden, expected_tile_widths):
        kernel, resource_input = self._ascend_add_rms_key31_input(
            rows=64, hidden=hidden)
        plan = resource_input.pipeline_plan

        assert kernel.launch.parameters["cann_tiling_key"] == 31.0
        assert plan is not None
        first_group, = tuple(
            entry for entry in plan.tasks
            if (isinstance(entry, PipelineTaskSequenceDemand)
                and entry.worker == 0))
        former_input_bytes = tuple(
            next(
                demand.bytes
                for stage in task.stages if stage.name == "former_input"
                for demand in stage.memory_node_demands
                if demand.resource_role == "mte2")
            for task in first_group.tasks
            if (task.name.startswith("key31_former_t")
                and task.name.endswith("_first")))
        assert former_input_bytes == tuple(
            float(4 * width) for width in expected_tile_widths)
        scalar_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "scalar_aiv")
        queue_control_demand, = tuple(
            demand for demand in scalar_demand.exact_request_demands
            if demand.service == "aiv_queue_control_cycle")
        # Every 64-row source worker has one group.  Both the tail and full
        # tile program therefore retain the same 4RT + GT + G control count.
        assert queue_control_demand.request_sizes_by_worker == (
            ((1,) * (8 * 2 + 3),) * 32)

    def test_ascend_add_rms_key31_forward_reuses_source_program(self):
        kernel, source_input = self._ascend_add_rms_key31_input(rows=4096)
        forward_input, _ = forward_analytical_resource_input(
            kernel, ASCEND_HARDWARE)

        assert source_input.pipeline_plan == forward_input.pipeline_plan
        assert source_input.pipeline_plan is not None
        assert any(
            isinstance(entry, PipelineTaskProgramDemand)
            for entry in source_input.pipeline_plan.tasks)
        source = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            source_input)
        forward = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            forward_input)
        assert forward.t_total_s == pytest.approx(source.t_total_s, rel=1e-12)

    @pytest.mark.parametrize("hidden", (12289, 16384))
    def test_ascend_add_rms_key31_full_cohort_keeps_source_fill_order(
            self, hidden):
        """A full initial AIV cohort cannot erase its source body.

        The fixed key-31 source program gives every worker one equal row at
        T47/T48.  At T48 the whole empty-task interval has one more admitted
        worker, but the source body begins at that worker's first instruction;
        only the measured worker-fill span may separate the two completions.
        Thus the empty shell is a competing floor rather than a serial prefix
        whose noisy terminal value could make T48 faster than T47.
        """

        _, forty_seven_input = self._ascend_add_rms_key31_input(
            rows=47, hidden=hidden)
        _, forty_eight_input = self._ascend_add_rms_key31_input(
            rows=48, hidden=hidden)
        assert forty_seven_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_COMPETING_SOURCE_FLOOR)
        assert forty_eight_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_COMPETING_SOURCE_FLOOR)
        forty_seven = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            forty_seven_input)
        forty_eight = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            forty_eight_input)

        for resource_input, prediction in (
                (forty_seven_input, forty_seven),
                (forty_eight_input, forty_eight)):
            prologue_ns = (
                resource_input.task_prologue_repetitions
                * ASCEND_HARDWARE.task_prologue_duration_ns(
                    resource_input.task_prologue_contract,
                    resource_input.active_units))
            worker_fill_ns = ASCEND_HARDWARE.aiv_worker_start_fill_ns(
                resource_input.active_units)
            empty_task_ns = ASCEND_HARDWARE.empty_kernel_duration_for_task(
                "aiv", resource_input.grid_size,
                resource_input.block_size, resource_input.launch_grid,
                resource_input.launch_block)
            source_completion_ns = (
                prediction.t_per_group["pipeline"] * 1e9
                + max(prologue_ns, worker_fill_ns))
            assert prediction.t_total_ns == pytest.approx(
                max(empty_task_ns, source_completion_ns))
            assert (
                "cann_add_rmsnorm_key31_source_entry_absolute_latency_unavailable"
                in resource_input.limitations)

        assert forty_eight.t_total_s > forty_seven.t_total_s
        assert forty_eight.t_total_ns - forty_seven.t_total_ns == (
            pytest.approx(
                ASCEND_HARDWARE.aiv_worker_start_fill_ns(48)
                - ASCEND_HARDWARE.aiv_worker_start_fill_ns(47)))

    @pytest.mark.parametrize("hidden", (12289, 16384))
    def test_ascend_add_rms_key31_worker_repartition_keeps_source_envelope(
            self, hidden):
        """Exercise both physical worker-repartition boundaries.

        T48→49 doubles the maximum owned rows and must expose a longer
        source chain. T64→65 keeps the same two-row source chain but admits
        one additional worker, so only the independently measured 40-ns
        fill interval changes. These are source-program consequences, not a
        general monotonicity rule.
        """

        predictions = {}
        for rows in (47, 48, 49, 50, 63, 64, 65):
            _, resource_input = self._ascend_add_rms_key31_input(
                rows=rows, hidden=hidden)
            predictions[rows] = PerformanceFormula(
                ASCEND_HARDWARE).predict_kernel(resource_input)

        assert predictions[48].t_total_s > predictions[47].t_total_s
        assert predictions[49].t_total_s > predictions[48].t_total_s
        assert predictions[50].t_total_s >= predictions[49].t_total_s
        assert predictions[64].t_total_s >= predictions[63].t_total_s
        assert predictions[65].t_total_ns - predictions[64].t_total_ns == (
            pytest.approx(
                ASCEND_HARDWARE.aiv_worker_start_fill_ns(33)
                - ASCEND_HARDWARE.aiv_worker_start_fill_ns(32)))

    def test_ascend_add_rms_key31_source_program_covers_noncaptured_launch(self):
        _, resource_input = self._ascend_add_rms_key31_input(rows=2)

        assert resource_input.pipeline_plan is not None

    def test_ascend_add_rms_key31_requires_split_d_source_identity(self):
        kernel, _ = self._ascend_add_rms_key31_input(rows=256)
        parameters = dict(kernel.launch.parameters)
        del parameters["source_bound_add_rmsnorm_split_d_dag"]
        with pytest.raises(ValueError, match="Split-D DAG identity"):
            changed = dataclasses.replace(
                kernel,
                launch=dataclasses.replace(
                    kernel.launch, parameters=parameters))
            create_predictor(changed.kind).resource_input(
                changed, ASCEND_HARDWARE)

    def test_ascend_add_rms_key31_counts_each_column_tile_invocation(self):
        _, resource_input = self._ascend_add_rms_key31_input(rows=1)
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        serial_counts = {
            demand.service: demand.serial_invocations
            for demand in vector_demand.service_demands}

        # H=16,384 has two fixed 8,192-column source tiles.  The aggregate
        # element work is unchanged, but each tile invokes its typed cast and
        # arithmetic helpers independently.
        assert serial_counts["cast_bf16_to_fp32_serialized"] == 10
        assert serial_counts["cast_fp32_to_bf16_serialized"] == 6
        assert serial_counts["mul_serialized"] == 4
        assert serial_counts["muls_serialized"] == 4

    def test_ascend_add_rms_key31_requires_block_reduce_source_services(self):
        hardware = copy.deepcopy(ASCEND_HARDWARE)
        reduction = hardware.resource_by_role("compute_reduction")
        del reduction.service_rates_per_unit_s[
            "cann_add_rmsnorm_split_d_block_reduce_full64"]
        kernel, _ = self._ascend_add_rms_key31_input(rows=1024)

        with pytest.raises(ValueError, match="BlockReduce source service"):
            create_predictor(kernel.kind).resource_input(kernel, hardware)

    def test_ascend_add_rms_key31_does_not_consume_launch_span_service(self):
        hardware = copy.deepcopy(ASCEND_HARDWARE)
        service = hardware.resource_by_role("mte2").exact_request_services[
            "add_rmsnorm_key31_residual_reload_completion_chain"]
        kernel, baseline_input = self._ascend_add_rms_key31_input(rows=256)
        baseline = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            baseline_input)
        service["service_time_s_by_request_size"][12] = 100e-6
        changed_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)
        changed = PerformanceFormula(hardware).predict_kernel(changed_input)

        assert changed.t_total_s == pytest.approx(baseline.t_total_s)

    def _ascend_add_rms_single_n_input(self, rows=4, hidden=2048):
        shape = {"rows": rows, "hidden": hidden}
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "add_rmsnorm", {}, hardware=ASCEND_HARDWARE)
        kernel = KernelSpec(
            KernelKind.VECTOR, ASCEND_HARDWARE.hardware_id, shape,
            dtype="bf16", variant=launch.execution_variant, launch=launch)
        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)
        return kernel, resource_input

    def test_ascend_add_rms_single_n_pipeline_conserves_source_work(self):
        rows = 4
        hidden = 2048
        _, resource_input = self._ascend_add_rms_single_n_input(
            rows, hidden)
        plan = resource_input.pipeline_plan

        assert resource_input.support_level == "partial"
        assert resource_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_PLUS_SOURCE_PROGRAM)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert resource_input.aiv_descriptor_prologue_pipeline is False
        assert plan is not None
        assert plan.worker_count == rows
        assert len(plan.tasks) == rows
        assert plan.buffers == (PipelineBuffer(
            "single_n_ub", "input_x1_load", "output_store", 1, "worker"),)
        expected_stages = (
            "input_x1_load", "input_x2_load", "input_x1_cast",
            "input_compute", "gamma_load", "residual_store",
            "reduce_compute", "reduction_dependency", "epsilon_add",
            "reciprocal_sqrt", "rstd_store", "output_scale",
            "residual_roundtrip", "gamma_apply", "final_cast",
            "output_store",
        )
        assert all(
            tuple(stage.name for stage in task.stages) == expected_stages
            for task in plan.tasks)

        _, one_worker_input = self._ascend_add_rms_single_n_input(
            rows=1, hidden=hidden)
        assert one_worker_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_PLUS_SOURCE_PROGRAM)
        assert one_worker_input.aiv_descriptor_prologue_pipeline is False

        memory_bytes = {}
        generic_operations = 0.0
        generic_operations_by_stage = {}
        exact_requests = []
        for task in plan.tasks:
            for stage in task.stages:
                stage_operations = math.fsum(
                    demand.operations
                    for demand in stage.compute_service_demands)
                generic_operations += stage_operations
                if stage_operations > 0:
                    if stage.name in generic_operations_by_stage:
                        generic_operations_by_stage[stage.name] += (
                            stage_operations)
                    else:
                        generic_operations_by_stage[stage.name] = (
                            stage_operations)
                for demand in stage.compute_exact_request_demands:
                    worker_requests, = demand.request_sizes_by_worker
                    exact_requests.append(worker_requests)
                for demand in stage.memory_node_demands:
                    key = (demand.path_name, demand.resource_role)
                    memory_bytes[key] = (
                        memory_bytes[key] + demand.bytes
                        if key in memory_bytes else demand.bytes)
                if task.worker == 0:
                    for demand in (
                            stage.launch_shared_memory_node_demands):
                        key = (demand.path_name, demand.resource_role)
                        memory_bytes[key] = (
                            memory_bytes[key] + demand.bytes
                            if key in memory_bytes else demand.bytes)
        aggregate_memory_bytes = {
            (path.name, node.resource_role): node.bytes
            for path in resource_input.memory_paths
            for node in path.nodes
        }
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        services = {
            demand.service: demand
            for demand in vector_demand.service_demands}
        exact, = vector_demand.exact_request_demands

        assert memory_bytes == aggregate_memory_bytes
        assert generic_operations == float(
            rows * (15 * hidden + 1))
        assert tuple(services) == (
            "cast_bf16_to_fp32_serialized", "generic",
            "cast_fp32_to_bf16_serialized", "mul_serialized",
            "muls_serialized")
        assert services["cast_bf16_to_fp32_serialized"].operations == float(
            5 * rows * hidden)
        assert services["cast_fp32_to_bf16_serialized"].operations == float(
            3 * rows * hidden)
        assert services["mul_serialized"].operations == float(
            2 * rows * hidden)
        assert services["muls_serialized"].operations == float(
            2 * rows * hidden)
        assert services["generic"].operations_by_worker == (
            float(3 * hidden + 1),) * rows
        assert generic_operations_by_stage == {
            "input_x1_cast": float(rows * hidden),
            "input_compute": float(3 * rows * hidden),
            "reduce_compute": float(rows * 5 * hidden),
            "epsilon_add": float(rows),
            "output_scale": float(rows * hidden),
            "residual_roundtrip": float(2 * rows * hidden),
            "gamma_apply": float(2 * rows * hidden),
            "final_cast": float(rows * hidden),
        }
        assert tuple(exact_requests) == exact.request_sizes_by_worker
        assert exact.request_sizes_by_worker == ((1,),) * rows
        for task in plan.tasks:
            gamma = next(
                stage for stage in task.stages
                if stage.name == "gamma_load")
            assert gamma.memory_node_demands == (
                PhaseMemoryDemand(
                    "mte2_read", "mte2", float(2 * hidden)),
                PhaseMemoryDemand(
                    "mte2_read", "l2_cache", float(2 * hidden)),)
            assert gamma.launch_shared_memory_node_demands == (
                PhaseMemoryDemand(
                    "mte2_read", "dram", float(2 * hidden)),)

    def test_ascend_add_rms_single_n_forward_envelope_matches_source_dag(
            self, monkeypatch):
        rows = 16
        kernel, _ = self._ascend_add_rms_single_n_input(
            rows=rows, hidden=2560)
        monkeypatch.setattr(
            vector_predictor,
            "_cann_unloaded_memory_completion_request",
            lambda *args: (),
        )
        _, source_input = self._ascend_add_rms_single_n_input(
            rows=rows, hidden=2560)
        compact_input, _ = forward_analytical_resource_input(
            kernel, ASCEND_HARDWARE)
        compact_plan = compact_input.pipeline_plan

        assert compact_plan is not None
        assert len(compact_plan.tasks) == 1
        compact_program, = compact_plan.tasks
        assert isinstance(compact_program, PipelineTaskProgramDemand)
        assert compact_program.worker_multiplicity == rows
        assert compact_program.physical_workers == tuple(range(rows))
        explicit_compact = _expand_pipeline_work_plan(compact_plan)
        assert all(
            not stage.memory_exact_request_demands
            for sequence in explicit_compact.tasks
            for task in sequence.tasks
            for stage in task.stages)
        first_compact_sequence = explicit_compact.tasks[0]
        first_compact_task, = first_compact_sequence.tasks
        assert tuple(
            stage.name for stage in first_compact_task.stages
        ) == tuple(
            stage.name for stage in source_input.pipeline_plan.tasks[0].stages
        )
        assert compact_input.memory_paths == source_input.memory_paths
        assert compact_input.compute_demands == source_input.compute_demands
        source = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            source_input)
        compact = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            compact_input)
        assert compact.t_total_s == pytest.approx(source.t_total_s, rel=1e-12)

    def test_ascend_add_rms_single_n_pipeline_preserves_event_dag_and_drain(
            self):
        _, resource_input = self._ascend_add_rms_single_n_input()
        task = resource_input.pipeline_plan.tasks[0]
        stages = {stage.name: stage for stage in task.stages}

        assert stages["input_x1_load"].predecessors == ()
        assert stages["input_x2_load"].predecessors == ()
        assert stages["input_x2_load"].start_predecessors == (
            "input_x1_load",)
        assert stages["input_x1_cast"].predecessors == ("input_x1_load",)
        assert stages["input_compute"].predecessors == (
            "input_x1_cast", "input_x2_load")
        assert stages["residual_store"].predecessors == ("input_compute",)
        assert stages["residual_store"].start_predecessors == (
            "gamma_load",)
        assert stages["reduce_compute"].predecessors == ("input_compute",)
        assert stages["reduce_compute"].start_predecessors == (
            "residual_store",)
        assert stages["reduction_dependency"].predecessors == (
            "reduce_compute",)
        assert stages["epsilon_add"].predecessors == (
            "reduction_dependency",)
        assert stages["reciprocal_sqrt"].predecessors == (
            "epsilon_add",)
        assert stages["rstd_store"].predecessors == (
            "reciprocal_sqrt",)
        assert stages["output_scale"].predecessors == (
            "reciprocal_sqrt",)
        assert stages["output_scale"].start_predecessors == ("rstd_store",)
        assert stages["residual_roundtrip"].predecessors == (
            "output_scale", "residual_store")
        assert stages["gamma_apply"].predecessors == (
            "gamma_load", "rstd_store", "residual_roundtrip")
        assert stages["final_cast"].predecessors == ("gamma_apply",)
        assert stages["output_store"].predecessors == ("final_cast",)

        prediction = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            resource_input)
        pipeline = prediction.diagnostics.pipeline
        first = pipeline.tasks[0]
        mte2 = next(
            diagnostic for diagnostic in prediction.diagnostics.memory
            if diagnostic.path_name == "mte2_read")
        capacity_by_role = {
            node.resource_role: node.byte_capacity_per_s
            for node in mte2.nodes
        }
        gamma_duration = (
            first.stage_end_s["gamma_load"]
            - first.stage_start_s["gamma_load"])
        assert gamma_duration == pytest.approx(max(
            2 * 2048 * 4 / capacity_by_role["mte2"],
            2 * 2048 * 4 / capacity_by_role["l2_cache"],
            2 * 2048 / capacity_by_role["dram"],
        ))
        assert first.stage_start_s["gamma_load"] <= (
            first.stage_start_s["residual_store"])
        assert first.stage_start_s["residual_store"] <= (
            first.stage_start_s["reduce_compute"])
        assert first.stage_start_s["output_scale"] == pytest.approx(
            first.stage_start_s["rstd_store"])
        assert first.stage_start_s["output_scale"] < (
            first.stage_end_s["rstd_store"])
        assert first.stage_start_s["residual_roundtrip"] >= max(
            first.stage_end_s["output_scale"],
            first.stage_end_s["residual_store"])
        assert first.stage_start_s["gamma_apply"] >= max(
            first.stage_end_s[name]
            for name in (
                "gamma_load", "rstd_store", "residual_roundtrip"))
        assert first.stage_start_s["final_cast"] >= (
            first.stage_end_s["gamma_apply"])
        assert first.stage_end_s["output_store"] == pytest.approx(
            pipeline.worker_makespan_s["0"])

