    @pytest.mark.parametrize("mutated_stage", ("memory", "exact"))
    def test_ascend_add_rms_single_n_pipeline_fails_on_nonconservation(
            self, mutated_stage):
        _, resource_input = self._ascend_add_rms_single_n_input()
        plan = resource_input.pipeline_plan
        task = plan.tasks[0]
        tasks = list(plan.tasks)
        if mutated_stage == "memory":
            for task_index, current_task in enumerate(tasks):
                stages = list(current_task.stages)
                stage_index = next(
                    index for index, stage in enumerate(stages)
                    if stage.name == "input_x1_load")
                stage = stages[stage_index]
                nodes = list(stage.memory_node_demands)
                nodes[0] = dataclasses.replace(
                    nodes[0], bytes=nodes[0].bytes + 1)
                stages[stage_index] = dataclasses.replace(
                    stage, memory_node_demands=tuple(nodes))
                tasks[task_index] = dataclasses.replace(
                    current_task, stages=tuple(stages))
            match = "memory-node bytes must conserve"
        elif mutated_stage == "exact":
            stages = list(task.stages)
            stage_index = next(
                index for index, stage in enumerate(stages)
                if stage.name == "reduce_compute")
            stage = stages[stage_index]
            stages[stage_index] = dataclasses.replace(
                stage,
                compute_exact_request_demands=(
                    ComputeExactRequestDemand(
                        "norm_sqrt_duplicate_div_serialized", ((2,),)),),
            )
            tasks[0] = dataclasses.replace(task, stages=tuple(stages))
            match = "exact requests must conserve"
        else:
            raise AssertionError(mutated_stage)
        malformed = dataclasses.replace(
            resource_input,
            pipeline_plan=dataclasses.replace(plan, tasks=tuple(tasks)),
        )

        with pytest.raises(ValueError, match=match):
            PerformanceFormula(ASCEND_HARDWARE).predict_kernel(malformed)

    @pytest.mark.parametrize(
        "scope", ("per_worker", "launch_shared", "dependency"))
    def test_ascend_add_rms_single_n_memory_stages_require_symmetry(
            self, scope):
        _, resource_input = self._ascend_add_rms_single_n_input()
        plan = resource_input.pipeline_plan
        tasks = list(plan.tasks)
        task = tasks[0]
        stages = list(task.stages)
        stage_index = next(
            index for index, stage in enumerate(stages)
            if stage.name == "gamma_load")
        stage = stages[stage_index]
        if scope == "per_worker":
            demands = list(stage.memory_node_demands)
            demands[0] = dataclasses.replace(
                demands[0], bytes=demands[0].bytes + 1)
            stages[stage_index] = dataclasses.replace(
                stage, memory_node_demands=tuple(demands))
        elif scope == "launch_shared":
            demands = list(stage.launch_shared_memory_node_demands)
            demands[0] = dataclasses.replace(
                demands[0], bytes=demands[0].bytes + 1)
            stages[stage_index] = dataclasses.replace(
                stage,
                launch_shared_memory_node_demands=tuple(demands))
        elif scope == "dependency":
            stages[stage_index] = dataclasses.replace(
                stage, predecessors=())
        else:
            raise AssertionError(scope)
        tasks[0] = dataclasses.replace(task, stages=tuple(stages))
        malformed = dataclasses.replace(
            resource_input,
            pipeline_plan=dataclasses.replace(plan, tasks=tuple(tasks)),
        )

        with pytest.raises(ValueError, match="must be symmetric"):
            PerformanceFormula(ASCEND_HARDWARE).predict_kernel(malformed)

