    def test_ascend_add_rms_single_n_pipeline_requires_exact_source_facts(
            self):
        kernel, _ = self._ascend_add_rms_single_n_input()
        parameters = dict(kernel.launch.parameters)
        del parameters["source_bound_add_rmsnorm_single_n_dag"]
        missing_identity_launch = dataclasses.replace(
            kernel.launch, parameters=parameters)
        missing_identity = dataclasses.replace(
            kernel, launch=missing_identity_launch)
        with pytest.raises(ValueError, match="source-bound SingleN DAG"):
            create_predictor(missing_identity.kind).resource_input(
                missing_identity, ASCEND_HARDWARE)

        parameters = dict(kernel.launch.parameters)
        parameters["lowered_vector_reduce_operations"] += 1.0
        changed_work_launch = dataclasses.replace(
            kernel.launch, parameters=parameters)
        changed_work = dataclasses.replace(kernel, launch=changed_work_launch)
        with pytest.raises(ValueError, match="lowered work disagrees"):
            create_predictor(changed_work.kind).resource_input(
                changed_work, ASCEND_HARDWARE)

        key30_shape = {"rows": 49, "hidden": 2048}
        key30_launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, key30_shape,
            "bf16", "add_rmsnorm", {}, hardware=ASCEND_HARDWARE)
        key30_parameters = dict(key30_launch.parameters)
        key30_parameters["source_bound_add_rmsnorm_single_n_dag"] = 1.0
        with pytest.raises(ValueError, match="requires AddRmsNorm CANN key 33"):
            KernelSpec(
                KernelKind.VECTOR, ASCEND_HARDWARE.hardware_id, key30_shape,
                dtype="bf16", variant=key30_launch.execution_variant,
                launch=dataclasses.replace(
                    key30_launch, parameters=key30_parameters))

    def _ascend_add_rms_key30_input(self, rows=256, hidden=8192):
        shape = {"rows": rows, "hidden": hidden}
        launch = select_launch_config(
            ASCEND_HARDWARE.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "add_rmsnorm", {}, hardware=ASCEND_HARDWARE)
        kernel = KernelSpec(
            KernelKind.VECTOR, ASCEND_HARDWARE.hardware_id, shape,
            dtype="bf16", variant=launch.execution_variant, launch=launch)
        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)
        return kernel, resource_input

    def test_ascend_add_rms_key30_pipeline_conserves_source_program(self):
        rows = 256
        hidden = 8192
        kernel, resource_input = self._ascend_add_rms_key30_input(
            rows, hidden)
        plan = resource_input.pipeline_plan

        assert resource_input.support_level == "partial"
        assert resource_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_PLUS_SOURCE_PROGRAM)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert resource_input.aiv_descriptor_prologue_pipeline is False
        assert plan is not None
        assert plan.worker_count == kernel.launch.grid_size == 43
        assert plan.buffers == (
            PipelineBuffer(
                "add_rms_key30_y_queue", "input_load", "output_store", 1,
                "worker"),
            PipelineBuffer(
                "add_rms_key30_rstd_queue", "input_load", "rstd_store", 1,
                "worker"),
        )
        explicit = _expand_pipeline_work_plan(plan)
        memory_bytes = {}
        generic_operations = 0.0
        generic_by_stage = {
            "input": 0.0,
            "reduce": 0.0,
            "epsilon": 0.0,
            "output_scale": 0.0,
            "output_finalize": 0.0,
        }
        exact_requests = 0
        shared_seen = set()
        for task in explicit.tasks:
            for stage in task.stages:
                stage_operations = math.fsum(
                    demand.operations
                    for demand in stage.compute_service_demands)
                generic_operations += stage_operations
                if stage.name.endswith("_input_compute"):
                    generic_by_stage["input"] += stage_operations
                elif stage.name.endswith("_reduce_compute"):
                    generic_by_stage["reduce"] += stage_operations
                elif stage.name.endswith("_epsilon_add"):
                    generic_by_stage["epsilon"] += stage_operations
                elif stage.name.endswith("_output_scale"):
                    generic_by_stage["output_scale"] += stage_operations
                elif stage.name.endswith("_output_finalize"):
                    generic_by_stage["output_finalize"] += stage_operations
                if stage.service == "compute:compute_vector":
                    for demand in stage.compute_exact_request_demands:
                        worker_requests, = demand.request_sizes_by_worker
                        exact_requests += sum(worker_requests)
                for demand in stage.memory_node_demands:
                    key = (demand.path_name, demand.resource_role)
                    memory_bytes[key] = (
                        memory_bytes[key] + demand.bytes
                        if key in memory_bytes else demand.bytes)
                for demand in stage.launch_shared_memory_node_demands:
                    key = (
                        stage.name, demand.path_name, demand.resource_role)
                    if key in shared_seen:
                        continue
                    shared_seen.add(key)
                    memory_key = (demand.path_name, demand.resource_role)
                    memory_bytes[memory_key] = (
                        memory_bytes[memory_key] + demand.bytes
                        if memory_key in memory_bytes else demand.bytes)
        aggregate_memory_bytes = {
            (path.name, node.resource_role): node.bytes
            for path in resource_input.memory_paths
            for node in path.nodes
        }
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        services = {
            demand.service: demand
            for demand in vector_demand.service_demands}
        exact, = vector_demand.exact_request_demands
        scalar_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "scalar_aiv")

        assert memory_bytes == aggregate_memory_bytes
        assert generic_operations == float(
            rows * (13 * hidden + 1))
        assert tuple(services) == (
            "cast_bf16_to_fp32_serialized", "generic",
            "cast_fp32_to_bf16_serialized", "mul_serialized",
            "muls_serialized", "add_rmsnorm_reduce_sum_fp32")
        assert services["cast_bf16_to_fp32_serialized"].operations == float(
            4 * rows * hidden)
        assert services["cast_fp32_to_bf16_serialized"].operations == float(
            3 * rows * hidden)
        assert services["mul_serialized"].operations == float(
            2 * rows * hidden)
        assert services["muls_serialized"].operations == float(
            2 * rows * hidden)
        assert services[
            "add_rmsnorm_reduce_sum_fp32"].operations == float(
                rows * hidden)
        assert services[
            "add_rmsnorm_reduce_sum_fp32"].serial_invocations_by_worker == (
                (6,) * 42 + (4,))
        assert generic_by_stage == {
            "input": float(4 * rows * hidden),
            "reduce": float(rows * 3 * hidden),
            "epsilon": float(rows),
            "output_scale": float(rows * hidden),
            "output_finalize": float(5 * rows * hidden),
        }
        assert exact_requests == exact.operations == float(rows)
        assert scalar_demand.exact_request_demands == (
            ComputeExactRequestDemand(
                "aiv_four_queue_three_tbuf_lifecycle", ((1,),) * 43),
            ComputeExactRequestDemand(
                "aiv_queue_control_cycle",
                ((1,) * 20,) * 42 + ((1,) * 14,)),
            ComputeExactRequestDemand(
                "add_rmsnorm_local_scalar_handoff",
                ((1,) * 6,) * 42 + ((1,) * 4,)),
            ComputeExactRequestDemand(
                "vector_to_mte2_fence",
                ((1,) * 6,) * 42 + ((1,) * 4,)),
        )
        assert services["generic"].operations_by_worker == (
            (float(6 * (hidden + 1)),) * 42
            + (float(4 * (hidden + 1)),))
        assert all(
            demand.resource_role != "compute_reduction"
            for demand in resource_input.compute_demands)
        first_group = next(
            task for task in plan.tasks
            if task.name == "worker0_first_group")
        stages = {stage.name: stage for stage in first_group.stages}
        gamma_exact, = stages["gamma_load"].memory_exact_request_demands
        assert gamma_exact.resource_role == "mte2"
        assert gamma_exact.service == "aiv_datacopypad_mte2_to_vector_completion"
        assert gamma_exact.request_sizes_by_worker == ((16384,),)
        assert not stages["input_load"].memory_exact_request_demands
        assert (
            "cann_add_rmsnorm_first_mte2_completion_evidence_pending"
            not in resource_input.limitations)

