    def test_ascend_add_rms_key30_forward_envelope_matches_source_dag(self):
        kernel, source_input = self._ascend_add_rms_key30_input(
            rows=256, hidden=8192)
        compact_input, _ = forward_analytical_resource_input(
            kernel, ASCEND_HARDWARE)
        compact_plan = compact_input.pipeline_plan

        assert compact_plan is not None
        assert len(compact_plan.tasks) < len(source_input.pipeline_plan.tasks)
        assert all(
            isinstance(entry, PipelineTaskProgramDemand)
            for entry in compact_plan.tasks)
        assert tuple(
            worker
            for entry in compact_plan.tasks
            for worker in entry.physical_workers
        ) == tuple(range(kernel.launch.grid_size))
        source = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            source_input)
        compact = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            compact_input)
        assert compact.t_total_s == pytest.approx(source.t_total_s, rel=1e-12)

    def test_ascend_add_rms_key30_launch_shared_gamma_requires_symmetry(self):
        _, resource_input = self._ascend_add_rms_key30_input(
            rows=49, hidden=2048)
        plan = resource_input.pipeline_plan
        tasks = list(plan.tasks)
        task = tasks[-1]
        stages = list(task.stages)
        gamma_index = next(
            index for index, stage in enumerate(stages)
            if stage.name == "gamma_load")
        gamma = stages[gamma_index]
        shared = list(gamma.launch_shared_memory_node_demands)
        shared[0] = dataclasses.replace(
            shared[0], bytes=shared[0].bytes + 1)
        stages[gamma_index] = dataclasses.replace(
            gamma, launch_shared_memory_node_demands=tuple(shared))
        tasks[-1] = dataclasses.replace(task, stages=tuple(stages))
        malformed = dataclasses.replace(
            resource_input,
            pipeline_plan=dataclasses.replace(plan, tasks=tuple(tasks)),
        )

        with pytest.raises(ValueError, match="must be symmetric"):
            PerformanceFormula(ASCEND_HARDWARE).predict_kernel(malformed)

    def test_ascend_add_rms_key30_requires_exact_source_identity(self):
        kernel, _ = self._ascend_add_rms_key30_input()
        parameters = dict(kernel.launch.parameters)
        del parameters["source_bound_add_rmsnorm_row_group_dag"]
        missing = dataclasses.replace(
            kernel,
            launch=dataclasses.replace(kernel.launch, parameters=parameters))
        with pytest.raises(ValueError, match="source-bound row-group DAG"):
            create_predictor(missing.kind).resource_input(
                missing, ASCEND_HARDWARE)

        parameters = dict(kernel.launch.parameters)
        parameters["lowered_vector_reduce_operations"] += 1.0
        changed = dataclasses.replace(
            kernel,
            launch=dataclasses.replace(kernel.launch, parameters=parameters))
        with pytest.raises(ValueError, match="lowered work disagrees"):
            create_predictor(changed.kind).resource_input(
                changed, ASCEND_HARDWARE)

        parameters = dict(kernel.launch.parameters)
        parameters["norm_epsilon_add_flops"] += 1.0
        with pytest.raises(ValueError, match="one scalar add per"):
            dataclasses.replace(
                kernel,
                launch=dataclasses.replace(
                    kernel.launch, parameters=parameters))

