    def test_c500_rope_prices_source_qk_integer_dependencies(self):
        hardware = HWSpec("configs/hardware/metax_c500.yaml")
        shape = {
            "seq_len": 2,
            "num_query_heads": 64,
            "num_kv_heads": 8,
            "head_dim": 128,
            "rotary_dim": 128,
            "element_count": 2 * (64 + 8) * 128,
        }
        attributes = {"is_neox": True, "key_present": True}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rope", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert launch.parameters["source_qk_rope_loop"] == 1.0
        assert launch.parameters[
            SOURCE_BF16_CONVERSION_OPERATIONS_PARAMETER] == 55296.0
        assert resource_input.demand_per_resource["compute_vector"] == 504.0
        assert resource_input.demand_per_resource["compute_alu"] == 71680.0
        vector_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        assert vector_demand.service_demands == (
            ComputeServiceDemand("integer_rem_u32_dependency", 144.0),
            ComputeServiceDemand(
                "address_multiply_add_u64_dependency", 144.0),
            ComputeServiceDemand("bf16_roundtrip_pair_dependency", 216.0),
        )
        assert resource_input.pipeline_plan is not None
        program, = resource_input.pipeline_plan.tasks
        assert isinstance(program, PipelineTaskProgramDemand)
        assert program.worker_multiplicity == 2
        assert program.physical_workers == (0, 1)
        assert program.order == (0,)
        first_cta, = program.patterns
        first_task, = first_cta.tasks
        assert len(first_task.stages) == 9 * 5
        assert first_task.stages[0].name == "load"
        assert first_task.stages[-1].name == "store"
        assert sum(
            stage.include_first_request_latency
            for stage in first_task.stages
        ) == 9
        resident_slots, = resource_input.pipeline_plan.buffers
        assert resident_slots.producer_stage == "load"
        assert resident_slots.consumer_stage == "store"
        assert resident_slots.slots == 4

        large_shape = dict(shape)
        large_shape["seq_len"] = 256
        large_shape["element_count"] = 256 * (64 + 8) * 128
        large_launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, large_shape, "bf16",
            "rope", attributes, hardware=hardware)
        large_kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, large_shape,
            dtype="bf16", variant=large_launch.execution_variant,
            launch=large_launch, attributes=attributes)
        large_input, _ = create_predictor(
            large_kernel.kind).resource_input(large_kernel, hardware)
        assert tuple(
            program.order for program in large_input.pipeline_plan.tasks
        ) == ((0, 1, 1), (0, 1))
        assert all(len(program.patterns) == 2
                   for program in large_input.pipeline_plan.tasks)
        assert all(sum(
            stage.include_first_request_latency
            for stage in program.patterns[0].tasks[0].stages
        ) == 1 for program in large_input.pipeline_plan.tasks)
        assert all(sum(
            stage.include_first_request_latency
            for stage in program.patterns[1].tasks[0].stages
        ) == 1 for program in large_input.pipeline_plan.tasks)

