    def test_c500_tail_free_vec4_elementwise_uses_typed_2r1w_dram_service(
            self):
        hardware = HWSpec("configs/hardware/metax_c500.yaml")
        elements = 2048 * 1024
        shape = {"element_count": elements}
        attributes = {"reads": 2, "writes": 1, "operation": "add"}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)
        paths = {path.access_kind: path for path in resource_input.memory_paths}
        read_service, = paths["read"].access_class_demands
        write_service, = paths["write"].access_class_demands

        assert launch.grid == (2048, 1, 1)
        assert launch.block == (256, 1, 1)
        assert read_service.logical_bytes == 2 * elements * 2
        assert write_service.logical_bytes == elements * 2
        assert read_service.signature.tile_k == 4
        assert write_service.signature.tile_k == 4
        assert read_service.service == (
            "bf16_vec4_elementwise_2r1w_dram_read")
        assert write_service.service == (
            "bf16_vec4_elementwise_2r1w_dram_write")
        dependency_path, = resource_input.dependency_paths
        assert dependency_path.name == "elementwise_add"
        assert dependency_path.services == (
            "launch:submit",
            "memory:global_read",
            "compute:compute_fma",
            "memory:global_write",
        )
        assert dependency_path.concurrent_service_groups == ((
            "memory:global_read",
            "compute:compute_fma",
            "memory:global_write",
        ),)
        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)
        typed_stream_time = prediction.t_per_group[
            "memory_access:bf16_vec4_elementwise_2r1w_dram_read"]
        assert prediction.t_per_group[
            "memory_access:bf16_vec4_elementwise_2r1w_dram_write"] == (
                pytest.approx(typed_stream_time))
        assert prediction.t_per_group["dependency:elementwise_add"] == (
            pytest.approx(
                hardware.launch_latency_model["submit_ns"] * 1e-9
                + typed_stream_time))

