        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rope", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert kernel.shape["element_count"] == 80
        assert compulsory == 368.0
        # RoPE rewrites the lines it just read, so its store completes in L2
        # and only the 208-byte read extent reaches DRAM; ``compulsory``
        # remains the full cold envelope the roofline baseline consumes.
        assert resource_input.demand_per_resource["dram"] == 208.0
        assert resource_input.demand_per_resource["l2_cache"] == 368.0
        assert resource_input.demand_per_resource["l1_cache"] == 544.0
