    def test_c500_abi10_and_abi11_rope_share_physical_qk_loop_model(self):
        """The dataset ABI10 program and the captured ABI11 one lower alike.

        The retained C500 capture's launch signature has eleven runtime
        arguments and no `rope_dim_offset` or `inverse`, so it is ABI11, not
        vLLM 0.24.0's ABI13.
        """
        hardware = HWSpec("configs/hardware/metax_c500.yaml")
        common_shape = {
            "seq_len": 12,
            "num_query_heads": 32,
            "num_kv_heads": 8,
            "head_dim": 128,
        }
        abi11_launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, common_shape, "bf16",
            "rotary", {}, hardware=hardware)
        abi10_shape = {**common_shape, "rotary_dim": 128}
        abi10_attributes = {"is_neox": True, "key_present": True}
        abi10_launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, abi10_shape, "bf16",
            "rope", abi10_attributes, hardware=hardware)

        assert abi10_launch.parameters[
            SOURCE_METAX_ROPE_VLLM_0_8_5_ABI10_PROGRAM_PARAMETER] == 1.0
        assert abi11_launch.parameters[
            SOURCE_METAX_ROPE_VLLM_0_9_1_ABI11_PROGRAM_PARAMETER] == 1.0
        assert abi10_launch.parameters[SOURCE_QK_ROPE_LOOP_PARAMETER] == 1.0
        assert abi11_launch.parameters[SOURCE_QK_ROPE_LOOP_PARAMETER] == 1.0
        assert abi10_launch.grid == abi11_launch.grid == (12, 1, 1)
        assert abi10_launch.block == abi11_launch.block == (512, 1, 1)

        abi10_kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, abi10_shape,
            dtype="bf16", variant="rope", launch=abi10_launch,
            attributes=abi10_attributes)
        abi11_kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, common_shape,
            dtype="bf16", variant="rotary", launch=abi11_launch,
            attributes={})
        predictor = create_predictor(KernelKind.VECTOR)
        abi10_input, abi10_bytes = predictor.resource_input(
            abi10_kernel, hardware)
        abi11_input, abi11_bytes = predictor.resource_input(
            abi11_kernel, hardware)

        assert abi10_bytes == abi11_bytes
        assert abi10_input.demand_per_resource == (
            abi11_input.demand_per_resource)
        assert abi10_input.compute_demands == abi11_input.compute_demands
        assert abi10_input.memory_paths == abi11_input.memory_paths
        assert abi10_input.pipeline_plan == abi11_input.pipeline_plan

    def test_c500_graph_padded_rope_uses_logical_aggregate_work(self):
        # Isolation guard: without a physical-extent binding a padded spec
        # must not price its physical-launch source program on logical rows.
        hardware = HWSpec("configs/hardware/metax_c500.yaml")
        hardware.full_graph_physical_extent_dispatch = False
        hardware.piecewise_graph_physical_extent_dispatch = False
        logical_shape = {
            "seq_len": 7,
            "num_query_heads": 64,
            "num_kv_heads": 8,
            "head_dim": 128,
        }
        model_input_shape = {**logical_shape, "seq_len": 8}
        model_input_shape["element_count"] = 8 * (64 + 8) * 128
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, model_input_shape,
            "bf16", "rotary", {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, logical_shape,
            dtype="bf16", variant="rotary", launch=launch,
            attributes={
                "graph_logical_tokens": 7,
                "graph_model_input_tokens": 8,
                "graph_runtime_mode": "FULL",
                "model_input_shape": model_input_shape,
            })

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        elements = 7 * (64 + 8) * 128
        tensor_bytes = elements * 2
        expected_read = tensor_bytes + 7 * 8 + 7 * 128 * 2
        assert SOURCE_QK_ROPE_LOOP_PARAMETER in launch.parameters
        assert compulsory == expected_read + tensor_bytes
        assert resource_input.demand_per_resource["l2_cache"] == compulsory
        assert vector_predictor._source_bf16_conversion_operations(kernel) == 0
        assert resource_input.pipeline_plan is None
        assert resource_input.task_prologue_contract is None

