    @pytest.mark.parametrize(
        ("hardware_path", "index_bytes"),
        (
            ("configs/hardware/nvidia_a800.yaml", 8),
            ("configs/hardware/metax_c500.yaml", 8),
            ("configs/hardware/ascend_910b.yaml", 4),
        ),
    )
    def test_rope_static_inputs_conserve_exact_traffic(
            self, hardware_path, index_bytes):
        hardware = HWSpec(hardware_path)
        tokens = 4
        head_dim = 8
        shape = {
            "seq_len": tokens,
            "num_query_heads": 2,
            "num_kv_heads": 1,
            "head_dim": head_dim,
        }
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rotary", {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch)

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        tensor_bytes = tokens * (2 + 1) * head_dim * 2
        position_bytes = tokens * index_bytes
        cos_sin_bytes = tokens * head_dim * 2
        expected_read = tensor_bytes + position_bytes + cos_sin_bytes
        expected_write = tensor_bytes
        expected_total = expected_read + expected_write
        assert compulsory == expected_total
        # The in-place store lands on lines this kernel loaded, so where the
        # target declares an L2 store-completion scope it completes there and
        # only the read extent reaches DRAM.  npu_tile has no such scope
        # field, but the same in-place-alias mechanism applies: its L2 is a
        # coherent, capacity-bounded write-back cache, so the store only has
        # to be accepted into L2 (not drained to DRAM) provided the resident
        # tensor footprint fits under the measured replacement capacity --
        # which this fixture's tiny shape (tensor_bytes far below
        # l2_replacement_capacity_bytes) always does.
        if hardware.kernel_memory_model == "npu_tile":
            if tensor_bytes <= hardware.l2_replacement_capacity_bytes:
                assert (resource_input.demand_per_resource["dram"]
                        == expected_read)
            else:
                assert (resource_input.demand_per_resource["dram"]
                        == expected_total)
        elif hardware.gpu_store_completion_scope == "l2":
            assert resource_input.demand_per_resource["dram"] == expected_read
        else:
            assert (resource_input.demand_per_resource["dram"]
                    == expected_total)
        if hardware.kernel_memory_model == "gpu_mshr":
            if hardware.hardware_id == "nvidia_a800":
                cache_path_bytes = (
                    tokens * (shape["num_query_heads"]
                              + shape["num_kv_heads"]) * head_dim * 2)
                position_cache_path_bytes = (
                    tokens
                    * math.ceil(
                        launch.block_size / hardware.parallel_width)
                    * hardware.l2_transaction_bytes)
            elif hardware.hardware_id == "metax_c500":
                cache_path_bytes = (
                    tokens * (shape["num_query_heads"]
                              + shape["num_kv_heads"]) * head_dim * 2)
                position_cache_path_bytes = position_bytes
            else:
                raise AssertionError(hardware.hardware_id)
            expected_local_read = (
                tensor_bytes + position_cache_path_bytes + cache_path_bytes
            )
            expected_local_total = expected_local_read + expected_write
            expected_l2 = (
                expected_total
                if hardware.l1_cache_enabled
                else expected_local_total)
            assert resource_input.demand_per_resource["l2_cache"] == expected_l2
            assert resource_input.demand_per_resource["l1_cache"] == (
                expected_local_total if hardware.l1_cache_enabled else 0.0)
            assert resource_input.demand_per_resource["mte3"] == 0.0
        elif hardware.kernel_memory_model == "npu_tile":
            assert resource_input.demand_per_resource["l2_cache"] == (
                expected_total)
            assert resource_input.demand_per_resource["mte3"] == (
                expected_write)
            assert resource_input.support_level == "aggregate_only"
            assert resource_input.pipeline_plan is None
            assert resource_input.include_dispatch_overhead
        else:
            raise AssertionError(hardware.kernel_memory_model)

    @pytest.mark.parametrize(
        ("tokens", "query_heads", "kv_heads", "head_dim", "expected_key",
         "expected_slots", "expected_rotation_service"),
        (
            (16, 64, 8, 128, 22, 1, "local_ub_copy_stride_128b"),
            (64, 64, 8, 128, 24, 2, "local_ub_copy_stride_128b"),
            (16, 64, 1, 64, 22, 1, "local_ub_copy_stride_64b"),
        ),
    )
    def test_ascend_atb_bf16_rope_pipeline_conserves_source_program(
            self, tokens, query_heads, kv_heads, head_dim, expected_key,
            expected_slots, expected_rotation_service):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {
            "seq_len": tokens,
            "num_query_heads": query_heads,
            "num_kv_heads": kv_heads,
            "head_dim": head_dim,
        }
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rotary", {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant="rotary", launch=launch, attributes={})

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert launch.parameters["cann_tiling_key"] == float(expected_key)
        assert resource_input.support_level == "partial"
        assert resource_input.task_prologue_contract == (
            "cann_aiv_tiling_materialization_48b_v1")
        assert resource_input.task_prologue_repetitions == 1
        assert resource_input.aiv_descriptor_prologue_pipeline is False
        assert resource_input.task_duration_floor_contract == (
            AIV_EMPTY_TASK_SHELL_PLUS_SOURCE_PROGRAM)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert resource_input.pipeline_plan is not None
        token_buffer, = resource_input.pipeline_plan.buffers
        assert token_buffer.slots == expected_slots
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        services = {
            demand.service: demand
            for demand in vector_demand.service_demands
        }
        assert set(services) == {
            "cast_bf16_to_fp32_serialized",
            "cast_fp32_to_bf16_serialized",
            "mul_serialized",
            "generic",
        }
        assert sum(
            demand.operations for demand in services.values()
        ) + sum(
            demand.operations
            for demand in vector_demand.exact_request_demands
        ) == vector_demand.operations
        exact_requests = {
            demand.service: demand
            for demand in vector_demand.exact_request_demands
        }
        assert set(exact_requests) == {
            "local_scalar_fill_s_v",
            "local_ub_copy_contiguous",
            expected_rotation_service,
        }
        scalar_fill = exact_requests["local_scalar_fill_s_v"]
        assert scalar_fill.service == "local_scalar_fill_s_v"
        assert set(
            request_size
            for worker_requests in scalar_fill.request_sizes_by_worker
            for request_size in worker_requests
        ) == {head_dim}
        assert tuple(
            len(worker_requests)
            for worker_requests in scalar_fill.request_sizes_by_worker
        ) == tuple(
            2 if expected_key == 24
            and tokens // resource_input.pipeline_plan.worker_count
            + (1 if worker < tokens % resource_input.pipeline_plan.worker_count
               else 0) > 1
            else 1
            for worker in range(resource_input.pipeline_plan.worker_count)
        )
        slice_elements = 2048 if expected_key == 24 else 4096
        query_elements = query_heads * head_dim
        key_elements = kv_heads * head_dim
        query_slices = tuple(
            min(slice_elements, query_elements - offset)
            for offset in range(0, query_elements, slice_elements))
        key_slices = tuple(
            min(slice_elements, key_elements - offset)
            for offset in range(0, key_elements, slice_elements))
        rounded_elements = sum(
            math.ceil(current_slice / 64) * 64
            for current_slice in query_slices + key_slices)
        expected_arithmetic_operations = float(
            tokens * (2 * min(query_elements, slice_elements)
                      + 8 * rounded_elements))
        assert vector_demand.operations == pytest.approx(
            expected_arithmetic_operations
            + sum(
                demand.operations
                for demand in vector_demand.exact_request_demands))
        query_heads_per_slice = min(
            query_elements, slice_elements) // head_dim
        base_tokens, remainder = divmod(
            tokens, resource_input.pipeline_plan.worker_count)
        for worker in range(resource_input.pipeline_plan.worker_count):
            worker_tokens = base_tokens + (1 if worker < remainder else 0)
            mask_buffers = (
                2 if expected_key == 24 and worker_tokens > 1 else 1)
            assert exact_requests[
                "local_ub_copy_contiguous"
            ].request_sizes_by_worker[worker] == (
                (head_dim * 4,) * (
                    mask_buffers * (query_heads_per_slice - 1))
                + (head_dim * 2,) * (
                    worker_tokens * 2 * (query_heads_per_slice - 1)))
            assert exact_requests[
                expected_rotation_service
            ].request_sizes_by_worker[worker] == (
                tuple(
                    payload_bytes
                    for current_slice in query_slices + key_slices
                    for payload_bytes in (current_slice,) * 2)
                + tuple(
                    payload_bytes
                    for current_slice in query_slices + key_slices
                    for payload_bytes in (
                        (current_slice,) * (2 * (worker_tokens - 1))))
            )
        stage_names = {
            stage.name
            for task in resource_input.pipeline_plan.tasks
            for local_task in task.tasks
            for stage in local_task.stages
        }
        assert "cos_sin_broadcast" in stage_names
        assert "query_half_rotation_copy_0" in stage_names
        assert "key_half_rotation_copy_0" in stage_names
        assert all(
            services[name].serial_invocations > 0
            for name in (
                "cast_bf16_to_fp32_serialized",
                "cast_fp32_to_bf16_serialized",
                "mul_serialized",
            )
        )
        assert "atb_rope_hard_event_latency_evidence_partial" in (
            resource_input.limitations)
        assert "atb_rope_scalar_mask_setup_evidence_pending" not in (
            resource_input.limitations)
        assert "atb_rope_local_ub_copy_service_evidence_pending" not in (
            resource_input.limitations)

    @pytest.mark.parametrize(
        ("tokens", "worker_count", "remaining_repeats"),
        (
            (64, 32, 1),
            (256, 43, 5),
            (1024, 47, 21),
        ),
    )
    def test_ascend_atb_key24_rope_binds_local_q_edges(
            self, tokens, worker_count, remaining_repeats):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {
            "seq_len": tokens,
            "num_query_heads": 64,
            "num_kv_heads": 8,
            "head_dim": 128,
        }
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rotary", {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant="rotary", launch=launch, attributes={})

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert launch.parameters["cann_tiling_key"] == 24.0
        assert launch.grid_size == worker_count
        for worker in (0, 1):
            worker_tasks = resource_input.pipeline_plan.tasks[worker].tasks
            assert tuple(task.repeat_count for task in worker_tasks) == (
                1, remaining_repeats)
            for task_index, task in enumerate(worker_tasks):
                stages = {stage.name: stage for stage in task.stages}
                if task_index == 0:
                    mte2_service = (
                        "aiv_rope_mte2_to_vector_completion"
                        if worker == 0 else
                        f"aiv_rope_mte2_to_vector_completion_{worker_count}_"
                        "workers")
                    expected_mte2 = (MemoryExactRequestDemand(
                        "mte2", mte2_service, ((4096,),)),)
                else:
                    if tokens == 1024:
                        mte2_service = (
                            "aiv_rope_key24_mte2_steady_completion_"
                            "47_workers_4096b")
                        mte2_size = 21
                    else:
                        mte2_service = (
                            f"aiv_rope_mte2_to_vector_completion_"
                            f"{worker_count}_workers")
                        mte2_size = 4096
                    expected_mte2 = (MemoryExactRequestDemand(
                        "mte2", mte2_service, ((mte2_size,),)),)
                assert stages[
                    "query_load_0"].memory_exact_request_demands == (
                        expected_mte2)
                if worker == 0 and task_index == 0:
                    mte3_service = "aiv_rope_vector_to_mte3_completion"
                elif worker_count in (43, 47):
                    mte3_service = (
                        f"aiv_rope_vector_to_mte3_completion_{worker_count}_"
                        "workers")
                else:
                    mte3_service = None
                expected_mte3 = (
                    (MemoryExactRequestDemand(
                        "mte3", mte3_service, ((4096,),)),)
                    if mte3_service is not None else ())
                assert stages[
                    "query_store_0"].memory_exact_request_demands == (
                        expected_mte3)
                for index in range(1, 4):
                    assert not stages[
                        f"query_load_{index}"].memory_exact_request_demands
                    assert not stages[
                        f"query_store_{index}"].memory_exact_request_demands
                assert stages["key_load_0"].memory_exact_request_demands == ()
                assert stages[
                    "key_store_0"].memory_exact_request_demands == ()
                assert stages["query_load_1"].predecessors == (
                    "query_compute_0",)
                assert stages["query_load_1"].start_predecessors == (
                    "query_store_0",)
                assert stages["query_compute_1"].predecessors == (
                    "query_half_rotation_copy_1", "query_store_0")
                assert stages["cos_sin_cast"].prior_resources == (
                    "memory:mte3_write",)
        assert "atb_rope_hard_event_latency_evidence_partial" in (
            resource_input.limitations)
        assert (
            "atb_rope_steady_mte2_completion_evidence_partial"
            in resource_input.limitations) is (tokens != 1024)

