    def test_ascend_kv_cache_key_202_uses_independent_two_slot_queues(self):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {"seq_len": 1000, "num_kv_heads": 4, "head_dim": 128}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.KV_CACHE, shape, "bf16",
            "paged_kv_cache", PAGED_KV_CACHE_ATTRIBUTES, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.KV_CACHE, hardware.hardware_id, shape,
            dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=PAGED_KV_CACHE_ATTRIBUTES)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert launch.parameters == {"cann_tiling_key": 202_000_000.0}
        assert resource_input.task_prologue_contract == (
            "cann_aiv_tiling_materialization_v1")
        assert resource_input.task_prologue_repetitions == 1
        assert resource_input.support_level == "partial"
        tensor_bytes = 1000 * 4 * 128 * 2
        read_bytes = 2 * tensor_bytes + 2 * 1000 * 4
        write_bytes = 2 * tensor_bytes
        assert resource_input.demand_per_resource["l2_cache"] == (
            read_bytes + write_bytes)
        assert resource_input.demand_per_resource["dram"] == (
            read_bytes + write_bytes)
        assert resource_input.demand_per_resource["mte3"] == write_bytes
        plan = resource_input.pipeline_plan
        assert plan is not None
        assert plan.worker_count == 48
        assert tuple(task.repeat_count for task in plan.tasks) == (
            (21,) * 40 + (20,) * 8)
        stages = plan.tasks[0].stages
        assert tuple(stage.name for stage in stages) == (
            "key_slot_get", "key_queue_control", "key_load", "key_store",
            "value_slot_get", "value_queue_control", "value_load",
            "value_store")
        assert tuple(stage.predecessors for stage in stages) == (
            None, ("key_slot_get",), ("key_queue_control",), ("key_load",),
            (), ("value_slot_get",), ("value_queue_control",),
            ("value_load",))
        key_stage_names = {
            "key_slot_get", "key_queue_control", "key_load", "key_store"}
        value_stage_names = {
            "value_slot_get", "value_queue_control", "value_load",
            "value_store"}
        assert all(
            not (set(stage.predecessors or ()) & value_stage_names)
            for stage in stages if stage.name in key_stage_names)
        assert all(
            not (set(stage.predecessors or ()) & key_stage_names)
            for stage in stages if stage.name in value_stage_names)
        for name in ("key_load", "value_load"):
            stage = next(stage for stage in stages if stage.name == name)
            exact, = stage.memory_exact_request_demands
            assert exact.resource_role == "mte2"
            assert exact.service == "aiv_mte2_request_completion"
            assert exact.pipelined_completion is True
        for name in ("key_store", "value_store"):
            stage = next(stage for stage in stages if stage.name == name)
            exact, = stage.memory_exact_request_demands
            assert exact.resource_role == "mte3"
            assert exact.service == "aiv_mte3_request_completion"
            assert exact.pipelined_completion is True
        demand_by_role = {
            demand.resource_role: demand
            for demand in resource_input.compute_demands}
        vector_demand = demand_by_role["compute_vector"]
        exact, = vector_demand.exact_request_demands
        assert exact.service == "scalar_global_get_value_serialized"
        assert exact.request_sizes_by_worker == (
            ((1,) * 42,) * 40 + ((1,) * 40,) * 8)
        scalar_demand = demand_by_role["scalar_aiv"]
        queue_exact, = scalar_demand.exact_request_demands
        assert queue_exact.service == "aiv_queue_control_cycle"
        assert queue_exact.request_sizes_by_worker == (
            ((1,) * (2 * 21),) * 40 + ((1,) * (2 * 20),) * 8)
        for name in ("key_queue_control", "value_queue_control"):
            stage = next(stage for stage in stages if stage.name == name)
            queue_stage_exact, = stage.compute_exact_request_demands
            assert queue_stage_exact.service == "aiv_queue_control_cycle"
            assert queue_stage_exact.request_sizes_by_worker == ((1,),)
        assert plan.buffers == (
            PipelineBuffer(
                name="key_queue",
                producer_stage="key_load",
                consumer_stage="key_store",
                slots=2,
                scope="worker",
            ),
            PipelineBuffer(
                name="value_queue",
                producer_stage="value_load",
                consumer_stage="value_store",
                slots=2,
                scope="worker",
            ),
        )

