    def test_a800_vector_semantic_dependency_paths(
            self, variant, shape, attributes, path_name, services,
            missing_reduction):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        if variant == "paged_kv_cache":
            kind = KernelKind.KV_CACHE
        else:
            kind = KernelKind.VECTOR
        launch = select_launch_config(
            hardware.hardware_id, kind, shape, "bf16", variant,
            attributes, hardware=hardware)
        kernel = KernelSpec(
            kind, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        if variant in ("rmsnorm", "add_rmsnorm"):
            assert resource_input.dependency_paths == ()
            assert resource_input.pipeline_plan is not None
            return
        path, = resource_input.dependency_paths
        assert resource_input.pipeline_plan is None
        assert path.name == path_name
        assert path.services == services
        if variant == "rotary":
            assert path.serial_service_counts == ((
                "memory_latency:global_read", 2),)
        elif variant == "rmsnorm":
            assert path.serial_service_counts == ((
                "task:memory_dependency_increment", 1),)
        elif variant == "add_rmsnorm":
            assert path.serial_service_counts == (
                ("memory_latency:global_read", 1),
                ("task:memory_dependency_increment", 2),
            )
        elif variant == "paged_kv_cache":
            assert path.serial_service_counts == ((
                "memory_latency:global_read", 2),)
        else:
            assert path.serial_service_counts == ()
        if variant == "elementwise":
            assert path.concurrent_service_groups == ((
                "memory:global_read",
                "local_memory:l1_cache",
                "compute:compute_fma",
                "memory:global_write",
            ),)
        assert (
            "norm_reduction_dependency_service_unavailable"
            in resource_input.limitations
        ) is missing_reduction

    def test_a800_rmsnorm_source_cta_pipeline_conserves_static_work(self):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        rows = 256
        hidden = 4096
        shape = {"rows": rows, "hidden": hidden}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rmsnorm", {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch, attributes={})

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        assert resource_input.pipeline_plan is not None
        assert resource_input.pipeline_plan.worker_count == 108
        resident_slots, = resource_input.pipeline_plan.buffers
        assert resident_slots == PipelineBuffer(
            "resident_cta_slots", "load_reduce_0", "final_store_3", 2,
            "worker")
        read_path = next(
            path for path in resource_input.memory_paths
            if path.name == "global_read")
        assert read_path.source.producers_per_unit == 32.0
        assert read_path.source.independent_requests_per_producer == 2.0

        reduction = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_reduction")
        assert {
            demand.service: demand.operations
            for demand in reduction.service_demands
        } == {
            "block_reduce_first_1024": 108.0,
            "block_reduce_resident_1024": 108.0,
            "block_reduce_queued_1024": 40.0,
        }
        assert sum(
            demand.operations for demand in reduction.service_demands
        ) == rows

        first_pattern = resource_input.pipeline_plan.tasks[0].patterns[0]
        first_cta, = first_pattern.tasks
        matching_first_cta, = (
            resource_input.pipeline_plan.tasks[1].patterns[0].tasks)
        assert first_cta.stages is matching_first_cta.stages
        stage_names = tuple(stage.name for stage in first_cta.stages)
        assert stage_names[:3] == (
            "load_reduce_0", "input_fma_0", "load_reduce_1")
        assert "block_reduction" in stage_names
        assert "residual_store_0" not in stage_names
        assert stage_names[-3:] == (
            "load_output_3", "output_fma_3", "final_store_3")

        latency_heads = {
            pattern.name: tuple(
                stage.name
                for stage in pattern.tasks[0].stages
                if stage.include_first_request_latency)
            for pattern in resource_input.pipeline_plan.tasks[0].patterns
        }
        assert latency_heads == {
            "first": ("load_reduce_0", "load_output_0"),
            "resident": (),
            "queued": (),
        }

    def test_a800_rmsnorm_resident_cta_reuses_sm_local_gamma(self):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        predictions = []
        for rows in (129, 191):
            shape = {"rows": rows, "hidden": 4096}
            launch = select_launch_config(
                hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
                "rmsnorm", {}, hardware=hardware)
            kernel = KernelSpec(
                KernelKind.VECTOR, hardware.hardware_id, shape,
                dtype="bf16", variant=launch.execution_variant,
                launch=launch, attributes={})
            assert launch.parameters["norm_weight_l2_copies"] == 108.0

            resource_input, _ = create_predictor(
                kernel.kind).resource_input(kernel, hardware)
            first, resident = resource_input.pipeline_plan.tasks[0].patterns
            first_stages = {stage.name: stage for stage in first.tasks[0].stages}
            assert tuple(
                stage.name for stage in resident.tasks[0].stages
                if stage.name.startswith("load_output_")) == ()
            for round_index in range(4):
                stage = first_stages[f"load_output_{round_index}"]
                assert stage.local_memory_source_completion == (
                    "sequence_start" if round_index == 0 else "steady")
                assert stage.memory_node_demands == (PhaseMemoryDemand(
                    "global_read", "l2_cache", 2048.0),)
                assert stage.launch_shared_memory_node_demands == (
                    PhaseMemoryDemand("global_read", "dram", 2048.0),)
            predictions.append(create_predictor(
                kernel.kind).midlayer(kernel, hardware).t_total_s)

        # Both launches have a two-CTA critical worker.  Appending resident
        # CTAs on other SMs cannot make that physical source program faster.
        assert predictions[1] >= predictions[0]

    def test_a800_low_grid_rmsnorm_uses_one_local_source_fill_per_phase(self):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        predictions = []
        for rows in (1, 2):
            hidden = 16384
            shape = {"rows": rows, "hidden": hidden}
            launch = select_launch_config(
                hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
                "rmsnorm", {}, hardware=hardware)
            kernel = KernelSpec(
                KernelKind.VECTOR, hardware.hardware_id, shape,
                dtype="bf16", variant=launch.execution_variant,
                launch=launch, attributes={})

            assert launch.parameters[
                "source_bound_gpu_norm_cta_pipeline"] == 1.0
            assert not _has_typed_rmsnorm_scalar_round_services(
                kernel, hardware)
            resource_input, _ = create_predictor(
                kernel.kind).resource_input(kernel, hardware)
            plan = resource_input.pipeline_plan
            first_task, = plan.tasks[0].patterns[0].tasks
            read_stages = tuple(
                stage for stage in first_task.stages
                if stage.service == "memory:global_read")
            input_stages = tuple(
                stage for stage in read_stages
                if stage.name.startswith("load_reduce_"))
            output_stages = tuple(
                stage for stage in read_stages
                if stage.name.startswith("load_output_"))

            assert tuple(
                stage.local_memory_source_completion
                for stage in input_stages) == (
                    "sequence_start",) + ("steady",) * 15
            assert tuple(
                stage.local_memory_source_completion
                for stage in output_stages) == (
                    "sequence_start",) + ("steady",) * 15
            assert all(stage.work_fraction is None for stage in read_stages)
            # The resident row operand stream reaches no DRAM node.
            assert all(
                tuple(demand.resource_role
                      for demand in stage.memory_node_demands)
                == ("l2_cache",)
                for stage in input_stages)
            assert all(
                tuple(demand.resource_role
                      for demand in stage.memory_node_demands)
                == ("l2_cache",)
                for stage in output_stages)
            assert all(
                tuple(demand.resource_role
                      for demand in stage.launch_shared_memory_node_demands)
                == ("dram",)
                for stage in output_stages)
            predictions.append(
                PerformanceFormula(hardware).predict_kernel(
                    resource_input).t_total_s)

        assert predictions[1] > predictions[0]

