    def test_cann_silu_uses_only_published_typed_opcode_services(self):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        elements = 2 * 12288
        shape = {
            "tok": 2,
            "intermediate": 12288,
            "element_count": elements,
        }
