    @pytest.mark.parametrize(
        ("operation", "expected_lowered_operations"),
        (("add", 3.0), ("mul", 3.0)),
    )
    def test_cann_elementwise_uses_operation_specific_cast_passes(
            self, operation, expected_lowered_operations):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        elements = 4096
        shape = {"element_count": elements}
        attributes = {"reads": 2, "writes": 1, "operation": operation}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input, _ = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        expected_parameters_by_operation = {
            "add": {
                "cann_tiling_key": 210_000_000.0,
                "elementwise_input_queue_depth": 1.0,
                "elementwise_input_ping_pong_slots": 2.0,
            },
            "mul": {
                "cann_tiling_key": 210_020_000.0,
                "elementwise_input_queue_depth": 4.0,
                "elementwise_input_ping_pong_slots": 2.0,
            },
        }
        expected_parameters = {
            **expected_parameters_by_operation[operation],
            "cann_tiling_payload_bytes": 56.0,
            "elementwise_block_factor": 1024.0,
            "elementwise_ub_factor": 1024.0,
            "elementwise_output_queue_depth": 1.0,
            "source_cann_bf16_elementwise_dag": 1.0,
        }
        expected_parameters["lowered_vector_operations"] = float(
            3 * elements)
        assert launch.grid == (4, 1, 1)
        assert launch.parameters == expected_parameters
        assert resource_input.demand_per_resource["compute_vector"] == (
            (1.0 + expected_lowered_operations) * elements)
        vector_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        assert vector_demand.operations == (
            (1.0 + expected_lowered_operations) * elements)
        assert resource_input.phase_ledger is not None
        expected_unassigned_by_operation = {
            operation: (
                PhaseComputeDemand(
                    resource_role="compute_vector",
                    operation="backend_lowered_vector",
                    operations=3.0 * elements,
                ),
                PhaseComputeDemand(
                    resource_role="scalar_aiv",
                    operation="source_queue_buffer_control",
                    operations=36.0,
                ),
            ) for operation in ("add", "mul")
        }
        assert resource_input.phase_ledger.unassigned_compute_demands == (
            expected_unassigned_by_operation[operation])
        assert resource_input.support_level == "partial"
        assert resource_input.pipeline_plan is not None
        assert resource_input.task_duration_floor_contract == (
            AIV_SOURCE_PIPELINE_LAUNCH_ONLY)
        assert resource_input.aiv_worker_start_contract == (
            AIV_WORKER_START_FILL)
        assert resource_input.dependency_paths == ()
        buffers = {
            buffer.name: buffer
            for buffer in resource_input.pipeline_plan.buffers
        }
        assert buffers["input_a_buffer"].slots == 2
        assert buffers["input_b_buffer"].slots == 2
        assert buffers["output_buffer"].slots == 1
        scalar_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "scalar_aiv")
        queue_control, = scalar_demand.exact_request_demands
        assert queue_control.service == "aiv_queue_control_cycle"
        assert queue_control.request_size_runs_by_worker == tuple(
            ((1, 9),) for _ in range(4))
        for program in resource_input.pipeline_plan.tasks:
            task, = program.patterns[0].tasks
            stages = {stage.name: stage for stage in task.stages}
            exact, = stages["queue_control"].compute_exact_request_demands
            assert exact.service == "aiv_queue_control_cycle"
            assert exact.request_sizes_by_worker == ((1,) * 9,)
            for stage_name in ("load_a", "load_b"):
                exact, = stages[
                    stage_name].memory_exact_request_demands
                assert exact.resource_role == "mte2"
                assert exact.service == "aiv_mte2_request_completion"
                assert exact.request_sizes_by_worker == ((2048,),)
            exact, = stages["store"].memory_exact_request_demands
            assert exact.resource_role == "mte3"
            assert exact.service == "aiv_mte3_request_completion"
            assert exact.request_sizes_by_worker == ((2048,),)

    @pytest.mark.parametrize("operation", ("add", "mul"))
    def test_cann_elementwise_input_ping_pong_slots_preserve_compact_program(
            self, operation):
        """A BF16 input stream has two source-selected slots, not q4 slots."""

        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {"element_count": 1_000_000}
        attributes = {"reads": 2, "writes": 1, "operation": operation}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise", attributes, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        source_input = _resource_input_for(kernel, hardware)
        source_buffers = {
            buffer.name: buffer for buffer in source_input.pipeline_plan.buffers
        }
        assert tuple(source_buffers[name].slots for name in (
            "input_a_buffer", "input_b_buffer")) == (2, 2)
        assert launch.parameters["elementwise_input_queue_depth"] == {
            "add": 2.0,
            "mul": 4.0,
        }[operation]

        compact_input, _ = forward_analytical_resource_input(kernel, hardware)
        assert all(
            isinstance(program, PipelineTaskProgramDemand)
            for program in compact_input.pipeline_plan.tasks)
        for resource_input in (source_input, compact_input):
            prediction = PerformanceFormula(hardware).predict_kernel(
                resource_input)
            assert prediction.t_total_s > 0.0
            assert prediction.t_launch_s * 1e9 >= 1809.5782470703125

