    def test_cann_elementwise_exact_gm_service_is_source_tiled_and_max_bound(
            self):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        elements = 256 * 2560
        shape = {"element_count": elements}
        attributes = {"reads": 2, "writes": 1, "operation": "add"}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise", attributes, hardware=hardware)
        assert launch.parameters["elementwise_ub_factor"] == 4608.0
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        typed_input = _resource_input_for(kernel, hardware)
        paths = {path.name: path for path in typed_input.memory_paths}
        read_demand, = paths["mte2_read"].access_class_demands
        write_demand, = paths["mte3_write"].access_class_demands
        assert read_demand.logical_bytes == 2 * elements * 2
        assert write_demand.logical_bytes == elements * 2
        assert read_demand.signature.tile_k == 4608
        assert write_demand.signature.tile_k == 4608

        for program in typed_input.pipeline_plan.tasks:
            for pattern in program.patterns:
                task, = pattern.tasks
                stages = {stage.name: stage for stage in task.stages}
                for stage_name in ("load_a", "load_b", "store"):
                    stage = stages[stage_name]
                    assert stage.work_fraction is None
                    demand, = stage.memory_access_class_demands
                    assert demand.signature.tile_k == 4608

        generic_hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        generic_hardware.memory_access_class_services = tuple(
            service for service
            in generic_hardware.memory_access_class_services
            if not service.service.startswith(
                "cann_bf16_binary_two_read_one_write_gm_"))
        generic_input = _resource_input_for(kernel, generic_hardware)
        for current_hardware, resource_input in (
                (hardware, typed_input),
                (generic_hardware, generic_input)):
            prediction = PerformanceFormula(current_hardware).predict_kernel(
                resource_input)
            assert prediction.t_total_s > 0.0
            assert prediction.t_launch_s * 1e9 >= 1809.5782470703125

        steady_mul_elements = 1024 * 8192
        steady_mul_shape = {"element_count": steady_mul_elements}
        steady_mul_attributes = {
            "reads": 2, "writes": 1, "operation": "mul",
        }
        steady_mul_launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, steady_mul_shape,
            "bf16", "elementwise", steady_mul_attributes,
            hardware=hardware)
        assert steady_mul_launch.parameters["elementwise_ub_factor"] == 9728.0
        steady_mul_kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, steady_mul_shape,
            dtype="bf16", variant=steady_mul_launch.execution_variant,
            launch=steady_mul_launch, attributes=steady_mul_attributes)
        steady_mul_input = _resource_input_for(
            steady_mul_kernel, hardware)
        steady_mul_paths = {
            path.name: path for path in steady_mul_input.memory_paths}
        steady_mul_read, = steady_mul_paths[
            "mte2_read"].access_class_demands
        steady_mul_write, = steady_mul_paths[
            "mte3_write"].access_class_demands
        assert steady_mul_read.signature.tile_k == 9728
        assert steady_mul_write.signature.tile_k == 9728
        assert steady_mul_read.service == (
            "cann_bf16_mul_q4q1_two_read_one_write_gm_read")
        assert steady_mul_write.service == (
            "cann_bf16_mul_q4q1_two_read_one_write_gm_write")
        steady_mul_scalar = next(
            demand for demand in steady_mul_input.compute_demands
            if demand.resource_role == "scalar_aiv")
        assert all(
            demand.service != "aiv_elementwise_tbuf_lifecycle_110080b"
            for demand in steady_mul_scalar.exact_request_demands)

    @pytest.mark.parametrize(
        ("tokens", "hidden", "expected_workers", "expected_prefix",
         "expected_suffix", "expected_widths"),
        (
            (16, 5120, 46,
             "aiv_elementwise_mul_prefix_46_workers",
             "aiv_elementwise_mul_suffix_46_workers", {1280, 1792}),
            (16, 8192, 47,
             "aiv_elementwise_mul_prefix_47_workers",
             "aiv_elementwise_mul_suffix_47_workers", {1536, 2816}),
        ),
    )
    def test_cann_elementwise_mul_compute_segments_preserve_b_input_boundary(
            self, tokens, hidden, expected_workers, expected_prefix,
            expected_suffix, expected_widths):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        elements = tokens * hidden
        shape = {"element_count": elements}
        attributes = {"reads": 2, "writes": 1, "operation": "mul"}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "elementwise", attributes, hardware=hardware)
        assert launch.grid == (expected_workers, 1, 1)
        kernel = KernelSpec(
            KernelKind.VECTOR, hardware.hardware_id, shape, dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=attributes)

        resource_input = _resource_input_for(kernel, hardware)
        vector_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        assert tuple(
            demand.service for demand in vector_demand.exact_request_demands
        ) == (expected_prefix, expected_suffix)
        assert vector_demand.service_demands == ()
        prefix, suffix = vector_demand.exact_request_demands
        assert {
            request
            for requests in prefix.request_sizes_by_worker
            for request in requests
        } == expected_widths
        assert {
            request // 3
            for requests in suffix.request_sizes_by_worker
            for request in requests
        } == expected_widths
        assert prefix.operations + suffix.operations == 4 * elements
        for program in resource_input.pipeline_plan.tasks:
            for pattern in program.patterns:
                for task in pattern.tasks:
                    stages = {stage.name: stage for stage in task.stages}
                    assert "cast_b" not in stages
                    assert "mul" not in stages
                    assert "cast_out" not in stages
                    assert stages["cast_a"].start_predecessors == ("load_b",)
                    assert stages["mul_suffix"].predecessors == (
                        "cast_a", "load_b")
        buffers = {
            buffer.name: buffer for buffer in resource_input.pipeline_plan.buffers}
        assert buffers["input_b_buffer"].consumer_stage == "mul_suffix"
        assert buffers["output_buffer"].producer_stage == "mul_suffix"

