    def test_cann_rmsnorm_consumes_source_half_interval_reduction(self):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {"rows": 4, "hidden": 4096, "dtype_bytes": 2}
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.VECTOR, shape, "bf16",
            "rmsnorm", {}, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.VECTOR,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="rmsnorm",
            launch=launch,
        )

        demand = _resource_input_for(kernel, hardware).demand_per_resource
        assert demand["compute_reduction"] == 0.0
        assert all(demand[role] == 0.0 for role in (
            "l1_cache", "smem", "xbar"))
        assert hardware.vector_reduce_sum_latency_lut is not None
        resource_input = _resource_input_for(kernel, hardware)
        assert resource_input.launch_task_kind == "aiv"
        assert resource_input.include_dispatch_overhead
        assert resource_input.pipeline_plan is not None
        for task in resource_input.pipeline_plan.tasks:
            assert all(
                stage.service != "compute:compute_reduction"
                for stage in task.stages)
            input_stage = next(
                stage for stage in task.stages
                if stage.name == "input_square_reduce")
            reduction_service, = tuple(
                service for service in input_stage.compute_service_demands
                if service.service == "rmsnorm_half_interval_reduce")
            assert reduction_service.operations == 4096.0
            assert reduction_service.serial_invocations == 1
            scalar_stage = next(
                stage for stage in task.stages
                if stage.name == "local_scalar_dependency")
            assert scalar_stage.predecessors == ("input_square_reduce",)
            exact, = scalar_stage.compute_exact_request_demands
            assert exact.service == "rmsnorm_local_scalar_dependency"
            assert exact.request_sizes_by_worker == ((2,),)
        assert hardware.aiv_empty_kernel_duration_lut is not None
        assert (
            "norm_reduction_dependency_service_unavailable"
            not in resource_input.limitations)
        assert (
            "launch_task_duration_evidence_unavailable"
            not in resource_input.limitations)

    def test_kv_cache_counts_k_and_v_reads_and_writes(self):
        demand, compulsory = self._demand(
            "paged_kv_cache", {
                "seq_len": 4,
                "num_kv_heads": 2,
                "head_dim": 8,
            }, hardware_path="configs/hardware/nvidia_a800.yaml")
        tensor_bytes = 4 * 4 * 2 * 8 * 2
        slot_bytes = 4 * 8
        expected_bytes = tensor_bytes + slot_bytes
        assert demand["l2_cache"] == expected_bytes
        # The source tensor and its cache copy are far inside the measured L2
        # residency curve, so only the slot-mapping indices and the graded
        # DRAM share of the copy reach DRAM.
        assert demand["dram"] < expected_bytes
        assert demand["dram"] >= slot_bytes
        assert compulsory == expected_bytes

