    def test_a800_kv_cache_limits_read_source_to_active_copy_warps(
            self, kv_heads, expected_read_producers):
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        shape = {
            "seq_len": 1024,
            "num_kv_heads": kv_heads,
            "head_dim": 128,
        }
