    @pytest.mark.parametrize(
        ("hardware_path", "index_bytes"),
        (
            ("configs/hardware/nvidia_a800.yaml", 8),
            ("configs/hardware/ascend_910b.yaml", 4),
        ),
    )
    def test_kv_cache_static_inputs_conserve_exact_traffic(
            self, hardware_path, index_bytes):
        hardware = HWSpec(hardware_path)
        tokens = 4
        kv_heads = 2
        head_dim = 8
        shape = {
            "seq_len": tokens,
            "num_kv_heads": kv_heads,
            "head_dim": head_dim,
        }
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.KV_CACHE, shape, "bf16",
            "paged_kv_cache", PAGED_KV_CACHE_ATTRIBUTES, hardware=hardware)
        kernel = KernelSpec(
            KernelKind.KV_CACHE, hardware.hardware_id, shape,
            dtype="bf16",
            variant=launch.execution_variant, launch=launch,
            attributes=PAGED_KV_CACHE_ATTRIBUTES)

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        one_kv_tensor = tokens * kv_heads * head_dim * 2
        expected_read = 2 * one_kv_tensor + tokens * index_bytes
        expected_write = 2 * one_kv_tensor
        expected_total = expected_read + expected_write
        assert compulsory == expected_total
        if hardware.l2_operand_residency_curve is None:
            assert resource_input.demand_per_resource["dram"] == expected_total
        else:
            # This footprint is far inside the measured residency curve, so
            # only the slot indices and the graded DRAM share reach DRAM while
            # the compulsory envelope stays the full traffic.
            assert (tokens * index_bytes
                    <= resource_input.demand_per_resource["dram"]
                    < expected_total)
        assert resource_input.demand_per_resource["compute_alu"] == 0.0
        if hardware.kernel_memory_model == "gpu_mshr":
            if hardware.hardware_id == "nvidia_a800":
                slot_l1_bytes = tokens * 32
            elif hardware.hardware_id == "metax_c500":
                slot_l1_bytes = tokens * index_bytes
            else:
                raise AssertionError(hardware.hardware_id)
            expected_local_total = (
                2 * one_kv_tensor + slot_l1_bytes + expected_write)
            expected_l2 = (
                expected_total
                if hardware.l1_cache_enabled
                else expected_local_total)
            assert resource_input.demand_per_resource["l2_cache"] == expected_l2
            assert resource_input.demand_per_resource["l1_cache"] == (
                expected_local_total if hardware.l1_cache_enabled else 0.0)
            assert resource_input.demand_per_resource["mte3"] == 0.0
        elif hardware.kernel_memory_model == "npu_tile":
            assert resource_input.demand_per_resource["l2_cache"] == (
                expected_total)
            assert resource_input.demand_per_resource["mte3"] == (
                expected_write)
            assert launch.parameters == {
                "cann_tiling_key": 200_000_000.0}
            assert resource_input.support_level == "partial"
            plan = resource_input.pipeline_plan
            assert plan is not None
            assert plan.worker_count == tokens
            assert tuple(task.repeat_count for task in plan.tasks) == (
                1,) * tokens
            assert tuple(
                stage.name for stage in plan.tasks[0].stages
            ) == (
                "slot_get", "key_load", "key_store", "value_load",
                "value_store")
            vector_demand, = tuple(
                demand for demand in resource_input.compute_demands
                if demand.resource_role == "compute_vector")
            exact, = vector_demand.exact_request_demands
            assert exact.service == "scalar_global_get_value_serialized"
            assert exact.request_sizes_by_worker == ((1,),) * tokens
            assert tuple(
                stage.service for stage in plan.tasks[0].stages
            ) == (
                "compute:compute_vector", "memory:mte2_read",
                "memory:mte3_write", "memory:mte2_read",
                "memory:mte3_write")
            assert plan.tasks[0].stages[0].work_fraction is None
            assert tuple(
                stage.work_fraction for stage in plan.tasks[0].stages[1:]
            ) == pytest.approx((
                (kv_heads * head_dim * 2 + index_bytes) / expected_read,
                (kv_heads * head_dim * 2) / expected_write,
                (kv_heads * head_dim * 2) / expected_read,
                (kv_heads * head_dim * 2) / expected_write,
            ))
            assert plan.buffers == (PipelineBuffer(
                name="token_buffer",
                producer_stage="key_load",
                consumer_stage="value_store",
                slots=1,
                scope="worker",
            ),)
            assert resource_input.include_dispatch_overhead
        else:
            raise AssertionError(hardware.kernel_memory_model)

    def test_pim_kv_cache_sends_k_and_v_once_through_row_protocol(self):
        hardware = HWSpec("configs/hardware/samsung_hbm_pim.yaml")
        shape = {
            "seq_len": 4,
            "num_kv_heads": 2,
            "head_dim": 8,
        }
        launch = LaunchConfig(
            algorithm="unindp_elewise",
            grid=(1, 1, 1),
            block=(1, 1, 1),
            execution_variant="paged_kv_cache",
        )
        kernel = KernelSpec(
            KernelKind.KV_CACHE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="paged_kv_cache",
            launch=launch,
            attributes=PAGED_KV_CACHE_ATTRIBUTES,
        )

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, hardware)

        base_elements = 4 * 2 * 8
        # The bank-attached unit runs this operator on the array itself: there
        # is no cache between the two, and the read-modify-write protocol that
        # carries it is priced as the serialized bank stream.  K and V are two
        # logical streams through that protocol, not four separate read/write
        # streams as in the generic GPU traffic envelope.
        assert resource_input.demand_per_resource["l2_cache"] == 0.0
        assert resource_input.demand_per_resource["dram"] == 0.0
        assert resource_input.execution_time_floor_ns == bank_stream_ns(
            (pointwise_stream(2 * base_elements),), hardware)
        assert compulsory == 4 * base_elements * 2

