    def test_a800_split3_varlen_admission_order_is_bijective(self):
        source = tuple((ordinal, 1) for ordinal in range(384))

        reordered = flash_attn_predictor._a800_split3_varlen_admission_order(
            source)
        flattened = tuple(
            item for item, count in reordered for _ in range(count))

        assert flattened[:166] == tuple(range(166))
        assert flattened[166:216] == tuple(
            ordinal
            for lower in range(166, 191)
            for ordinal in (lower, lower + 25)
        )
        assert flattened[216:] == tuple(range(216, 384))
        assert sorted(flattened) == list(range(384))

