    @pytest.mark.parametrize(
        ("period", "repetitions", "worker_count", "start_ordinal"),
        (
            ((0,), 1, 4, 0),
            ((0, 1, 2), 7, 5, 0),
            ((0, 1, 2, 3), 11, 6, 4),
            ((0, 1, 0, 2, 3), 19, 8, 7),
        ),
    )
    def test_periodic_round_robin_program_matches_explicit_cta_assignment(
            self, period, repetitions, worker_count, start_ordinal):
        programs = flash_attn_predictor._periodic_round_robin_worker_programs(
            period,
            repetitions,
            worker_count,
            start_ordinal=start_ordinal,
        )
        explicit_stream = period * repetitions
        for worker, program in enumerate(programs):
            expected = tuple(
                item for offset, item in enumerate(explicit_stream)
                if (start_ordinal + offset) % worker_count == worker)
            if program is None:
                assert expected == ()
                continue
            order, repeat_count, tail_order = program
            assert order * repeat_count + tail_order == expected

    def test_periodic_round_robin_program_size_is_grid_independent(self):
        period = tuple(range(64))
        small = flash_attn_predictor._periodic_round_robin_worker_programs(
            period, 108, 108, start_ordinal=0)
        large = flash_attn_predictor._periodic_round_robin_worker_programs(
            period, 108 * 1024, 108, start_ordinal=0)

        def encoded_order_size(programs):
            return sum(
                len(order) + len(tail)
                for program in programs
                if program is not None
                for order, _, tail in (program,)
            )

        assert encoded_order_size(large) == encoded_order_size(small)
        assert encoded_order_size(large) <= 2 * len(period) * 108

    def test_a800_fa_envelope_size_is_independent_of_repeated_requests(self):
        small_kernel = _tiled_flash_attention_kernel(
            batch=1,
            q_len=4096,
            kv_len=4096,
            query_heads=8,
            kv_heads=2,
            q_lens=(4096,),
            kv_lens=(4096,),
            causal=True,
        )
        kernel = _tiled_flash_attention_kernel(
            batch=2,
            q_len=4096,
            kv_len=4096,
            query_heads=8,
            kv_heads=2,
            q_lens=(4096,) * 2,
            kv_lens=(4096,) * 2,
            causal=True,
        )
        small_plan = _resource_input_for(small_kernel, HARDWARE).pipeline_plan
        plan = _resource_input_for(kernel, HARDWARE).pipeline_plan

        assert small_plan is not None
        assert plan is not None
        assert isinstance(small_plan, AttentionPipelineEnvelopeDemand)
        assert isinstance(plan, AttentionPipelineEnvelopeDemand)
        assert small_kernel.launch.grid_size == 512
        assert kernel.launch.grid_size == 1024
        assert len(small_plan.classes) == 32
        assert len(plan.classes) == 2
        assert small_plan.source_repeat_count == 8
        assert plan.source_repeat_count == 1
        logical_ctas = sum(
            work_class.count for work_class in plan.classes)
        assert logical_ctas == kernel.launch.grid_size
        total_panels = sum(
            work_class.panel_count * work_class.count
            for work_class in plan.classes)
        assert total_panels == 16_896

    def test_a800_fa_pipeline_description_is_kv_length_independent(self):
        plans = []
        for kv_len in (512, 4096, 65536):
            kernel = _tiled_flash_attention_kernel(
                batch=1,
                q_len=128,
                kv_len=kv_len,
                query_heads=8,
                kv_heads=2,
                q_lens=(128,),
                kv_lens=(kv_len,),
                causal=False,
            )
            plan = _resource_input_for(kernel, HARDWARE).pipeline_plan
            assert isinstance(plan, AttentionPipelineEnvelopeDemand)
            plans.append(plan)

        stage_counts = tuple(
            sum(
                len(phase.stages)
                for work_class in plan.classes
                for phase in work_class.phases)
            for plan in plans)
        logical_panel_counts = tuple(
            sum(
                phase.repeat_count
                for work_class in plan.classes
                for phase in work_class.phases
                if phase.name == "steady_panel")
            for plan in plans)

        assert stage_counts == (51, 51, 51)
        assert logical_panel_counts == (2, 30, 510)

    def test_a800_fa_pipeline_preserves_causal_panel_moments(self):
        class_counts = []
        for q_len in (512, 4096):
            kernel = _tiled_flash_attention_kernel(
                batch=1,
                q_len=q_len,
                kv_len=q_len,
                query_heads=8,
                kv_heads=2,
                q_lens=(q_len,),
                kv_lens=(q_len,),
                causal=True,
            )
            plan = _resource_input_for(kernel, HARDWARE).pipeline_plan
            assert isinstance(plan, AttentionPipelineEnvelopeDemand)
            expected_per_head = tuple(
                math.ceil(end / 128)
                for end in range(64, q_len + 1, 64))
            assert sum(
                work_class.panel_count * work_class.count
                for work_class in plan.classes) * plan.source_repeat_count == (
                    sum(expected_per_head) * 8)
            assert plan.source_repeat_count * sum(
                work_class.count for work_class in plan.classes) == (
                    len(expected_per_head) * 8)
            class_counts.append(
                len(plan.classes) * plan.source_repeat_count)

        assert tuple(class_counts) == (32, 256)

        chunked = _tiled_flash_attention_kernel(
            batch=2,
            q_len=4096,
            kv_len=4096,
            query_heads=32,
            kv_heads=8,
            q_lens=(128, 4096),
            kv_lens=(128, 4096),
            causal=True,
        )
        chunked = dataclasses.replace(
            chunked,
            attributes={
                **chunked.attributes,
                "kv_layout": "chunked_prefill",
            },
        )
        chunked_input = _resource_input_for(chunked, HARDWARE)
        chunked_plan = chunked_input.pipeline_plan
        assert isinstance(chunked_plan, AttentionPipelineEnvelopeDemand)
        assert chunked_plan.active_lane_count == 108
        assert chunked_plan.buffers == (PipelineBuffer(
            name="resident_cta",
            producer_stage="cta_begin",
            consumer_stage="cta_end",
            slots=2,
            scope="worker",
        ),)
        assert sum(
            work_class.count for work_class in chunked_plan.classes
        ) < chunked.launch.grid_size
        assert chunked_input.dependency_paths == ()
        assert "fa2_empty_cta_issue_lifecycle_unavailable" not in (
            chunked_input.limitations)

