    @pytest.mark.parametrize(
        ("q_len", "kv_len", "causal_fraction"),
        (
            # Q=KV: the four Q tiles attend 1, 1, 2, 2 KV tiles.
            (256, 256, 6 / 8),
            # Bottom-right Q<KV: context shifts those counts to 2, 2, 3, 3.
            (256, 384, 10 / 12),
        ),
    )
    def test_causal_prefill_uses_bottom_right_tile_work(
            self, q_len, kv_len, causal_fraction):
        common = dict(
            batch=1,
            q_len=q_len,
            kv_len=kv_len,
            query_heads=8,
            kv_heads=2,
            q_lens=(q_len,),
            kv_lens=(kv_len,),
        )
        causal = _demand(_tiled_flash_attention_kernel(
            **common, causal=True))["compute_tensor"]
        full = _demand(_tiled_flash_attention_kernel(
            **common, causal=False))["compute_tensor"]

        assert causal == pytest.approx(full * causal_fraction)

    def test_gqa_tensor_flops_scale_with_query_heads(self):
        common = dict(
            batch=1,
            q_len=256,
            kv_len=384,
            kv_heads=2,
            q_lens=(256,),
            kv_lens=(384,),
            causal=True,
        )
        four_query_heads = _demand(_tiled_flash_attention_kernel(
            **common, query_heads=4))["compute_tensor"]
        eight_query_heads = _demand(_tiled_flash_attention_kernel(
            **common, query_heads=8))["compute_tensor"]

        assert eight_query_heads == 2 * four_query_heads

