    @pytest.mark.parametrize("service", ("exp", "div"))
    def test_ascend_typed_worker_operations_require_matching_invocations(
            self, service):
        kernel = _selected_ascend_decode_kernel(kv_len=4096)
        parameters = dict(kernel.launch.parameters)
        worker_count = int(parameters[
            "cann_source_vector_worker_count"])
        positive_worker = next(
            worker for worker in range(worker_count)
            if parameters[
                f"cann_source_vector_worker_{worker}_{service}_operations"]
            > 0)
        parameters[
            f"cann_source_vector_worker_{positive_worker}_{service}_invocations"
        ] = 0.0

        with pytest.raises(
                ValueError, match="operations and invocations.*positive"):
            dataclasses.replace(
                kernel,
                launch=dataclasses.replace(
                    kernel.launch, parameters=parameters),
            )

    def test_ascend_typed_worker_operations_must_be_integral(self):
        kernel = _selected_ascend_decode_kernel(kv_len=4096)
        parameters = dict(kernel.launch.parameters)
        worker_count = int(parameters[
            "cann_source_vector_worker_count"])
        positive_workers = [
            worker for worker in range(worker_count)
            if parameters[
                f"cann_source_vector_worker_{worker}_generic_operations"]
            >= 1.0
        ]
        first, second = positive_workers[:2]
        parameters[
            f"cann_source_vector_worker_{first}_generic_operations"] += 0.5
        parameters[
            f"cann_source_vector_worker_{second}_generic_operations"] -= 0.5

        with pytest.raises(ValueError, match="operations must be integral"):
            dataclasses.replace(
                kernel,
                launch=dataclasses.replace(
                    kernel.launch, parameters=parameters),
            )

    def test_ascend_standard_decode_applies_source_closed_cube_padding(self):
        kernel = _selected_ascend_decode_kernel(kv_len=4096)
        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        tensor_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_tensor")
        vector_demand, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_vector")
        paths = {
            path.name: path for path in resource_input.memory_paths}
        write_path = paths["mte3_write"]

        assert kernel.launch.algorithm == (
            "cann_flash_attention_score:103000000010422221")
        assert tensor_demand.shape_efficiency == 4 / 16
        assert vector_demand.shape_efficiency == 1.0
        assert vector_demand.schedule_efficiency == 1.0
        score_elements = 32 * 4096
        output_elements = 32 * 128
        initialization_operations = 2 * kernel.launch.grid_size * 2 * 512
        brcb_operations = int(kernel.launch.parameters[
            "cann_source_task_count"]) * 64
        assert vector_demand.operations == (
            initialization_operations + 5 * score_elements + 32
            + brcb_operations + 2 * output_elements)
        assert kernel.launch.parameters[
            "cann_source_vector_initialization_operations"] == (
                initialization_operations)
        services = {
            service.service: service
            for service in vector_demand.service_demands}
        assert set(services) == {"generic", "exp", "div"}
        assert all(
            len(service.operations_by_worker)
            == 2 * kernel.launch.grid_size
            for service in services.values())
        assert services["exp"].operations == score_elements + 32
        assert services["div"].operations == output_elements
        assert all(
            services["generic"].operations_by_worker[worker] == 2 * 512
            for worker in range(1, 2 * kernel.launch.grid_size, 2))
        assert write_path.source.active_units == 2 * kernel.launch.grid_size
        assert set(paths) == {
            "mte2_read", "mte3_write", "fixpipe_l2_write",
            "kfc_workspace_clear"}
        # The AscendC MIX entry clears each core's KFC message region before
        # any operator phase; it is an L1->GM copy, so it is neither MTE3 nor
        # Fixpipe and carries its own path.
        assert {
            node.resource_role: node.bytes
            for node in paths["kfc_workspace_clear"].nodes
        } == {
            "l2_cache": self._cann_kfc_clear(kernel),
            "dram": self._cann_kfc_clear(kernel),
        }
        assert "cann_standard_decode_dynamic_partition_unavailable" not in (
            resource_input.limitations)
        assert "cann_standard_decode_output_init_partition_unavailable" not in (
            resource_input.limitations)
        assert "cann_standard_decode_workspace_padding_unavailable" not in (
            resource_input.limitations)
        assert "cann_standard_decode_vector_padding_and_merge_unavailable" not in (
            resource_input.limitations)
        assert "cann_fia_fixpipe_service_evidence_unavailable" not in (
            resource_input.limitations)
        assert "cann_fia_fixpipe_tail_service_evidence_unavailable" not in (
            resource_input.limitations)
        assert "cann_fia_workspace_dram_residency_unavailable" in (
            resource_input.limitations)
        assert "cann_flash_decode_vector_demand_unavailable" not in (
            resource_input.limitations)

        ledger = resource_input.phase_ledger
        assert ledger is not None
        assert tuple(phase.name for phase in ledger.phases) == (
            "kfc_workspace_clear",
            "aiv_initialization", "output_init", "mm1", "vec1", "mm2",
            "vec2")
        assert tuple(phase.predecessors for phase in ledger.phases) == (
            (), ("kfc_workspace_clear",), ("aiv_initialization",),
            ("kfc_workspace_clear",), ("mm1", "output_init"),
            ("vec1",), ("mm2",))
        assert all(phase.completion_barrier for phase in ledger.phases)
        assert isinstance(
            resource_input.pipeline_plan, FiaCrossDomainWorkPlan)
        plan = resource_input.pipeline_plan
        assert plan.task_counts == (1,) * 8
        assert plan.tiling_data_prelude is not None
        assert plan.tiling_data_prelude.payload_bytes == 1560
        assert plan.tiling_data_prelude.aiv_transfer_bytes == 1568
        assert plan.tiling_data_prelude.active_aic_groups == 8
        assert all(
            task.mm1_mte1.load_pair is not None
            and task.mm1_mte1.load_pair.stage_kind == "mm1"
            and task.mm1_mte1.load_pair.head_dim == 128
            and task.mm1_mte1.load_pair.count == 32
            and task.mm2_mte1.load_pair is not None
            and task.mm2_mte1.load_pair.stage_kind == "mm2"
            and task.mm2_mte1.load_pair.head_dim == 128
            and task.mm2_mte1.load_pair.count == 32
            for group in plan.groups
            for task in group.tasks)
        assert tuple(
            stage.physical_worker
            for stage in plan.aiv_initialization_stages) == tuple(range(16))
        assert all(
            stage.logical_operations == 2 * 512
            for stage in plan.aiv_initialization_stages)
        main_aiv_mte2_bytes = 0
        main_aiv_mte3_bytes = 0
        for group in plan.groups:
            for task in group.tasks:
                multiplier = group.class_count * task.repeat_count
                for memory in (
                        task.vec1_memory, task.vec1_update_memory,
                        task.vec1_peer_memory,
                        task.vec1_peer_update_memory, task.vec2_memory,
                        task.vec2_peer_memory):
                    if memory is not None:
                        main_aiv_mte2_bytes += multiplier * memory.mte2_bytes
                        main_aiv_mte3_bytes += multiplier * memory.mte3_bytes
        assert main_aiv_mte2_bytes == sum(
            kernel.launch.parameters[name] for name in (
                "cann_source_vec1_read_bytes",
                "cann_source_vec2_mm2_read_bytes",
                "cann_source_vec2_state_read_bytes"))
        assert main_aiv_mte3_bytes == sum(
            kernel.launch.parameters[name] for name in (
                "cann_source_vec1_write_bytes",
                "cann_source_nupdate_write_bytes",
                "cann_source_vec2_write_bytes"))
        assert resource_input.support_level == "partial"
        ledger.validate_conservation(
            resource_input.compute_demands, resource_input.memory_paths)

        tensor_by_phase = {
            phase.name: sum(
                demand.operations for demand in phase.compute_demands
                if demand.resource_role == "compute_tensor")
            for phase in ledger.phases
        }
        vector_by_phase = {
            phase.name: sum(
                demand.operations for demand in phase.compute_demands
                if demand.resource_role == "compute_vector")
            for phase in ledger.phases
        }
        assert tensor_by_phase["mm1"] == pytest.approx(
            0.5 * tensor_demand.operations)
        assert tensor_by_phase["mm2"] == pytest.approx(
            0.5 * tensor_demand.operations)
        assert vector_by_phase["aiv_initialization"] == (
            initialization_operations)
        assert vector_by_phase["vec1"] == 5 * score_elements + 32
        assert vector_by_phase["vec2"] == (
            brcb_operations + 2 * output_elements)

        phase_memory = {
            phase.name: {
                (demand.path_name, demand.resource_role): demand.bytes
                for demand in phase.memory_demands
            }
            for phase in ledger.phases
        }
        query_bytes = 32 * 128 * 2
        key_or_value_bytes = 8 * 4096 * 128 * 2
        score_elements = 32 * 4096
        score_fp32_bytes = score_elements * 4
        score_bf16_bytes = score_elements * 2
        output_fp32_bytes = 32 * 128 * 4
        mte3_nodes = {
            node.resource_role: node.bytes
            for node in paths["mte3_write"].nodes}
        # MTE3 moves every byte, but DRAM sees the distinct extent: the
        # vec1Res/vec2Res rings are charged once however often their slots are
        # rewritten, and output_init rewrites the output's own addresses.
        assert mte3_nodes == {
            "mte3": query_bytes + score_bf16_bytes + query_bytes,
            "l2_cache": query_bytes + score_bf16_bytes + query_bytes,
            "dram": kernel.launch.parameters[
                "cann_source_aiv_unique_write_bytes"],
        }
        # The mm1Res/mm2Res ring is charged once however often its slots are
        # rewritten, exactly as the AIV rings above.
        assert {
            node.resource_role: node.bytes
            for node in paths["fixpipe_l2_write"].nodes
        } == {
            "l2_cache": score_fp32_bytes + output_fp32_bytes,
            "dram": kernel.launch.parameters[
                "cann_source_aic_unique_write_bytes"],
        }
        # output_init rewrites the output's own addresses, which the direct
        # output write then covers, so it adds no distinct DRAM extent.
        assert phase_memory["output_init"] == {
            ("mte3_write", "mte3"): query_bytes,
            ("mte3_write", "l2_cache"): query_bytes,
        }
        kv_fill_share = self._cann_kv_fill_share(
            ASCEND_HARDWARE, 8, 128, 2, 2 * key_or_value_bytes)
        assert phase_memory["mm1"] == {
            ("mte2_read", "l2_cache"): query_bytes + key_or_value_bytes,
            ("mte2_read", "dram"): (
                query_bytes + key_or_value_bytes / kv_fill_share),
            ("fixpipe_l2_write", "l2_cache"): score_fp32_bytes,
            # MM1 stores into the per-core mm1Res ring on the same
            # PRELOAD_NUM-deep rotation, so DRAM sees its distinct extent.
            ("fixpipe_l2_write", "dram"): kernel.launch.parameters[
                "cann_source_mm1_unique_write_bytes"],
        }
        # Vec1 stores into the per-core vec1Res ring, so DRAM sees that
        # ring's distinct extent rather than every rewrite of it.
        assert phase_memory["vec1"] == {
            ("mte2_read", "l2_cache"): score_fp32_bytes,
            ("mte3_write", "mte3"): score_bf16_bytes,
            ("mte3_write", "l2_cache"): score_bf16_bytes,
            ("mte3_write", "dram"): kernel.launch.parameters[
                "cann_source_vec1_unique_write_bytes"],
        }
        assert phase_memory["mm2"] == {
            ("mte2_read", "l2_cache"):
                key_or_value_bytes + score_bf16_bytes,
            ("mte2_read", "dram"): key_or_value_bytes / kv_fill_share,
            ("fixpipe_l2_write", "l2_cache"): output_fp32_bytes,
            ("fixpipe_l2_write", "dram"): kernel.launch.parameters[
                "cann_source_mm2_unique_write_bytes"],
        }
        assert phase_memory["vec2"] == {
            ("mte2_read", "l2_cache"): output_fp32_bytes,
            ("mte3_write", "mte3"): query_bytes,
            ("mte3_write", "l2_cache"): query_bytes,
            ("mte3_write", "dram"): (
                kernel.launch.parameters[
                    "cann_source_vec2_unique_write_bytes"]
                + query_bytes),
        }

