    def test_ascend_standard_gqa_attaches_source_row_sum_geometry(self):
        kernel = _selected_ascend_decode_kernel(kv_len=512)
        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        plan = resource_input.pipeline_plan

        assert isinstance(plan, FiaCrossDomainWorkPlan)
        descriptors = tuple(
            descriptor
            for group in plan.groups
            for task in group.tasks
            for descriptor in task.vec1_block_reduce_sum)
        assert sum(
            group.class_count
            * len(task.vec1_block_reduce_sum)
            for group in plan.groups
            for task in group.tasks) == 8
        assert {
            (
                descriptor.row_chunk_round,
                descriptor.column_count,
                descriptor.column_alignment,
                descriptor.count,
            )
            for descriptor in descriptors
        } == {(8, 512, 32, 1)}

        prediction = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            resource_input)
        per_task_s = ASCEND_HARDWARE.fia_block_reduce_sum_time_ns(
            8, 512, 32) * 1e-9
        per_task_max_s = ASCEND_HARDWARE.fia_block_reduce_max_time_ns(
            8, 512, 32) * 1e-9
        per_task_brcb_s = ASCEND_HARDWARE.fia_brcb_time_ns(8) * 1e-9
        assert prediction.diagnostics.pipeline.stage_service_s[
            "aiv_block_reduce_sum"] == pytest.approx(8 * per_task_s)
        assert prediction.diagnostics.pipeline.stage_service_s[
            "aiv_block_reduce_max"] == pytest.approx(8 * per_task_max_s)
        assert prediction.diagnostics.pipeline.stage_service_s[
            "aiv_brcb"] == pytest.approx(8 * per_task_brcb_s)
        baseline_groups = tuple(dataclasses.replace(
            group,
            tasks=tuple(dataclasses.replace(
                task, vec1_block_reduce_sum=()) for task in group.tasks),
        ) for group in plan.groups)
        baseline_input = dataclasses.replace(
            resource_input,
            pipeline_plan=dataclasses.replace(plan, groups=baseline_groups),
        )
        baseline = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            baseline_input)
        assert prediction.t_per_group["pipeline"] - baseline.t_per_group[
            "pipeline"] == pytest.approx(
                per_task_s + per_task_max_s + per_task_brcb_s)

