    def test_ascend_mla_uses_distinct_qk_and_value_dimensions(self):
        kernel = _selected_ascend_mla_decode_kernel(kv_len=512)
        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, ASCEND_HARDWARE)
        paths = {path.name: path for path in resource_input.memory_paths}
        mte2_nodes = {
            node.resource_role: node.bytes
            for node in paths["mte2_read"].nodes
        }
        mte3_nodes = {
            node.resource_role: node.bytes
            for node in paths["mte3_write"].nodes
        }
        fixpipe_nodes = {
            node.resource_role: node.bytes
            for node in paths["fixpipe_l2_write"].nodes
        }

        qk_dim = 512 + 64
        value_dim = 512
        query_bytes = 64 * qk_dim * 2
        key_bytes = 512 * qk_dim * 2
        value_bytes = 512 * value_dim * 2
        output_bytes = 64 * value_dim * 2
        input_bytes = query_bytes + key_bytes + value_bytes
        # MLA keeps one latent per position and the value operand is that
        # latent's leading value_dim channels, so both operands are charged
        # at L2 but they share a single compulsory GM footprint.
        latent_dram_bytes = query_bytes + key_bytes
        tensor_operations = 2 * 64 * 512 * (qk_dim + value_dim)
        score_elements = 64 * 512
        output_elements = 64 * value_dim
        workspace_read_bytes = (
            6 * score_elements + 4 * output_elements)
        aiv_write_bytes = 2 * score_elements

        assert kernel.launch.algorithm in (
            flash_attn_predictor._CANN_MLA_DECODE_ALGORITHMS)
        assert resource_input.demand_per_resource["compute_tensor"] == (
            tensor_operations)
        assert resource_input.demand_per_resource["compute_vector"] == (
            kernel.launch.parameters["cann_source_vector_operations"])
        assert mte2_nodes == {
            "l2_cache": pytest.approx(input_bytes + workspace_read_bytes),
            "dram": pytest.approx(latent_dram_bytes),
        }
        assert mte3_nodes == {
            "mte3": pytest.approx(2 * output_bytes + aiv_write_bytes),
            "l2_cache": pytest.approx(2 * output_bytes + aiv_write_bytes),
            "dram": pytest.approx(2 * output_bytes),
        }
        # One task per core, so the mm1Res/mm2Res ring never rotates and its
        # distinct extent is that single task's whole Fixpipe write.
        assert kernel.launch.parameters[
            "cann_source_aic_unique_write_bytes"] == pytest.approx(
                4 * score_elements + 4 * output_elements)
        assert fixpipe_nodes == {
            "l2_cache": pytest.approx(
                4 * score_elements + 4 * output_elements),
            "dram": pytest.approx(
                4 * score_elements + 4 * output_elements),
        }
        assert resource_input.demand_per_resource["l2_cache"] == (
            pytest.approx(
                input_bytes + workspace_read_bytes
                + 2 * output_bytes + aiv_write_bytes
                + 4 * score_elements + 4 * output_elements
                + self._cann_kfc_clear(kernel)))
        assert compulsory == input_bytes
        assert resource_input.support_level == "partial"
        assert isinstance(
            resource_input.pipeline_plan, FiaCrossDomainWorkPlan)
        assert resource_input.pipeline_plan.task_counts == (1,)
        assert "cann_fia_workspace_dram_residency_unavailable" in (
            resource_input.limitations)
        for limitation in (
                "cann_mla_dynamic_partition_unavailable",
                "cann_mla_workspace_lifecycle_unavailable",
                "cann_mla_nupdate_pipeline_unavailable",
                "cann_fia_fixpipe_service_evidence_unavailable",
                "cann_flash_attention_tile_pipeline_unavailable"):
            assert limitation not in resource_input.limitations

