    def test_metax_source_bound_tile16_decode_uses_common_attention_pipeline(
            self):
        kernel = _metax_tile16_flash_attention_kernel(
            kv_lens=(128, 512),
            algorithm=(
                "observed_metax_flash_attention_trait_direct:decode"),
        )
        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        plan = resource_input.pipeline_plan

        assert isinstance(plan, AttentionPipelineEnvelopeDemand)
        assert plan.active_lane_count == kernel.launch.grid_size == 16
        assert resource_input.support_level == "partial"
        assert "gpu_flash_attention_cta_worker_mapping_unavailable" not in (
            resource_input.limitations)
        assert tuple(buffer.slots for buffer in plan.buffers) == (8,)
        assert tuple(
            (work_class.name, work_class.count, work_class.panel_count)
            for work_class in plan.classes
        ) == (
            ("cold_steps8_rows128", 8, 8),
            ("cold_steps32_rows512", 8, 32),
        )
        stages = tuple(
            stage.name
            for work_class in plan.classes
            for phase in work_class.phases
            for stage in phase.stages)
        for required in (
                "cta_start", "load_k_0", "qk_0", "softmax_0", "pv_0",
                "stage_output", "store"):
            assert required in stages
        assert max(
            len(work_class.phases)
            for work_class in plan.classes) <= 6
        assert max(
            phase.repeat_count
            for work_class in plan.classes
            for phase in work_class.phases) == 1
        long_class = plan.classes[1]
        assert tuple(
            (phase.name, phase.repeat_count)
            for phase in long_class.phases) == (
                ("prologue", 1),
                ("first_page", 1),
                ("steady_page", 1),
                ("pre_final_page", 1),
                ("final_page", 1),
                ("epilogue", 1),
            )
        latency_stages = {
            stage.name
            for phase in long_class.phases
            for stage in phase.stages
            if stage.include_first_request_latency
            and stage.name.startswith("load_")
        }
        expected_latency_stages = {
            "load_k_0", "load_v_0",
            "load_k_first_page_8",
            "load_k_steady_page_8", "load_k_pre_final_page_8",
        }
        expected_latency_stages.update(
            stage.name
            for phase in long_class.phases
            for stage in phase.stages
            if stage.name.startswith("load_v_"))
        assert latency_stages == expected_latency_stages

        prediction = PerformanceFormula(METAX_HARDWARE).predict_kernel(
            resource_input)
        assert prediction.diagnostics.pipeline is not None
        assert prediction.t_per_group["pipeline"] > 0.0

