    def test_metax_graph_splitkv_body_keeps_paged_empty_split_exits(self):
        """The Graph split body has one executable source program per CTA."""

        shape = {
            "batch": 56,
            "q_len": 1,
            "kv_len": 839,
            "head_dim": 128,
            "num_query_heads": 32,
            "num_kv_heads": 8,
        }
        attributes = {
            "is_decode": True,
            "causal": True,
            "kv_layout": "paged_varlen",
            "kv_dist": "skew",
            "q_lens": (1,) * 56,
            "kv_lens": (
                745, 23, 123, 71, 33, 69, 48, 88, 677, 236, 15, 386,
                408, 24, 750, 252, 27, 409, 331, 67, 418, 94, 186, 31,
                33, 193, 512, 254, 389, 839, 390, 9, 683, 29, 745, 388,
                61, 335, 14, 40, 164, 791, 32, 60, 26, 337, 60, 275, 7,
                50, 159, 307, 773, 316, 21, 76),
            "fa_ksteps": None,
            "fa_eff_mfrac": 1.0,
            "launch_policy": "injected_launch",
            "split_policy": "serving",
            "graph_runtime_mode": "FULL",
        }
        launch = _select_launch_config(
            METAX_HARDWARE.hardware_id, KernelKind.FLASH_ATTN, shape,
            "bf16", "decode", attributes, hardware=METAX_HARDWARE)
        kernel_attributes = {
            name: attributes[name] for name in (
                "causal", "kv_layout", "kv_dist", "q_lens", "kv_lens",
                "fa_ksteps", "fa_eff_mfrac")}
        kernel = KernelSpec(
            KernelKind.FLASH_ATTN, METAX_HARDWARE.hardware_id, shape,
            dtype="bf16", variant="decode", launch=launch,
            attributes=kernel_attributes)

        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        plan = resource_input.pipeline_plan
        classes, head_groups = _pipeline_cta_class_counts(
            kernel, 16, 16, grouped_mla=False, include_empty_splits=True)

        assert kernel.launch.grid == (1, 448, 5)
        assert head_groups == 8
        assert sum(count for _, count in classes) == kernel.launch.grid_size
        assert sum(
            count for item, count in classes if item.step_count == 0) == 488
        assert isinstance(plan, AttentionPipelineEnvelopeDemand)
        empty_classes = tuple(
            work_class for work_class in plan.classes
            if work_class.panel_count == 0)
        assert len(empty_classes) == 1
        empty_class, = empty_classes
        assert empty_class.count == 488
        empty_stages = empty_class.phases[0].stages
        assert tuple(stage.name for stage in empty_stages) == (
            "cta_start", "store")
        assert tuple(stage.service for stage in empty_stages) == (
            "memory:global_write", "memory:global_write")
        assert all(
            stage.predecessors == (() if index == 0 else ("cta_start",))
            for index, stage in enumerate(empty_stages))
        assert PerformanceFormula(METAX_HARDWARE).predict_kernel(
            resource_input).diagnostics.pipeline is not None

        combine_attributes = dict(attributes)
        combine_attributes["num_kv_splits"] = launch.tiling.num_kv_splits
        combine_launch = _select_launch_config(
            METAX_HARDWARE.hardware_id, KernelKind.FLASH_ATTN, shape,
            "bf16", "combine", combine_attributes,
            hardware=METAX_HARDWARE)
        combine = KernelSpec(
            KernelKind.FLASH_ATTN, METAX_HARDWARE.hardware_id, shape,
            dtype="bf16", variant="combine", launch=combine_launch,
            attributes=kernel_attributes)
        combine_input = _resource_input_for(combine, METAX_HARDWARE)
        dependency_stages = (
            flash_attn_predictor._metax_fa2_combine_dependency_stages(
                combine, METAX_HARDWARE))

        assert combine.launch.grid == (224, 1, 1)
        assert flash_attn_predictor._metax_fa2_combine_max_splits(
            combine) == 8
        assert dependency_stages == {
            "lse_shared_transpose": pytest.approx(135.994140625),
            "max_allreduce": pytest.approx(236.0),
            "post_max_exp_sum": pytest.approx(56.0),
            "sum_allreduce": pytest.approx(220.0),
            "post_sum_log": pytest.approx(216.0),
            "scale_shared_barrier": pytest.approx(172.076171875),
            "output_conversion": pytest.approx(4.0),
        }
        assert combine_input.pipeline_plan is not None
        assert isinstance(
            combine_input.pipeline_plan, AttentionPipelineEnvelopeDemand)
        assert combine_input.pipeline_plan.active_lane_count == 104
        assert combine_input.demand_per_resource["compute_reduction"] == (
            pytest.approx(224 * 1040.0703125))

        # The isolated C500 fragment represents kMaxSplits=8 with a partial
        # predicate.  A full eight-split invocation has a distinct source
        # path, so it must not borrow that fragment merely because its launch
        # geometry is otherwise identical.
        full_eight = dataclasses.replace(
            combine,
            launch=dataclasses.replace(
                combine.launch,
                tiling=dataclasses.replace(
                    combine.launch.tiling, num_kv_splits=8),
            ),
        )
        assert not flash_attn_predictor._is_source_bound_metax_fa2_combine(
            full_eight)

        wrong_grid = dataclasses.replace(
            kernel.launch, grid=(8, 1, 8))
        with pytest.raises(ValueError, match="grid axes"):
            _resource_input_for(
                dataclasses.replace(kernel, launch=wrong_grid),
                METAX_HARDWARE,
            )

