    def test_metax_q64_prefill_pipeline_preserves_source_order(self):
        kernel = _observed_flash_attention_kernel(
            METAX_HARDWARE,
            algorithm=(
                "observed_metax_flash_attention_trait_direct:"
                "prefill_q64_full_tile"),
            grid=(32, 8, 2),
            block=(256, 1, 1),
            tile_shape={"q": 64, "kv": 64, "head": 128},
            splits=1,
            batch=2,
            q_len=512,
            kv_len=512,
            head_dim=128,
            query_heads=32,
            kv_heads=8,
            q_lens=(512, 512),
            kv_lens=(512, 512),
            causal=True,
            kv_layout="paged_varlen",
            variant="prefill",
        )

        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        plan = resource_input.pipeline_plan
        tensor_demand = next(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_tensor")

        assert isinstance(plan, AttentionPipelineEnvelopeDemand)
        assert tensor_demand.schedule_efficiency == pytest.approx(
            flash_attn_predictor._metax_bf16_mma_capacity_for_active_waves(8)
            / flash_attn_predictor._METAX_372_FA_TENSOR_OPS_PER_AP_CYCLE)
        # 512 active CTAs exceed the 208-CTA resident window (104 APs x 2
        # resident CTAs), so only the resident prefix keeps its exact source
        # order; beyond it a freed AP takes whichever CTA is next, and the
        # queued remainder is carried as its CTA-count- and panel-work-
        # preserving balance rather than as a fixed CTA-to-AP mapping.
        resident_capacity = 104 * 2
        prefix = []
        remaining = resident_capacity
        for work_class in plan.classes:
            if remaining <= 0:
                break
            taken = min(remaining, work_class.count)
            prefix.append((work_class.panel_count, taken))
            remaining -= taken
        assert prefix == [
            (panel_count, 32) for panel_count in range(8, 2, -1)] + [(2, 16)]
        assert sum(count for _, count in prefix) == resident_capacity
        assert plan.source_repeat_count == 1
        # The envelope and its KV-panel work are conserved exactly.
        assert sum(
            work_class.count
            for work_class in plan.classes) * plan.source_repeat_count == 512
        assert sum(
            work_class.panel_count * work_class.count
            for work_class in plan.classes) * plan.source_repeat_count == (
                2 * 32 * sum(range(1, 9)))
        expected_barriers = 2 * 32 * sum(
            2 * panel_count + 4 for panel_count in range(1, 9))
        assert resource_input.demand_per_resource["compute_reduction"] == (
            expected_barriers
            * METAX_HARDWARE.cta_barrier_service_cycles["barrier_cycles"])
        all_stage_names = {
            stage.name
            for work_class in plan.classes
            for phase in work_class.phases
            for stage in phase.stages
        }
        assert {
            "q_ready_barrier", "q_reuse_barrier", "ready_0", "consumed_0",
            "output_ready_barrier", "output_visible_barrier",
        }.issubset(all_stage_names)
        for work_class in plan.classes:
            prologue = work_class.phases[0]
            first_request_loads = {
                stage.name
                for stage in prologue.stages
                if stage.include_first_request_latency
            }
            assert first_request_loads == {
                "load_q", "load_k_0", "load_v_0",
            }

