        read_stage_names = {
            stage.name
            for work_class in plan.classes
            for phase in work_class.phases
            for stage in phase.stages
            if stage.service == "memory:global_read"
        }
        local_read_service = sum(
            prediction.diagnostics.pipeline.stage_service_s[name]
            for name in read_stage_names)
