    def test_paged_prefill_uses_finite_resident_ldgsts_service(self):
        kernel = _kernel(
            KernelKind.FLASH_ATTN,
            {
                "batch": 16,
                "q_len": 1024,
                "kv_len": 1024,
                "head_dim": 128,
                "num_query_heads": 32,
                "num_kv_heads": 8,
            },
            variant="prefill",
            attributes={"is_decode": False, "kv_layout": "paged"},
        )
        resource_input = _resource_input(kernel)
        paths = {path.name: path for path in resource_input.memory_paths}
        active_ctas = sum(
            work_class.count
            for work_class in resource_input.pipeline_plan.classes)
        transactions_per_panel = (
            HARDWARE.ldgsts_finite_resident_panel_bytes
            / HARDWARE.l2_transaction_bytes)
        average_panels = sum(
            work_class.count * work_class.panel_count
            for work_class in resource_input.pipeline_plan.classes
        ) / active_ctas
        query_transactions_per_cta = (
            64 * 128 * 2 / HARDWARE.l2_transaction_bytes)
        finite_cycles = (
            HARDWARE.ldgsts_finite_resident_affine_startup_cycles
            + average_panels
            * HARDWARE.ldgsts_finite_resident_affine_panel_cycles
            + HARDWARE.ldgsts_finite_resident_full_chip_ctas
            * query_transactions_per_cta
            / HARDWARE.ldgsts_initial_32b_transactions_full_chip_per_cycle)
        expected_per_unit_per_cycle = (
            HARDWARE.ldgsts_finite_resident_full_chip_ctas
            * (query_transactions_per_cta
               + transactions_per_panel * average_panels)
            / finite_cycles / resource_input.active_units)

        assert paths["global_read"].source.frontend_rate_per_unit_s == (
            pytest.approx(
                expected_per_unit_per_cycle * resource_input.sm_freq_hz))

    def test_paged_s512_prefill_uses_queued_steady_ldgsts_service(self):
        kernel = _tiled_flash_attention_kernel(
            batch=128,
            q_len=512,
            kv_len=512,
            query_heads=32,
            kv_heads=8,
            q_lens=(512,) * 128,
            kv_lens=(512,) * 128,
            causal=True,
        )
        resource_input = _resource_input(kernel)
        paths = {path.name: path for path in resource_input.memory_paths}
        active_ctas = sum(
            work_class.count
            for work_class in resource_input.pipeline_plan.classes)
        panel_counts = tuple(
            sum(
                work_class.count
                for work_class in resource_input.pipeline_plan.classes
                if work_class.panel_count == panel_count)
            for panel_count in (2, 3))
        transactions_per_panel = (
            HARDWARE.ldgsts_finite_resident_panel_bytes
            / HARDWARE.l2_transaction_bytes)
        query_transactions_per_cta = (
            64 * 128 * 2 / HARDWARE.l2_transaction_bytes)
        steady_panel_cycles = (
            HARDWARE.ldgsts_finite_resident_full_chip_ctas
            * transactions_per_panel * 2.5
            / HARDWARE
            .ldgsts_queued_steady_full_chip_initial_32b_transactions_per_cycle)
        query_cycles = (
            HARDWARE.ldgsts_finite_resident_full_chip_ctas
            * query_transactions_per_cta
            / HARDWARE.ldgsts_initial_32b_transactions_full_chip_per_cycle)
        expected_per_unit_per_cycle = (
            HARDWARE.ldgsts_finite_resident_full_chip_ctas
            * (query_transactions_per_cta + transactions_per_panel * 2.5)
            / (steady_panel_cycles + query_cycles)
            / resource_input.active_units)

        assert active_ctas == 32768
        assert panel_counts == (16384, 16384)
        assert paths["global_read"].source.frontend_rate_per_unit_s == (
            pytest.approx(
                expected_per_unit_per_cycle * resource_input.sm_freq_hz))

    def test_a800_paged_period32_service_partitions_q_and_kv_ingress(self):
        """The exact K/V service must not price the separate Q prologue."""

        kernel = _tiled_flash_attention_kernel(
            batch=1,
            q_len=4096,
            kv_len=4096,
            query_heads=32,
            kv_heads=8,
            q_lens=(4096,),
            kv_lens=(4096,),
            causal=True,
        )

        resource_input = _resource_input(kernel)
        paths = {path.name: path for path in resource_input.memory_paths}
        assert set(paths) == {"global_read", "global_kv_read", "global_write"}
        q_path = paths["global_read"]
        kv_path = paths["global_kv_read"]
        q_nodes = {node.resource_role: node for node in q_path.nodes}
        kv_nodes = {node.resource_role: node for node in kv_path.nodes}
        assert q_nodes["l2_cache"].bytes == q_nodes["dram"].bytes
        assert q_nodes["l2_cache"].bytes + kv_nodes["l2_cache"].bytes == (
            _demand(kernel)["l2_cache"] - paths["global_write"].nodes[0].bytes)
        assert q_nodes["dram"].bytes + kv_nodes["dram"].bytes == (
            _demand(kernel)["dram"] - paths["global_write"].nodes[1].bytes)
        demand, = kv_path.access_class_demands
        assert demand.service == (
            "sm80_fa2_paged_q64_kv128_period32_ldgsts")
        assert demand.replaces_ingress_path_service
        assert demand.logical_bytes == kv_nodes["l2_cache"].bytes

        plan = resource_input.pipeline_plan
        assert isinstance(plan, AttentionPipelineEnvelopeDemand)
        stages = tuple(
            stage
            for work_class in plan.classes
            for phase in work_class.phases
            for stage in phase.stages)
        assert any(
            stage.name == "load_q" and stage.service == "memory:global_read"
            for stage in stages)
        kv_stages = tuple(
            stage for stage in stages
            if stage.name.startswith(("load_k", "load_v")))
        assert kv_stages
        assert all(stage.service == "memory:global_kv_read"
                   for stage in kv_stages)

