    def test_metax_mla_main_l2_and_dram_share_one_latent_not_two_caches(self):
        """FLASHATTN_MLA_B8_S8192_HQ64_HKV1_D512_C0's source split geometry
        (kv_blocks_per_request=ceil(8192/16)=512, scheduler-derived splits),
        reproduced from kernel_dataset/metax_c500/flash_attn.json.zst.  MLA's
        KV cache is one shared qk_head_dim(576)-wide latent per position, not
        a separate 576-wide K cache plus a 512-wide V cache: before this fix,
        the main kernel's L2 (and, downstream, DRAM) summed both widths and
        over-predicted this case's read-only L2 traffic by 1.71x and its DRAM
        traffic by 1.57x.
        """
        batch = 8
        kv_lens = (8192,) * batch
        work = derive_mla_scheduler_work(kv_lens)
        kernel = _observed_flash_attention_kernel(
            METAX_HARDWARE,
            algorithm="observed_metax_flash_attention_persistent_queue",
            grid=(1, 1, METAX_MLA_SCHEDULER_PARTITIONS),
            block=(512, 1, 1),
            tile_shape={},
            splits=max(work.splits_per_request),
            batch=batch,
            q_len=1,
            kv_len=8192,
            head_dim=512,
            query_heads=64,
            kv_heads=1,
            q_lens=(1,) * batch,
            kv_lens=kv_lens,
            causal=True,
            kv_layout="mla",
            variant="decode",
        )
        kernel = dataclasses.replace(
            kernel,
            launch=dataclasses.replace(
                kernel.launch,
                parameters={
                    **kernel.launch.parameters,
                    "unpadded_flops": 1.0,
                },
            ),
        )

        l2_bytes, dram_bytes = flash_attn_predictor._tensor_traffic(
            kernel, METAX_HARDWARE)

        query_heads, element_bytes, qk_head_dim = 64, 2, 576
        query_l2 = work.segment_count * query_heads * qk_head_dim * element_bytes
        key_value_l2 = (
            work.kv_block_count * METAX_MLA_KV_BLOCK
            * qk_head_dim * element_bytes)
        output = flash_attn_predictor._metax_mla_main_output_bytes(kernel)
        assert l2_bytes == pytest.approx(query_l2 + key_value_l2 + output)
        # The rejected formula would instead carry qk_head_dim + 512 in
        # key_value_l2 -- assert the fix actually dropped that term, not
        # merely that some formula matches (the assertion above would also
        # pass trivially if both this test and the source used the same
        # stale width).
        assert l2_bytes < query_l2 + (
            work.kv_block_count * METAX_MLA_KV_BLOCK
            * (qk_head_dim + 512) * element_bytes) + output

        compulsory_query = query_heads * sum((1,) * batch) * qk_head_dim * element_bytes
        compulsory_kv = 1 * sum(kv_lens) * qk_head_dim * element_bytes
        assert dram_bytes == pytest.approx(
            compulsory_query + compulsory_kv + output)
        assert dram_bytes <= l2_bytes

        # The resource_input build (which independently re-derives the
        # read/write DRAM split via _output_bytes and a matching compulsory
        # baseline) must not regress into the read_dram > read_l2 state the
        # first version of this fix hit: exercising it end to end is the
        # regression guard for that coupling.
        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        assert resource_input.demand_per_resource["dram"] == (
            pytest.approx(dram_bytes))

    @pytest.mark.parametrize("batch", (8, 104))
    def test_metax_mla_main_smem_stages_conserve_source_bytes(self, batch):
        kv_lens = (512,) * batch
        work = derive_mla_scheduler_work(kv_lens)
        kernel = _observed_flash_attention_kernel(
            METAX_HARDWARE,
            algorithm="observed_metax_flash_attention_persistent_queue",
            grid=(1, 1, METAX_MLA_SCHEDULER_PARTITIONS),
            block=(512, 1, 1),
            tile_shape={},
            splits=max(work.splits_per_request),
            batch=batch,
            q_len=1,
            kv_len=512,
            head_dim=512,
            query_heads=64,
            kv_heads=1,
            q_lens=(1,) * batch,
            kv_lens=kv_lens,
            causal=True,
            kv_layout="mla",
            variant="decode",
        )
        kernel = dataclasses.replace(
            kernel,
            launch=dataclasses.replace(
                kernel.launch,
                parameters={
                    **kernel.launch.parameters,
                    "unpadded_flops": 1.0,
                },
            ),
        )

        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        split_segments = work.segment_count - work.unsplit_requests
        expected_smem_bytes = (
            work.segment_count * 147_456
            + work.kv_block_count * 53_248
            + split_segments * 262_144
            + work.unsplit_requests * 131_072)

        assert resource_input.demand_per_resource["smem"] == (
            float(expected_smem_bytes))

        plan = resource_input.pipeline_plan
        assert isinstance(plan, PipelineWorkPlan)
        stages = tuple(
            stage
            for program in plan.tasks
            for pattern in program.patterns[1:]
            for task in pattern.tasks
            for stage in task.stages)
        assert any(stage.name == "segment_stage_q"
                   and stage.predecessors == ("segment_load_q",)
                   for stage in stages)
        assert any(stage.name.endswith("_stage_k")
                   and stage.service == "resource:smem"
                   for stage in stages)
        assert any(stage.name.endswith("_stage_v")
                   and stage.predecessors[0].endswith("_softmax")
                   for stage in stages)
        assert any(stage.name == "segment_stage_output"
                   and stage.service == "resource:smem"
                   for stage in stages)

    def test_metax_mla_combine_prices_each_source_split_barrier(self):
        batch = 8
