    def test_a800_grouped_mla_l2_includes_q_replay_and_fp32_scratch(self):
        kernel = _observed_flash_attention_kernel(
            HARDWARE,
            algorithm="triton_grouped_mla_stage1",
            grid=(1, 4, 4),
            block=(128, 1, 1),
            tile_shape={
                "query_heads": 16,
                "kv": 32,
                "head": 512,
                "qk_head": 576,
                "value_head": 512,
            },
            splits=4,
            batch=1,
            q_len=1,
            kv_len=8192,
            head_dim=512,
            query_heads=64,
            kv_heads=1,
            q_lens=(1,),
            kv_lens=(8192,),
            causal=False,
            kv_layout="mla",
            variant="decode",
        )
        positions = 64
        kv_replay = 4 * 8192 * (576 + 512) * 2
        q_replay = positions * 4 * 576 * 2
        fp32_scratch = positions * 4 * (512 + 1) * 4

        resource_input = _resource_input(kernel)
        demand = resource_input.demand_per_resource

        assert demand["l2_cache"] == (
            kv_replay + q_replay + fp32_scratch)
        plan = resource_input.pipeline_plan
        assert isinstance(plan, AttentionPipelineEnvelopeDemand)
        memory_rounds = tuple(
            stage
            for work_class in plan.classes
            for phase in work_class.phases
            for stage in phase.stages
            if stage.name in {"panel_k", "load_v"}
        )
        assert memory_rounds
        assert all(
            stage.include_first_request_latency for stage in memory_rounds)
        issue = flash_attn_predictor._grouped_mla_sass_stage_issue_per_cta(
            kernel, 64)
        assert issue == flash_attn_predictor._GroupedMLASASSStageIssue(
            prologue=3320.0,
            qk=548.0,
            softmax=508.0,
            pv=1340.0,
            next_panel=900.0,
            epilogue=3252.0,
            cta_end=4.0,
        )
        issue_stage_names = {
            "prologue_issue", "qk_issue", "softmax_issue", "pv_issue",
            "next_panel_issue", "epilogue_issue", "cta_end",
        }
        issue_fraction = sum(
            work_class.count * phase.repeat_count * stage.work_fraction
            for work_class in plan.classes
            for phase in work_class.phases
            for stage in phase.stages
            if stage.name in issue_stage_names
        ) * plan.source_repeat_count
        assert issue_fraction == pytest.approx(1.0)
        first_panel = next(
            phase for phase in plan.classes[0].phases
            if phase.name == "first_panel")
        stages = {stage.name: stage for stage in first_panel.stages}
        assert stages["softmax_issue"].predecessors == (
            "qk", "load_v", "qk_issue")
        assert stages["pv_issue"].predecessors == (
            "softmax", "stage_v", "softmax_issue")
        assert stages["next_panel_issue"].predecessors == (
            "pv", "pv_issue")
        assert stages["panel_k"].predecessors == ("pv", "pv_issue")
        assert stages["panel_stage_k"].predecessors == (
            "panel_k", "next_panel_issue")

