@pytest.mark.parametrize(
    ("hardware", "variant", "read_copies", "write_copies"),
    (
        (HARDWARE, "moe_act_and_mul", 2, 1),
        (METAX_HARDWARE, "moe_silu", 1, 1),
        (METAX_HARDWARE, "moe_mul", 2, 1),
        (ASCEND_HARDWARE, "moe_swiglu", 2, 1),
    ),
)
def test_source_bound_moe_auxiliary_traffic_preserves_direction(
        hardware, variant, read_copies, write_copies):
    shape = {
        "tokens": 8,
        "experts": 4,
        "topk": 2,
        "hidden": 32,
        "intermediate": 64,
        "dtype_bytes": 2,
    }
    if (hardware.hardware_id == HARDWARE.hardware_id
            and variant == "moe_act_and_mul"):
        grid = (shape["tokens"] * shape["topk"], 1, 1)
        block = (1024, 1, 1)
    elif hardware.kernel_memory_model == "npu_tile":
        routed_rows = shape["tokens"] * shape["topk"]
        source_launch = ascend_vector_launch.select_vector_launch(
            shape, "bf16", variant, {
                "launch_policy": "analytical_launch",
                "routed_rows": routed_rows,
            }, hardware)
        grid = source_launch.grid
        block = source_launch.block
    else:
        grid = (1, 1, 1)
        block = (128, 1, 1)
    if hardware.kernel_memory_model == "npu_tile":
        launch = source_launch
    elif hardware.kernel_memory_model == "gpu_mshr":
        launch = LaunchConfig(
            algorithm="test_source_bound_moe_auxiliary",
            grid=grid,
            block=block,
            execution_variant=variant,
        )
    else:
        raise ValueError(
            f"unsupported kernel memory model: {hardware.kernel_memory_model}")
    if variant == "moe_swiglu":
        attributes = {"routed_rows": shape["tokens"] * shape["topk"]}
    elif variant in ("moe_silu", "moe_mul"):
        attributes = {"work_fraction": 1.0}
    else:
        attributes = {}
    kernel = KernelSpec(
        KernelKind.VECTOR,
        hardware.hardware_id,
        shape,
        dtype="bf16",
        variant=variant,
        launch=launch,
        attributes=attributes,
    )

    resource_input = _resource_input_for(kernel, hardware)
    element_bytes = shape["tokens"] * shape["topk"] * shape[
        "intermediate"] * shape["dtype_bytes"]
    paths = {path.name: path for path in resource_input.memory_paths}
    if hardware.kernel_memory_model == "npu_tile":
        read_path = paths["mte2_read"]
        write_path = paths["mte3_write"]
        assert {node.resource_role: node.bytes for node in read_path.nodes} == {
            "mte2": read_copies * element_bytes,
            "l2_cache": read_copies * element_bytes,
            "dram": read_copies * element_bytes,
        }
        assert {node.resource_role: node.bytes for node in write_path.nodes} == {
            "mte3": write_copies * element_bytes,
            "l2_cache": write_copies * element_bytes,
            "dram": write_copies * element_bytes,
        }
    else:
        assert {
            node.resource_role: node.bytes
            for node in paths["global_read"].nodes
        } == {
            "l2_cache": read_copies * element_bytes,
            "dram": read_copies * element_bytes,
        }
        assert {
            node.resource_role: node.bytes
            for node in paths["global_write"].nodes
        } == {
            "l2_cache": write_copies * element_bytes,
            "dram": write_copies * element_bytes,
        }
    if hardware.hardware_id == HARDWARE.hardware_id:
        output_elements = (
            shape["tokens"] * shape["topk"] * shape["intermediate"])
        scalar_rounds = (
            shape["tokens"] * shape["topk"]
            * math.ceil(shape["intermediate"] / 1024))
        assert resource_input.demand_per_resource["compute_vector"] == (
            scalar_rounds)
        assert resource_input.demand_per_resource["compute_fma"] == (
            output_elements)
        assert resource_input.demand_per_resource["compute_sfu"] == 0.0
        dependency_path, = resource_input.dependency_paths
        assert dependency_path.name == "silu"
        assert dependency_path.services == (
            "launch:submit", "memory:global_read",
            "local_memory:l1_cache",
            "compute:compute_vector", "compute:compute_fma",
            "memory:global_write")
    elif (hardware.hardware_id == ASCEND_HARDWARE.hardware_id
          and variant == "moe_swiglu"):
        forward_input, _ = forward_analytical_resource_input(
            kernel, hardware)
        assert forward_input.pipeline_plan is not None
        assert all(
            isinstance(program, (PipelineTaskDemand, PipelineTaskProgramDemand))
            for program in forward_input.pipeline_plan.tasks)
        # MoE uses the same CANN SwiGLU worker source.  Its published
        # multi-worker queue probes establish launch admission, rather than a
        # repeating worker-local edge, so the common model must expose that
        # evidence boundary for MoE as well as ordinary activation SwiGLU.
        assert (
            "cann_swiglu_multiworker_queue_completion_not_local"
            in forward_input.limitations)
        assert (
            "cann_swiglu_tile_address_scalar_service_unavailable"
            not in forward_input.limitations)


@pytest.mark.parametrize(
    ("variant", "expected_read_bytes", "expected_write_bytes"),
    (
        (
            "moe_init_routing",
            8 * 32 * 2 + 2 * (8 * 2) * 4,
            (8 * 2) * 32 * 2 + 2 * (8 * 2) * 4,
        ),
        (
            "moe_finalize_routing",
            (8 * 2) * 32 * 2 + (8 * 2) * 2 + (8 * 2) * 4,
            8 * 32 * 2,
        ),
    ),
)
def test_source_bound_cann_moe_routing_abi_preserves_direction_and_indices(
        variant, expected_read_bytes, expected_write_bytes):
    shape = {
        "tokens": 8,
        "experts": 4,
        "topk": 2,
        "hidden": 32,
        "intermediate": 64,
        "dtype_bytes": 2,
    }
    kernel = KernelSpec(
        KernelKind.VECTOR,
        ASCEND_HARDWARE.hardware_id,
        shape,
        dtype="bf16",
        variant=variant,
        launch=LaunchConfig(
            algorithm="test_source_bound_cann_moe_routing",
            grid=(16, 1, 1),
            block=(1, 1, 1),
            execution_variant=variant,
            parameters=(
                {"cann_moe_init_routing_mix_aiv_1_0": 1.0}
                if variant == "moe_init_routing" else (
                    {"cann_tiling_key": 20036.0}
                    if variant == "moe_finalize_routing" else {})),
        ),
        attributes={},
    )

    resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
    paths = {path.name: path for path in resource_input.memory_paths}
    assert {
        node.resource_role: node.bytes
        for node in paths["mte2_read"].nodes
    } == {
        "mte2": expected_read_bytes,
        "l2_cache": expected_read_bytes,
        "dram": expected_read_bytes,
    }
    assert {
        node.resource_role: node.bytes
        for node in paths["mte3_write"].nodes
    } == {
        "mte3": expected_write_bytes,
        "l2_cache": expected_write_bytes,
        "dram": expected_write_bytes,
    }
    assert resource_input.demand_per_resource["l2_cache"] == (
        expected_read_bytes + expected_write_bytes)
    assert resource_input.demand_per_resource["dram"] == (
        expected_read_bytes + expected_write_bytes)
    assert resource_input.demand_per_resource["mte3"] == expected_write_bytes
    if variant == "moe_finalize_routing":
        assert resource_input.demand_per_resource["compute_vector"] == (
            3.0 * 8 * 2 * 32)
    if variant == "moe_init_routing":
        assert resource_input.launch_task_kind == "mix_aiv"
        assert (
            "moe_init_routing_internal_read_traffic_evidence_pending"
            in resource_input.limitations)
    else:
        assert (
            "moe_init_routing_internal_read_traffic_evidence_pending"
            not in resource_input.limitations)


