def test_key1003_e512_one_worker_prices_closed_source_tail():
    with open(
            "microbench/ascend_910b/references/"
            "moe_compute_expert_tokens_key1003_phase_services_cann_8_5_1.json"
    ) as stream:
        phase_evidence = json.load(stream)
    with open(
            "microbench/ascend_910b/references/"
            "moe_compute_expert_tokens_process_after_cann_8_5_1.json"
    ) as stream:
        process_after_evidence = json.load(stream)
    assert phase_evidence["production_or_evaluation_duration_consumed"] is False
    assert process_after_evidence[
        "production_or_evaluation_duration_consumed"] is False
    assert process_after_evidence["source_scope"]["experts"] == 512
    assert process_after_evidence["source_scope"]["used_input_workers"] == 1

    shape = {
        "tokens": 2,
        "experts": 512,
        "topk": 10,
        "hidden": 2048,
        "intermediate": 512,
        "dtype_bytes": 2,
    }
    launch = select_launch_config(
        "ascend_910b", KernelKind.VECTOR, shape, "bf16",
        "moe_compute_expert_tokens", {}, hardware=ASCEND_HARDWARE)
    kernel = KernelSpec(
        KernelKind.VECTOR,
        ASCEND_HARDWARE.hardware_id,
        shape,
        dtype="bf16",
        variant="moe_compute_expert_tokens",
        launch=launch,
        attributes={
            "tokens_per_expert": (0,) * 300 + (20,) + (0,) * 211,
        },
    )

    search = _cann_moe_compute_expert_tokens_search_service(
        kernel, ASCEND_HARDWARE)
    source = _cann_moe_compute_expert_tokens_source_service(
        kernel, ASCEND_HARDWARE)
    expected_tail_ns = math.fsum((
        2 * phase_evidence["scatter_mte3"]["service_time_ns"],
        phase_evidence["init_output_sync_all"]
        ["service_time_ns_by_payload_bytes_per_worker"]["2048"],
        phase_evidence["init_output_sync_all"]
        ["service_time_ns_by_payload_bytes_per_worker"]["32"],
        process_after_evidence["measurement"]["service_time_ns"],
    ))
    assert vector_predictor._CANN_MOE_COMPUTE_EXPERT_TOKENS_SCATTER_MTE3_NS == (
        phase_evidence["scatter_mte3"]["service_time_ns"])
    assert vector_predictor._CANN_MOE_COMPUTE_EXPERT_TOKENS_FIRST_SYNC_NS == (
        phase_evidence["init_output_sync_all"]
        ["service_time_ns_by_payload_bytes_per_worker"]["2048"])
    assert vector_predictor._CANN_MOE_COMPUTE_EXPERT_TOKENS_SECOND_SYNC_NS == (
        phase_evidence["init_output_sync_all"]
        ["service_time_ns_by_payload_bytes_per_worker"]["32"])
    assert vector_predictor._CANN_MOE_COMPUTE_EXPERT_TOKENS_PROCESS_AFTER_NS == (
        process_after_evidence["measurement"]["service_time_ns"])
    generic_rate = ASCEND_HARDWARE.resource_by_role(
        "compute_vector").service_rate_for_one_unit("generic")

    assert source is not None
    assert source.operations_by_worker[0] == pytest.approx(
        search.operations_by_worker[0] + expected_tail_ns * 1e-9 * generic_rate)
    assert source.operations_by_worker[1:] == search.operations_by_worker[1:]
    resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
    vector_demand, = resource_input.compute_demands
    assert vector_demand.service_demands == (source,)
    assert (
        "moe_compute_expert_tokens_scalar_control_work_evidence_pending"
        not in resource_input.limitations)
    assert (
        "moe_compute_expert_tokens_syncall_lowering_evidence_pending"
        not in resource_input.limitations)
    assert (
        "moe_compute_expert_tokens_write_transaction_evidence_pending"
        not in resource_input.limitations)


