    def test_cann_grouped_pipeline_reuses_base_m_invariant_b_service(self):
        common_shape = {
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
            "dtype_bytes": 2,
        }

        def build_kernel(tokens, counts):
            shape = dict(common_shape, tokens=tokens)
            launch = select_launch_config(
                ASCEND_HARDWARE.hardware_id,
                KernelKind.FUSED_MOE,
                shape,
                "bf16",
                "w2",
                {"launch_policy": "analytical_launch",
                 "expert_parallel_size": 1},
                hardware=ASCEND_HARDWARE,
            )
            return KernelSpec(
                KernelKind.FUSED_MOE,
                ASCEND_HARDWARE.hardware_id,
                shape,
                dtype="bf16",
                variant="w2",
                launch=launch,
                attributes={
                    "tokens_per_expert": counts,
                    "local_tokens_per_expert": counts,
                    "expert_parallel_size": 1,
                    "expert_rank": 0,
                    "owned_experts": tuple(range(len(counts))),
                    "expert_weight_tile_rows": None,
                },
            )

        base_m_128 = build_kernel(2048, (16384,) + (0,) * 127)
        base_m_32 = build_kernel(4, (32,) + (0,) * 127)

        assert dict(base_m_128.launch.tiling.tile_shape)["m"] == 128
        assert dict(base_m_32.launch.tiling.tile_shape)["m"] == 32
        input_128 = _resource_input_for(base_m_128, ASCEND_HARDWARE)
        input_32 = _resource_input_for(base_m_32, ASCEND_HARDWARE)
        services_128 = {
            demand.service
            for path in input_128.memory_paths
            for demand in path.access_class_demands}
        services_32 = {
            demand.service
            for path in input_32.memory_paths
            for demand in path.access_class_demands}

        assert any("operand_a" in service for service in services_128)
        assert any("operand_b" in service for service in services_128)
        assert not any("operand_a" in service for service in services_32)
        assert any("operand_b" in service for service in services_32)
        assert input_128.pipeline_plan is not None
        assert input_32.pipeline_plan is not None
        assert input_128.pipeline_plan.a_step_k_tiles == 4
        assert input_128.pipeline_plan.b_step_k_tiles == 4
        assert input_32.pipeline_plan.a_step_k_tiles == 28
        assert input_32.pipeline_plan.b_step_k_tiles == 4
        assert input_32.pipeline_plan.a1_buffer_slots == 2
        assert input_32.pipeline_plan.b1_buffer_slots == 2
        prediction_32 = PerformanceFormula(ASCEND_HARDWARE).predict_kernel(
            input_32)
        assert prediction_32.diagnostics.pipeline is not None
        assert prediction_32.diagnostics.pipeline.stage_service_s["load"] > 0.0
        for kernel in (base_m_128, base_m_32):
            resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
            assert resource_input.phase_ledger is not None
            assert resource_input.dependency_paths == ()
            tile_m = dict(kernel.launch.tiling.tile_shape)["m"]
            if tile_m == 128:
                assert resource_input.pipeline_plan is not None
                assert resource_input.support_level == "partial"
            elif tile_m == 32:
                assert resource_input.pipeline_plan is not None
                assert resource_input.support_level == "partial"
                assert (
                    "cann_grouped_matmul_uses_tile_class_analytical_envelope"
                    in resource_input.limitations)
            else:
                raise AssertionError(tile_m)

        base_m_48 = build_kernel(5, (40,) + (0,) * 127)
        assert dict(base_m_48.launch.tiling.tile_shape)["m"] == 48
        assert tuple(
            base_m_48.launch.parameters[name]
            for name in (
                "cann_depth_a1", "cann_depth_b1",
                "cann_step_ka", "cann_step_kb",
                "cann_step_m", "cann_step_n",
                "cann_db_l0a", "cann_db_l0b", "cann_db_l0c",
            )) == (40.0, 8.0, 20.0, 4.0, 1.0, 1.0, 2.0, 2.0, 1.0)
        input_48 = _resource_input_for(base_m_48, ASCEND_HARDWARE)
        assert input_48.pipeline_plan is not None
        assert input_48.pipeline_plan.a_step_k_tiles == 20
        assert input_48.pipeline_plan.b_step_k_tiles == 4
        assert input_48.pipeline_plan.a1_buffer_slots == 2
        assert input_48.pipeline_plan.b1_buffer_slots == 2
        assert input_48.support_level == "partial"
        assert (
            "cann_grouped_matmul_uses_tile_class_analytical_envelope"
            in input_48.limitations)

        unsupported_m48 = build_kernel(6, (48,) + (0,) * 127)
        unsupported_input_48 = _resource_input_for(
            unsupported_m48, ASCEND_HARDWARE)
        assert unsupported_input_48.pipeline_plan is None
        assert unsupported_input_48.support_level == "aggregate_only"

    def test_cann_grouped_k2880_uses_resident_strided_b_service(self):
        def build_kernel(hidden, intermediate):
            shape = {
                "tokens": 2048,
                "experts": 32,
                "topk": 4,
                "hidden": hidden,
                "intermediate": intermediate,
                "dtype_bytes": 2,
            }
            counts = (256,) * 32
            launch = select_launch_config(
                ASCEND_HARDWARE.hardware_id,
                KernelKind.FUSED_MOE,
                shape,
                "bf16",
                "w2",
                {"launch_policy": "analytical_launch",
                 "expert_parallel_size": 1},
                hardware=ASCEND_HARDWARE,
            )
            return KernelSpec(
                KernelKind.FUSED_MOE,
                ASCEND_HARDWARE.hardware_id,
                shape,
                dtype="bf16",
                variant="w2",
                launch=launch,
                attributes={
                    "tokens_per_expert": counts,
                    "local_tokens_per_expert": counts,
                    "expert_parallel_size": 1,
                    "expert_rank": 0,
                    "owned_experts": tuple(range(len(counts))),
                    "expert_weight_tile_rows": None,
                },
            )

        kernel = build_kernel(2880, 2880)
        control = build_kernel(2048, 768)
        service_name = (
            "cann_grouped_moe_operand_b_k2880_stride_l2_hit")
        generic_name = "cann_grouped_moe_operand_b_l2_hit"
        services = fused_moe_predictor._cann_grouped_operand_services(
            kernel, ASCEND_HARDWARE)
        control_services = fused_moe_predictor._cann_grouped_operand_services(
            control, ASCEND_HARDWARE)

        assert service_name in services
        assert generic_name not in services
        assert generic_name in control_services
        assert service_name not in control_services
        resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
        typed = {
            demand.service: demand.logical_bytes
            for path in resource_input.memory_paths
            for demand in path.access_class_demands}
        assert typed[service_name] > 0.0
        assert generic_name not in typed

        contiguous_capacity = next(
            service.logical_byte_capacity_per_s
            for service in ASCEND_HARDWARE.memory_access_class_services
            if service.service == generic_name)
        contiguous_hardware = copy.deepcopy(ASCEND_HARDWARE)
        contiguous_hardware.memory_access_class_services = tuple(
            dataclasses.replace(
                service,
                logical_byte_capacity_per_s=contiguous_capacity,
            ) if service.service == service_name else service
            for service in contiguous_hardware.memory_access_class_services)
        strided_prediction = PerformanceFormula(
            ASCEND_HARDWARE).predict_kernel(resource_input)
        contiguous_input = _resource_input_for(kernel, contiguous_hardware)
        contiguous_prediction = PerformanceFormula(
            contiguous_hardware).predict_kernel(contiguous_input)

        assert strided_prediction.t_total_ns > contiguous_prediction.t_total_ns
        assert strided_prediction.diagnostics.pipeline.stage_service_s[
            "load"] > contiguous_prediction.diagnostics.pipeline.stage_service_s[
                "load"]

