    def test_cann_grouped_entry_metadata_pair_precedes_each_projection_once(
            self):
        shape = {
            "tokens": 2, "experts": 8, "topk": 2,
            "hidden": 6144, "intermediate": 16384, "dtype_bytes": 2,
        }
        counts = (0, 1, 0, 0, 1, 0, 2, 0)
        service_s = ASCEND_HARDWARE.\
            aic_grouped_matmul_entry_metadata_pair_time_ns(
                "bf16", 24, "grouped_matmul", 6144, 16384) * 1e-9
        for role in ("w1", "w2"):
            launch = select_launch_config(
                ASCEND_HARDWARE.hardware_id, KernelKind.FUSED_MOE, shape,
                "bf16", role,
                {"launch_policy": "analytical_launch",
                 "expert_parallel_size": 1}, hardware=ASCEND_HARDWARE)
            kernel = KernelSpec(
                KernelKind.FUSED_MOE, ASCEND_HARDWARE.hardware_id, shape,
                dtype="bf16", variant=role, launch=launch,
                attributes={
                    "tokens_per_expert": counts,
                    "local_tokens_per_expert": counts,
                    "expert_parallel_size": 1, "expert_rank": 0,
                    "owned_experts": tuple(range(8)),
                    "expert_weight_tile_rows": None,
                })
            resource_input = _resource_input_for(kernel, ASCEND_HARDWARE)
            envelope = resource_input.pipeline_plan
            assert envelope is not None
            assert sum(
                sum(worker_counts) for worker_counts in envelope.counts_by_worker
            ) > envelope.worker_count
            assert ASCEND_HARDWARE.\
                aic_grouped_matmul_entry_metadata_pair_supports(
                    envelope.dtype, envelope.worker_count,
                    envelope.source_kind, envelope.projection_k,
                    envelope.projection_n)
