        mixed_counts = ((1, 1),) + ((0, 0),) * (
            envelope.worker_count - 1)
        mixed_runs = (((0, 1), (1, 1)),) + ((),) * (
            envelope.worker_count - 1)
        mixed_envelope = dataclasses.replace(
            envelope, counts_by_worker=mixed_counts,
            source_class_runs_by_worker=mixed_runs)
