    def test_bm16_early_exit_padding_has_no_activation_or_output_traffic(
            self):
        import src.kernel.predictors.fused_moe as fused_moe_predictor

        counts = (1, 1, 1, 1, 0, 0, 0, 0)
        block_m, block_n, block_k = 16, 32, 64
        # The standalone runner allocates TOK*TOPK + E*(BM-1) routing slots.
        # Only four BM tiles contain routes; the other four return before any
        # operand load or output store.
        routing_storage_rows = sum(counts) + len(counts) * (block_m - 1)
        launch = LaunchConfig(
            algorithm="test_metax_fused_moe_bm16_early_exit",
            grid=(math.ceil(routing_storage_rows / block_m), 1, 1),
            block=(256, 1, 1),
            tiling=TilingSpec(
                tile_shape={"m": block_m, "n": block_n, "k": block_k},
                num_kv_splits=None,
            ),
            parameters={
                "group_size_m": 1,
                "padded_rows": routing_storage_rows,
                "mte2_tile_bytes": 0,
                "weight_tile_rows": 0,
                "operand_replay_a": 1,
                "operand_replay_b": 1,
            },
            execution_variant="w1",
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            METAX_HARDWARE.hardware_id,
            {
                "tokens": 2,
                "experts": 8,
                "topk": 2,
                "hidden": 64,
                "intermediate": 16,
            },
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(len(counts))),
                "expert_weight_tile_rows": None,
            },
        )
        l2_bytes, dram_bytes, _ = fused_moe_predictor._gpu_traffic(
            kernel, METAX_HARDWARE)

        active_expert_weight = (
            4 * block_k * block_n * 2)
        populated_activation = sum(counts) * block_k * 2
        populated_output = sum(counts) * block_n * 2
        assert l2_bytes == (
            populated_activation + active_expert_weight + populated_output)
        compulsory_activation = 2 * block_k * 2
        assert dram_bytes == (
            compulsory_activation
            + active_expert_weight
            + populated_output)

    def test_bm16_weight_requests_follow_populated_m_and_full_n_tiles(self):
        import src.kernel.predictors.fused_moe as fused_moe_predictor

        counts = (17, 1, 0, 0, 0, 0, 0, 0)
        block_m, block_n, block_k = 16, 32, 64
        routing_storage_rows = sum(counts) + len(counts) * (block_m - 1)
        n_tiles = 2
        launch = LaunchConfig(
            algorithm="test_metax_fused_moe_bm16_program_requests",
            grid=(math.ceil(routing_storage_rows / block_m) * n_tiles, 1, 1),
            block=(256, 1, 1),
            tiling=TilingSpec(
                tile_shape={"m": block_m, "n": block_n, "k": block_k},
                num_kv_splits=None,
            ),
            parameters={
                "group_size_m": 1,
                "padded_rows": routing_storage_rows,
                "mte2_tile_bytes": 0,
                "weight_tile_rows": 0,
                "operand_replay_a": 1,
                "operand_replay_b": 1,
            },
            execution_variant="w1",
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            METAX_HARDWARE.hardware_id,
            {
                "tokens": 9,
                "experts": 8,
                "topk": 2,
                "hidden": 64,
                "intermediate": 17,
            },
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(len(counts))),
                "expert_weight_tile_rows": None,
            },
        )

        l2_bytes, dram_bytes, _ = fused_moe_predictor._gpu_traffic(
            kernel, METAX_HARDWARE)

        routed_rows = sum(counts)
        projection_n = 2 * 17
        populated_m_tiles = 3
        activation_l2 = routed_rows * block_k * n_tiles * 2
        weight_l2 = (
            populated_m_tiles * block_k * n_tiles * block_n * 2)
        output_l2 = routed_rows * projection_n * 2
        assert l2_bytes == activation_l2 + weight_l2 + output_l2
        assert dram_bytes == (
            9 * block_k * 2
            + 2 * block_k * projection_n * 2
            + output_l2)









