    @pytest.mark.parametrize("hardware", (HARDWARE, METAX_HARDWARE))
    def test_gpu_moe_has_no_unproven_physical_worker_pipeline(
            self, hardware):
        shape = {
            "tokens": 128,
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
        }
        counts = (8,) * shape["experts"]
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w1",
            {
                "tokens_per_expert": counts,
                "expert_parallel_size": 1,
            },
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(len(counts))),
                "expert_weight_tile_rows": None,
            },
        )

        resource_input = _resource_input_for(kernel, hardware)
        projection_n = 2 * shape["intermediate"]
        compulsory = (
            shape["tokens"] * shape["hidden"]
            + shape["experts"] * shape["hidden"] * projection_n
            + sum(counts) * projection_n
        ) * 2

        if hardware.hardware_id == "nvidia_a800":
            assert isinstance(
                resource_input.pipeline_plan,
                GpuGroupedGemmPipelineEnvelopeDemand)
        elif resource_input.pipeline_plan is None:
            pass
        else:
            # A MetaX launch may only carry a pipeline that one of the
            # measured compiled-program mechanisms established.
            assert isinstance(
                resource_input.pipeline_plan,
                MetaxGroupedOperandPipelineDemand)
            assert resource_input.pipeline_plan.mechanism_key in (
                METAX_GROUPED_OPERAND_PIPELINE_MECHANISM_KEYS)
        assert resource_input.support_level == "aggregate_only"
        assert resource_input.demand_per_resource["dram"] == compulsory
        assert (
            "moe_physical_worker_assignment_unavailable"
            in resource_input.limitations)
        assert (
            "moe_l2_residency_order_unavailable"
            in resource_input.limitations)
        if hardware.has_memory_access_class_service(
                "grouped_fused_moe_operand_read"):
            operand_path, = tuple(
                path for path in resource_input.memory_paths
                if path.name == "operand_read")
            assert len(operand_path.access_class_demands) == 1
            assert tuple(path.name for path in resource_input.memory_paths) == (
                "operand_read", "output_write")
            assert (
                "moe_gather_service_class_not_separated"
                not in resource_input.limitations)
        else:
            # MetaX's retained gather services predate the active runtime
            # resolver and match none of its tile signatures; the predictor
            # must leave the paths untyped rather than fabricate a demand.
            activation_path, = tuple(
                path for path in resource_input.memory_paths
                if path.name == "activation_read")
            assert activation_path.access_class_demands == ()
            assert tuple(path.name for path in resource_input.memory_paths) == (
                "activation_read", "weight_read", "output_write")
            assert (
                "moe_gather_service_class_not_separated"
                in resource_input.limitations)
        assert sum(
            path.nodes[0].bytes for path in resource_input.memory_paths
        ) == resource_input.demand_per_resource["l2_cache"]
        assert sum(
            node.bytes
            for path in resource_input.memory_paths
            for node in path.nodes
            if node.resource_role == "dram"
        ) == resource_input.demand_per_resource["dram"]


    @pytest.mark.parametrize("replay_fraction", (None, 0.25))
    def test_metax_grouped_operand_service_applies_combined_refetch_and_time(
            self, replay_fraction):
        shape = {
            "tokens": 2048,
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
        }
        counts = (128,) * shape["experts"]
        attributes = {
            "tokens_per_expert": counts,
            "expert_parallel_size": 1,
        }
        hardware = HWSpec("configs/hardware/metax_c500.yaml")
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w1",
            attributes,
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(shape["experts"])),
                "expert_weight_tile_rows": None,
            },
        )
        baseline = fused_moe_predictor._gpu_traffic_components(
            kernel, hardware)
        capacity = 500e9
        hardware.memory_access_class_services = (
            MemoryAccessClassService(
                service="grouped_fused_moe_operand_read",
                access_kind="read",
                ingress_resource_role="l2_cache",
                signature=(
                    fused_moe_predictor._gpu_grouped_operand_signature(
                        kernel)),
                scope="full_chip",
                logical_byte_capacity_per_s=capacity,
                evidence_ref="independent_grouped_operand_probe#combined",
                replay_to_dram_fraction=replay_fraction,
            ),
        )

        resource_input = _resource_input_for(kernel, hardware)
        paths = {path.name: path for path in resource_input.memory_paths}
        operand_nodes = {
            node.resource_role: node.bytes
            for node in paths["operand_read"].nodes}
        if replay_fraction is None:
            expected_activation_dram = baseline.activation_dram_read_bytes
            expected_weight_dram = baseline.weight_dram_read_bytes
        else:
            expected_activation_dram = (
                baseline.activation_compulsory_read_bytes
                + replay_fraction * (
                    baseline.activation_l2_read_bytes
                    - baseline.activation_compulsory_read_bytes))
            expected_weight_dram = (
                baseline.weight_compulsory_read_bytes
                + replay_fraction * (
                    baseline.weight_l2_read_bytes
                    - baseline.weight_compulsory_read_bytes))

        assert tuple(paths) == ("operand_read", "output_write")
        assert operand_nodes == {
            "l2_cache": (
                baseline.activation_l2_read_bytes
                + baseline.weight_l2_read_bytes),
            "dram": expected_activation_dram + expected_weight_dram,
        }
        demand, = paths["operand_read"].access_class_demands
        assert demand.signature.operand_role == "combined"
        assert demand.service == "grouped_fused_moe_operand_read"
        assert (
            "moe_l2_residency_order_unavailable" in resource_input.limitations
        ) is (replay_fraction is None)

        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)
        diagnostics = prediction.diagnostics.memory_access_classes
        assert len(diagnostics) == 1
        assert prediction.t_per_group[
            "memory_access:grouped_fused_moe_operand_read"] == pytest.approx(
                (
                    baseline.activation_l2_read_bytes
                    + baseline.weight_l2_read_bytes
                ) / capacity)

    def test_a800_grouped_operand_service_sums_exact_active_row_signatures(
            self):
        shape = {
            "tokens": 2048,
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
        }
        counts = (65, 63) + (128,) * 125 + (256,)
        attributes = {
            "tokens_per_expert": counts,
            "expert_parallel_size": 1,
        }
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w1",
            attributes,
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(shape["experts"])),
                "expert_weight_tile_rows": None,
            },
        )
        tile_m, tile_n, tile_k = (
            launch.tiling.tile_shape[name] for name in ("m", "n", "k"))
        assert tile_m == 64
        capacity = 2.0e12
        hardware.memory_access_class_services = tuple(
            MemoryAccessClassService(
                service="grouped_fused_moe_operand_read",
                access_kind="read",
                ingress_resource_role="l2_cache",
                signature=MemoryAccessClassSignature(
                    access_class="grouped_fused_moe_operand_read",
                    dtype="bf16",
                    tile_m=tile_m,
                    tile_k=tile_k,
                    logical_row_bytes=(
                        active_rows * tile_k + tile_k * tile_n) * 2,
                    operand_role="combined",
                    tile_n=tile_n,
                    group_size_m=8,
                ),
                scope="full_chip",
                logical_byte_capacity_per_s=capacity,
                evidence_ref=(
                    "independent_masked_row_probe#"
                    f"active_rows={active_rows}"),
            )
            for active_rows in range(1, tile_m + 1))

        resource_input = _resource_input_for(kernel, hardware)
        operand_path, = tuple(
            path for path in resource_input.memory_paths
            if path.name == "operand_read")
        assert tuple(
            demand.signature.logical_row_bytes
            for demand in operand_path.access_class_demands) == (
                (1 * tile_k + tile_k * tile_n) * 2,
                (63 * tile_k + tile_k * tile_n) * 2,
                (64 * tile_k + tile_k * tile_n) * 2,
            )
        traffic = fused_moe_predictor._gpu_traffic_components(
            kernel, hardware)
        expected_bytes = (
            traffic.activation_l2_read_bytes
            + traffic.weight_l2_read_bytes)
        assert math.fsum(
            demand.logical_bytes
            for demand in operand_path.access_class_demands
        ) == expected_bytes
        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)
        assert prediction.t_per_group[
            "memory_access:grouped_fused_moe_operand_read"] == pytest.approx(
                expected_bytes / capacity)

    def test_a800_bm64_separates_l2_hits_from_strided_weight_misses(self):
        shape = {
            "tokens": 2048,
            "experts": 128,
            "topk": 8,
            "hidden": 4096,
            "intermediate": 1536,
        }
        counts = (128,) * shape["experts"]
        attributes = {
            "tokens_per_expert": counts,
            "expert_parallel_size": 1,
        }
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w1",
            attributes,
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(shape["experts"])),
                "expert_weight_tile_rows": None,
            },
        )
        assert tuple(
            launch.tiling.tile_shape[name] for name in ("m", "n", "k")
        ) == (64, 64, 32)

        traffic = fused_moe_predictor._gpu_traffic_components(
            kernel, hardware)
        resource_input = _resource_input_for(kernel, hardware)
        operand_path, = tuple(
            path for path in resource_input.memory_paths
            if path.name == "operand_read")
        demands = {
            demand.signature.operand_role: demand
            for demand in operand_path.access_class_demands}
        assert set(demands) == {"combined", "weight"}
        assert {
            demand.service for demand in demands.values()
        } == {
            "grouped_fused_moe_operand_pipeline",
            "grouped_fused_moe_weight_overlapped_dram_miss_pipeline",
        }
        expected_hit_bytes = (
            traffic.activation_l2_read_bytes
            + traffic.weight_l2_read_bytes
            - traffic.activation_dram_read_bytes
            - traffic.weight_dram_read_bytes)
        assert demands["combined"].logical_bytes == expected_hit_bytes
        assert demands["weight"].logical_bytes == (
                traffic.weight_dram_read_bytes)
        assert math.fsum(
            demand.logical_bytes for demand in demands.values()
        ) <= traffic.activation_l2_read_bytes + traffic.weight_l2_read_bytes

        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)
        services = {
            (service.service, service.signature): service
            for service in hardware.memory_access_class_services
            if service.service in {
                "grouped_fused_moe_operand_pipeline",
                "grouped_fused_moe_weight_overlapped_dram_miss_pipeline",
            }
        }
        assert prediction.t_per_group[
            "memory_access:grouped_fused_moe_operand_pipeline"
        ] == pytest.approx(
            expected_hit_bytes
            / services[
                (demands["combined"].service,
                 demands["combined"].signature)
            ].logical_byte_capacity_per_s)
        assert prediction.t_per_group[
            "memory_access:"
            "grouped_fused_moe_weight_overlapped_dram_miss_pipeline"
        ] == pytest.approx(
            traffic.weight_dram_read_bytes
            / services[
                (demands["weight"].service,
                 demands["weight"].signature)
            ].logical_byte_capacity_per_s)

