    def test_metax_bm32_grouped_operand_pipeline_binds_serial_rounds(self):
        shape = {
            "tokens": 35,
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
        }
        global_counts = (3,) * 24 + (2,) * 104
        local_counts = global_counts[:64] + (0,) * 64
        hardware = METAX_HARDWARE
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w1",
            {
                "tokens_per_expert": global_counts,
                "expert_parallel_size": 2,
            },
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": global_counts,
                "local_tokens_per_expert": local_counts,
                "expert_parallel_size": 2,
                "expert_rank": 0,
                "owned_experts": tuple(range(64)),
                "expert_weight_tile_rows": None,
            },
        )

        resource_input = _resource_input_for(kernel, hardware)
        plan = resource_input.pipeline_plan
        assert isinstance(plan, MetaxGroupedOperandPipelineDemand)
        assert plan.active_ctas == 64 * (
            2 * shape["intermediate"] // 64)
        assert plan.k_tiles == shape["hidden"] // 128

        mechanism = hardware.metax_fused_moe_bm32_operand_pipeline
        resident_ctas = (
            hardware.num_compute_units * mechanism["resident_ctas_per_ap"])
        waves = math.ceil(plan.active_ctas / resident_ctas)
        dram = hardware.resource_by_role("dram")
        dram_capacity = dram.effective_capacity(
            resource_input.active_units,
            sm_freq_hz=hardware.nominal_sm_freq_hz,
            dram_freq_hz=hardware.nominal_dram_freq_hz)
        dram_round_ns = (
            plan.dram_read_bytes / plan.k_tiles / waves / dram_capacity * 1e9
            + hardware.dram_latency_ns / mechanism["pipeline_depth"])
        round_ns = max(
            mechanism["local_k_round_interval_ns"], dram_round_ns)
        empty_waves = math.ceil(
            (resource_input.grid_size - plan.active_ctas)
            / hardware.num_compute_units)
        expected_pipeline_ns = (
            waves * (mechanism["fixed_span_ns"] + plan.k_tiles * round_ns)
            + empty_waves * mechanism["empty_wave_slot_ns"])
        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)
        assert prediction.diagnostics.pipeline.execution_time_s * 1e9 == (
            pytest.approx(expected_pipeline_ns))
        # The pipeline still sets the bottleneck; the launch additionally pays
        # its measured, geometry-independent CTA dispatch cost.
        assert prediction.t_total_ns == pytest.approx(
            expected_pipeline_ns
            + hardware.cta_dispatch_cost_ns(resource_input.grid_size))
        assert prediction.bottleneck_group == "pipeline"

