    def test_metax_grouped_operand_pipeline_keys_are_signature_disjoint(self):
        """No two measured mechanisms may claim the same tile signature."""

        hardware = METAX_HARDWARE
        signatures = []
        for key in METAX_GROUPED_OPERAND_PIPELINE_MECHANISM_KEYS:
            mechanism = getattr(hardware, key)
            if mechanism is None:
                continue
            signatures.append((
                mechanism["dtype"], mechanism["tile_m"], mechanism["tile_n"],
                mechanism["tile_k"], mechanism["group_size_m"],
                mechanism["threads_per_cta"], mechanism["num_warps"],
                mechanism["num_stages"]))
        assert len(signatures) == len(set(signatures))

    def test_metax_operand_pipeline_needs_its_compiled_program_facts(self):
        """A launch that does not name its program cannot match a mechanism."""

        shape = {
            "tokens": 35,
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
        }
        global_counts = (3,) * 24 + (2,) * 104
        local_counts = global_counts[:64] + (0,) * 64
        hardware = METAX_HARDWARE
        attributes = {
            "tokens_per_expert": global_counts,
            "local_tokens_per_expert": local_counts,
            "expert_parallel_size": 2,
            "expert_rank": 0,
            "owned_experts": tuple(range(64)),
            "expert_weight_tile_rows": None,
        }
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w1",
            {
                "tokens_per_expert": global_counts,
                "expert_parallel_size": 2,
            },
            hardware=hardware,
        )
        matched = KernelSpec(
            KernelKind.FUSED_MOE, hardware.hardware_id, shape, dtype="bf16",
            variant="w1", launch=launch, attributes=attributes)
        plan = _resource_input_for(matched, hardware).pipeline_plan
        assert isinstance(plan, MetaxGroupedOperandPipelineDemand)

        # Same tile, threads and dynamic shared memory, different compiled
        # program: no mechanism may claim it.
        parameters = dict(launch.parameters)
        parameters["num_warps"] = parameters["num_warps"] + 4.0
        other_program = KernelSpec(
            KernelKind.FUSED_MOE, hardware.hardware_id, shape, dtype="bf16",
            variant="w1",
            launch=dataclasses.replace(launch, parameters=parameters),
            attributes=attributes)
        assert _resource_input_for(
            other_program, hardware).pipeline_plan is None

        # A launch that records no compiled-program facts at all is likewise
        # unmatchable rather than matched by tile shape alone.
        anonymous = dict(launch.parameters)
        del anonymous["num_warps"]
        del anonymous["num_stages"]
        unnamed = KernelSpec(
            KernelKind.FUSED_MOE, hardware.hardware_id, shape, dtype="bf16",
            variant="w1",
            launch=dataclasses.replace(launch, parameters=anonymous),
            attributes=attributes)
        assert _resource_input_for(unnamed, hardware).pipeline_plan is None

