    def test_a800_bm16_prices_source_ordered_empty_cta_tail(self):
        shape = {
            "tokens": 2,
            "experts": 512,
            "topk": 10,
            "hidden": 2048,
            "intermediate": 512,
        }
        counts = (1,) * 20 + (0,) * (shape["experts"] - 20)
        attributes = {
            "tokens_per_expert": counts,
            "expert_parallel_size": 1,
        }
        hardware = HWSpec("configs/hardware/nvidia_a800.yaml")
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            "w2",
            attributes,
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w2",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(shape["experts"])),
                "expert_weight_tile_rows": None,
            },
        )

        resource_input = _resource_input_for(kernel, hardware)
        plan = resource_input.pipeline_plan
        assert isinstance(plan, GpuGroupedGemmPipelineEnvelopeDemand)
        assert plan.active_ctas == 1280
        assert resource_input.grid_size == 30848

        prediction = PerformanceFormula(hardware).predict_kernel(
            resource_input)
        pipeline = prediction.diagnostics.pipeline
        resident_ctas = (
            hardware.num_compute_units
            * hardware.grouped_gemm_tile_pipeline["resident_ctas_per_sm"])
        waves = math.ceil(plan.active_ctas / resident_ctas)
        active_wave_ns = (
            pipeline.stage_service_s["dram_service_plus_hidden_latency"]
            * 1e9 / waves)
        tail_rounds = math.ceil(
            (resource_input.grid_size - plan.active_ctas)
            / hardware.num_compute_units)
        expected_tail_ns = (
            tail_rounds
            * hardware.grouped_gemm_tile_pipeline["empty_tail_round_ns"])
        assert pipeline.stage_service_s["empty_cta_tail"] * 1e9 == (
            pytest.approx(expected_tail_ns))
        assert pipeline.execution_time_s * 1e9 == pytest.approx(
            hardware.grouped_gemm_tile_pipeline["fixed_span_ns"]
            + active_wave_ns
            + max((waves - 1) * active_wave_ns, expected_tail_ns))
        assert "gpu_grouped_gemm/empty_cta_tail" in pipeline.critical_path

