    @pytest.mark.parametrize(
        ("tokens", "expected_tile_m", "expected_replay"),
        (
            (64, 32, 1.0),
            (128, 64, 2.0),
            (2048, 128, 1.0),
        ))
    def test_metax_operand_replay_is_an_explicit_launch_fact(
            self, tokens, expected_tile_m, expected_replay):
        shape = {
            "tokens": tokens, "experts": 128, "topk": 8,
            "hidden": 2048, "intermediate": 768,
        }
        attributes = {
            "tokens_per_expert": (tokens * 8 // 128,) * 128,
            "expert_parallel_size": 1,
        }
        metax = select_launch_config(
            METAX_HARDWARE.hardware_id, KernelKind.FUSED_MOE,
            shape, "bf16", "w1", attributes, hardware=METAX_HARDWARE)
        a800 = select_launch_config(
            HARDWARE.hardware_id, KernelKind.FUSED_MOE,
            shape, "bf16", "w1", attributes, hardware=HARDWARE)

        assert metax.tiling.tile_shape["m"] == expected_tile_m
        assert metax.parameters["operand_replay_a"] == expected_replay
        assert metax.parameters["operand_replay_b"] == expected_replay
        assert a800.parameters["operand_replay_a"] == 1.0
        assert a800.parameters["operand_replay_b"] == 1.0

        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            METAX_HARDWARE.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=metax,
            attributes={
                "tokens_per_expert": attributes["tokens_per_expert"],
                "local_tokens_per_expert": attributes["tokens_per_expert"],
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(shape["experts"])),
                "expert_weight_tile_rows": None,
            },
        )
        # The retained access-class services predate the active runtime
        # resolver and match none of its tile signatures; the predictor must
        # leave the signature untyped instead of fabricating a service.
        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        assert all(
            not path.access_class_demands
            for path in resource_input.memory_paths)
        assert "moe_gather_service_class_not_separated" in (
            resource_input.limitations)
        prediction = PerformanceFormula(METAX_HARDWARE).predict_kernel(
            resource_input)
        assert prediction.t_total_s > 0.0

    @pytest.mark.parametrize("variant", ("w1", "w2"))
    def test_metax_bm32_fused_moe_uses_only_exact_mma_occupancy(
            self, variant):
        shape = {
            "tokens": 35,
            "experts": 128,
            "topk": 8,
            "hidden": 2048,
            "intermediate": 768,
        }
        global_counts = (3,) * 24 + (2,) * 104
        local_counts = global_counts[:64] + (0,) * 64
        selection_attributes = {
            "tokens_per_expert": global_counts,
            "expert_parallel_size": 2,
        }
        launch = select_launch_config(
            METAX_HARDWARE.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            variant,
            selection_attributes,
            hardware=METAX_HARDWARE,
        )
        assert launch.tiling.tile_shape == {"m": 32, "n": 64, "k": 128}
        assert launch.block_size == 256
        assert launch.grid_size >= METAX_HARDWARE.num_compute_units
        assert launch.parameters["dynamic_shared_memory_bytes"] == 49152.0
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            METAX_HARDWARE.hardware_id,
            shape,
            dtype="bf16",
            variant=variant,
            launch=launch,
            attributes={
                "tokens_per_expert": global_counts,
                "local_tokens_per_expert": local_counts,
                "expert_parallel_size": 2,
                "expert_rank": 0,
                "owned_experts": tuple(range(64)),
                "expert_weight_tile_rows": None,
            },
        )
        resource_input = _resource_input_for(kernel, METAX_HARDWARE)
        tensor, = tuple(
            demand for demand in resource_input.compute_demands
            if demand.resource_role == "compute_tensor")
        occupancy = METAX_HARDWARE.metax_fused_moe_bm32_bf16_mma_occupancy
        assert tensor.schedule_efficiency == pytest.approx(
            resource_input.eta * resource_input.wave_efficiency
            * occupancy["flops_per_ap_cycle"]
            / occupancy["architecture_peak_flops_per_ap_cycle"])

        non_bm32_shape = {**shape, "tokens": 32}
        non_bm32_counts = (2,) * 128
        non_bm32_launch = select_launch_config(
            METAX_HARDWARE.hardware_id,
            KernelKind.FUSED_MOE,
            non_bm32_shape,
            "bf16",
            variant,
            {
                "tokens_per_expert": non_bm32_counts,
                "expert_parallel_size": 2,
            },
            hardware=METAX_HARDWARE,
        )
        assert non_bm32_launch.tiling.tile_shape["m"] == 16
        non_bm32_kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            METAX_HARDWARE.hardware_id,
            non_bm32_shape,
            dtype="bf16",
            variant=variant,
            launch=non_bm32_launch,
            attributes={
                "tokens_per_expert": non_bm32_counts,
                "local_tokens_per_expert": (2,) * 64 + (0,) * 64,
                "expert_parallel_size": 2,
                "expert_rank": 0,
                "owned_experts": tuple(range(64)),
                "expert_weight_tile_rows": None,
            },
        )
        non_bm32_input = _resource_input_for(
            non_bm32_kernel, METAX_HARDWARE)
        non_bm32_tensor, = tuple(
            demand for demand in non_bm32_input.compute_demands
            if demand.resource_role == "compute_tensor")
        assert non_bm32_tensor.schedule_efficiency == pytest.approx(
            non_bm32_input.eta * non_bm32_input.wave_efficiency)


    @pytest.mark.parametrize("variant", ("w1", "w2"))
    def test_cann_moe_separates_tile_replay_reads_and_aic_output_writes(
            self, variant):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {
            "tokens": 130,
            "experts": 4,
            "topk": 2,
            "hidden": 288,
            "intermediate": 144,
        }
        counts = (129, 128, 3, 0)
        launch = select_launch_config(
            hardware.hardware_id,
            KernelKind.FUSED_MOE,
            shape,
            "bf16",
            variant,
            {"launch_policy": "analytical_launch", "expert_parallel_size": 1},
            hardware=hardware,
        )
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant=variant,
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(len(counts))),
                "expert_weight_tile_rows": None,
            },
        )

        resource_input, compulsory = create_predictor(
            kernel.kind).resource_input(kernel, hardware)
        routed_rows = sum(counts)
        if variant == "w1":
            projection_k = shape["hidden"]
            projection_n = 2 * shape["intermediate"]
        elif variant == "w2":
            projection_k = shape["intermediate"]
            projection_n = shape["hidden"]
        else:
            raise AssertionError(variant)
        element_bytes = 2
        n_tiles = math.ceil(projection_n / 256)
        populated_m_tiles = 4
        activation_read = (
            routed_rows * projection_k * n_tiles * element_bytes)
        weight_read = (
            populated_m_tiles * projection_k * projection_n * element_bytes)
        output = routed_rows * projection_n * element_bytes
        from src.kernel.predictors import fused_moe as fused_moe_predictor
        work = fused_moe_predictor._cann_grouped_matmul_work(kernel)
        residency = fused_moe_predictor._cann_grouped_operand_residency(
            kernel, work, hardware)
        dram_input = residency.dram_read_bytes
        paths = {path.name: path for path in resource_input.memory_paths}
        read_nodes = {
            node.resource_role: node.bytes
            for node in paths["mte2_read"].nodes}
        dram_read_nodes = {
            node.resource_role: node.bytes
            for node in paths["operand_dram_read"].nodes}
        write_nodes = {
            node.resource_role: node.bytes
            for node in paths["aic_output_l2_write"].nodes}

        assert set(paths) == {
            "mte2_read", "operand_dram_read", "aic_output_l2_write"}
        assert paths["mte2_read"].access_kind == "read"
        assert paths["operand_dram_read"].access_kind == "read"
        assert paths["aic_output_l2_write"].access_kind == "write"
        assert read_nodes == {"l2_cache": activation_read + weight_read}
        assert dram_read_nodes == {"dram": dram_input}
        assert write_nodes == {"l2_cache": output, "dram": output}
        assert resource_input.demand_per_resource["l2_cache"] == (
            activation_read + weight_read + output)
        assert resource_input.demand_per_resource["dram"] == (
            dram_input + output)
        assert compulsory == dram_input + output
        assert resource_input.demand_per_resource["mte3"] == 0.0
        assert all(resource_input.demand_per_resource[role] == 0.0 for role in (
            "l1_cache", "smem", "xbar"))
        assert (
            "aic_grouped_matmul_operand_replay_evidence_unavailable"
            not in resource_input.limitations)
        assert "aic_read_write_transaction_split_unavailable" in (
            resource_input.limitations)
        assert "aic_grouped_matmul_dram_residency_uses_source_order_lru" in (
            resource_input.limitations)
        assert "aic_output_writeback_dram_residency_unavailable" in (
            resource_input.limitations)
        assert "aic_store_fixpipe_tile_lifecycle_unavailable" in (
            resource_input.limitations)

        prediction = PerformanceFormula(hardware).predict_kernel(resource_input)
        diagnostics = {
            path.path_name: path
            for path in prediction.diagnostics.memory}
        assert set(diagnostics) == {
            "mte2_read", "operand_dram_read", "aic_output_l2_write"}
        assert diagnostics["mte2_read"].access_kind == "read"
        assert diagnostics["operand_dram_read"].access_kind == "read"
        assert diagnostics["aic_output_l2_write"].access_kind == "write"
        arbitration, = prediction.diagnostics.memory_arbitration
        assert arbitration.resource_role == "dram"
        assert arbitration.read_bytes == dram_input
        assert arbitration.write_bytes == output
        assert arbitration.schedule_status == "unavailable"

        roofline = create_predictor(kernel.kind).roofline(kernel, hardware)
        assert roofline.t_total_ns > 0.0

    def test_cann_moe_rejects_traffic_derived_residency_windows(self):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {
            "tokens": 8,
            "experts": 8,
            "topk": 2,
            "hidden": 4096,
            "intermediate": 14336,
        }
        counts = (2,) * shape["experts"]
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.FUSED_MOE, shape, "bf16", "w1",
            {"launch_policy": "analytical_launch", "expert_parallel_size": 1},
            hardware=hardware)
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(len(counts))),
                "expert_weight_tile_rows": (1.0,) * shape["experts"],
            },
        )

        with pytest.raises(
                ValueError, match="traffic-derived residency windows"):
            _resource_input_for(kernel, hardware)

    def test_cann_moe_rejects_non_conserving_single_rank_routing(
            self, monkeypatch):
        hardware = HWSpec("configs/hardware/ascend_910b.yaml")
        shape = {
            "tokens": 8,
            "experts": 4,
            "topk": 2,
            "hidden": 288,
            "intermediate": 144,
        }
        counts = (4,) * shape["experts"]
        launch = select_launch_config(
            hardware.hardware_id, KernelKind.FUSED_MOE, shape, "bf16", "w1",
            {"launch_policy": "analytical_launch", "expert_parallel_size": 1},
            hardware=hardware)
        kernel = KernelSpec(
            KernelKind.FUSED_MOE,
            hardware.hardware_id,
            shape,
            dtype="bf16",
            variant="w1",
            launch=launch,
            attributes={
                "tokens_per_expert": counts,
                "local_tokens_per_expert": counts,
                "expert_parallel_size": 1,
                "expert_rank": 0,
                "owned_experts": tuple(range(len(counts))),
                "expert_weight_tile_rows": None,
            },
        )
        monkeypatch.setattr(
            fused_moe_predictor,
            "_routing",
            lambda unused_kernel: (counts, (3, 4, 4, 4)),
        )

        with pytest.raises(ValueError, match=r"must conserve tokens\*topk"):
            _resource_input_for(kernel, hardware)

